CREATE OR REPLACE FUNCTION fixeo_private._bp12_touch_sla_policy()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  NEW.updated_at := pg_catalog.now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION fixeo_private._bp12_validate_sla_policy_site()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_site_enterprise uuid;
BEGIN
  IF NEW.site_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT es.enterprise_id
  INTO v_site_enterprise
  FROM public.enterprise_sites es
  WHERE es.id=NEW.site_id;

  IF v_site_enterprise IS NULL THEN
    RAISE EXCEPTION 'sla_policy_site_not_found';
  END IF;

  IF v_site_enterprise <> NEW.enterprise_id THEN
    RAISE EXCEPTION 'sla_policy_site_enterprise_mismatch';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION fixeo_private._bp15_validate_member_site_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_member_enterprise uuid;
  v_member_role text;
  v_member_status text;
  v_site_enterprise uuid;
BEGIN
  SELECT em.enterprise_id, em.role, em.status
  INTO v_member_enterprise, v_member_role, v_member_status
  FROM public.enterprise_members em
  WHERE em.id = NEW.member_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'enterprise_member_not_found';
  END IF;

  SELECT es.enterprise_id
  INTO v_site_enterprise
  FROM public.enterprise_sites es
  WHERE es.id = NEW.site_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'enterprise_site_not_found';
  END IF;

  IF v_member_enterprise <> NEW.enterprise_id
     OR v_site_enterprise <> NEW.enterprise_id
  THEN
    RAISE EXCEPTION 'enterprise_member_site_mismatch';
  END IF;

  IF v_member_role <> 'site_manager' THEN
    RAISE EXCEPTION 'member_role_not_site_manager';
  END IF;

  IF v_member_status <> 'active' THEN
    RAISE EXCEPTION 'member_not_active';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION fixeo_private._fixeo_can_access_enterprise_equipment_path(p_enterprise_id_text text, p_equipment_id_text text, p_manage boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_enterprise_id uuid;
  v_equipment_id uuid;
BEGIN
  BEGIN
    v_enterprise_id:=p_enterprise_id_text::uuid;
    v_equipment_id:=p_equipment_id_text::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    RETURN false;
  END;

  IF p_manage THEN
    RETURN fixeo_private._fixeo_can_manage_enterprise_equipment_id(v_enterprise_id,v_equipment_id);
  END IF;
  RETURN fixeo_private._fixeo_can_access_enterprise_equipment(v_enterprise_id,v_equipment_id);
END;
$function$

CREATE OR REPLACE FUNCTION fixeo_private._fixeo_generate_maintenance_request_v1(p_plan_id uuid, p_due_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_plan public.enterprise_maintenance_plans%ROWTYPE;
  v_enterprise_status text;
  v_site_status text;
  v_city text;
  v_sla_urgency text;
  v_policy_id uuid;
  v_policy_urgency text;
  v_target_minutes integer;
  v_request_id uuid;
  v_context_id uuid;
  v_request_sla_id uuid;
  v_started_at timestamptz;
  v_at_risk_at timestamptz;
  v_due_at timestamptz;
  v_dispatch jsonb;
BEGIN
  SELECT *
  INTO v_plan
  FROM public.enterprise_maintenance_plans p
  WHERE p.id=p_plan_id
  FOR UPDATE;

  IF NOT FOUND OR v_plan.status<>'active' THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','plan_not_active');
  END IF;

  SELECT ea.status
  INTO v_enterprise_status
  FROM public.enterprise_accounts ea
  WHERE ea.id=v_plan.enterprise_id
  FOR SHARE;

  IF v_enterprise_status<>'active' THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','enterprise_not_active');
  END IF;

  SELECT es.status,es.city
  INTO v_site_status,v_city
  FROM public.enterprise_sites es
  WHERE es.id=v_plan.site_id
    AND es.enterprise_id=v_plan.enterprise_id
  FOR SHARE;

  IF NOT FOUND OR v_site_status<>'active' THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','site_not_active');
  END IF;

  v_sla_urgency := CASE v_plan.urgency
    WHEN 'now' THEN 'urgent'
    WHEN 'urgent' THEN 'high'
    WHEN 'normale' THEN 'normal'
    ELSE 'normal'
  END;

  SELECT p.id,p.urgency,p.acceptance_target_minutes
  INTO v_policy_id,v_policy_urgency,v_target_minutes
  FROM public.enterprise_sla_policies p
  WHERE p.enterprise_id=v_plan.enterprise_id
    AND p.status='active'
    AND (p.site_id=v_plan.site_id OR p.site_id IS NULL)
    AND (p.urgency=v_sla_urgency OR p.urgency IS NULL)
  ORDER BY
    CASE WHEN p.site_id=v_plan.site_id THEN 0 ELSE 1 END,
    CASE WHEN p.urgency=v_sla_urgency THEN 0 ELSE 1 END
  LIMIT 1
  FOR SHARE;

  IF v_policy_id IS NULL THEN
    v_policy_urgency := v_sla_urgency;
    v_target_minutes := CASE v_sla_urgency
      WHEN 'urgent' THEN 15
      WHEN 'high' THEN 30
      WHEN 'normal' THEN 120
      WHEN 'low' THEN 240
      ELSE 120
    END;
  END IF;

  PERFORM pg_catalog.set_config('fixeo.enterprise_dispatch_deferred','on',true);

  INSERT INTO public.service_requests(
    service_category,city,description,urgency,client_profile_id,status
  )
  VALUES(
    v_plan.service_category,
    v_city,
    '[Maintenance préventive] '||v_plan.description,
    v_plan.urgency,
    NULL,
    'new'
  )
  RETURNING id,created_at
  INTO v_request_id,v_started_at;

  PERFORM pg_catalog.set_config('fixeo.enterprise_dispatch_deferred','off',true);

  v_started_at := COALESCE(v_started_at,now());

  INSERT INTO public.enterprise_request_context(
    enterprise_id,site_id,service_request_id,created_by
  )
  VALUES(
    v_plan.enterprise_id,
    v_plan.site_id,
    v_request_id,
    v_plan.created_by
  )
  RETURNING id INTO v_context_id;

  v_at_risk_at := v_started_at + (pg_catalog.make_interval(mins=>v_target_minutes)*0.75);
  v_due_at := v_started_at + pg_catalog.make_interval(mins=>v_target_minutes);

  INSERT INTO public.enterprise_request_sla(
    service_request_id,enterprise_id,site_id,policy_id,policy_urgency,
    request_urgency,acceptance_target_minutes,started_at,at_risk_at,due_at
  )
  VALUES(
    v_request_id,v_plan.enterprise_id,v_plan.site_id,v_policy_id,v_policy_urgency,
    v_plan.urgency,v_target_minutes,v_started_at,v_at_risk_at,v_due_at
  )
  RETURNING id INTO v_request_sla_id;

  v_dispatch := public.dispatch_enterprise_hybrid_v1(v_request_id);

  RETURN pg_catalog.jsonb_build_object(
    'ok',true,
    'service_request_id',v_request_id,
    'enterprise_request_context_id',v_context_id,
    'request_sla_id',v_request_sla_id,
    'dispatch',v_dispatch
  );

EXCEPTION WHEN OTHERS THEN
  PERFORM pg_catalog.set_config('fixeo.enterprise_dispatch_deferred','off',true);
  RAISE WARNING '[_fixeo_generate_maintenance_request_v1] % %',SQLSTATE,SQLERRM;
  RETURN pg_catalog.jsonb_build_object('ok',false,'reason','internal_error');
END;
$function$

CREATE OR REPLACE FUNCTION fixeo_private._fixeo_is_admin()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_caller_id uuid;
  v_result    boolean;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN false;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM   public.users u
    WHERE  u.id   = v_caller_id
      AND  u.role = 'admin'
  ) INTO v_result;

  RETURN COALESCE(v_result, false);
END;
$function$

CREATE OR REPLACE FUNCTION fixeo_private._fixeo_is_enterprise_manager(p_enterprise_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_caller_id uuid;
  v_result    boolean;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL OR p_enterprise_id IS NULL THEN
    RETURN false;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM   public.enterprise_members em
    WHERE  em.enterprise_id = p_enterprise_id
      AND  em.user_id       = v_caller_id
      AND  em.role          IN ('owner', 'admin')
      AND  em.status        = 'active'
  ) INTO v_result;

  RETURN COALESCE(v_result, false);
END;
$function$

CREATE OR REPLACE FUNCTION fixeo_private._fixeo_is_enterprise_member(p_enterprise_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_caller_id uuid;
  v_result    boolean;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL OR p_enterprise_id IS NULL THEN
    RETURN false;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM   public.enterprise_members em
    WHERE  em.enterprise_id = p_enterprise_id
      AND  em.user_id       = v_caller_id
      AND  em.status        = 'active'
  ) INTO v_result;

  RETURN COALESCE(v_result, false);
END;
$function$

CREATE OR REPLACE FUNCTION fixeo_private._fixeo_next_maintenance_due(p_due_at timestamp with time zone, p_frequency text, p_interval_count integer)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
BEGIN
  IF p_frequency='daily' THEN
    RETURN p_due_at + pg_catalog.make_interval(days=>p_interval_count);
  ELSIF p_frequency='weekly' THEN
    RETURN p_due_at + pg_catalog.make_interval(days=>(7*p_interval_count));
  ELSIF p_frequency='monthly' THEN
    RETURN p_due_at + pg_catalog.make_interval(months=>p_interval_count);
  END IF;
  RAISE EXCEPTION 'invalid_frequency';
END;
$function$

CREATE OR REPLACE FUNCTION fixeo_private._write_enterprise_audit_event(p_enterprise_id uuid, p_event_type text, p_target_type text, p_target_id uuid, p_before_state jsonb DEFAULT NULL::jsonb, p_after_state jsonb DEFAULT NULL::jsonb, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_event_id uuid;
  v_actor_user_id uuid;
  v_event_type text;
  v_target_type text;
  v_metadata jsonb;
BEGIN
  IF p_enterprise_id IS NULL THEN
    RAISE EXCEPTION 'enterprise_id_required';
  END IF;

  v_actor_user_id := auth.uid();
  IF v_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'actor_user_id_required';
  END IF;

  v_event_type := pg_catalog.btrim(p_event_type);
  IF v_event_type IS NULL OR pg_catalog.char_length(v_event_type) < 1 THEN
    RAISE EXCEPTION 'event_type_required';
  END IF;

  v_target_type := pg_catalog.btrim(p_target_type);
  IF v_target_type IS NULL OR pg_catalog.char_length(v_target_type) < 1 THEN
    RAISE EXCEPTION 'target_type_required';
  END IF;

  IF p_before_state IS NOT NULL
     AND pg_catalog.jsonb_typeof(p_before_state) <> 'object'
  THEN
    RAISE EXCEPTION 'before_state_must_be_object';
  END IF;

  IF p_after_state IS NOT NULL
     AND pg_catalog.jsonb_typeof(p_after_state) <> 'object'
  THEN
    RAISE EXCEPTION 'after_state_must_be_object';
  END IF;

  v_metadata := COALESCE(p_metadata, '{}'::jsonb);

  IF pg_catalog.jsonb_typeof(v_metadata) <> 'object' THEN
    RAISE EXCEPTION 'metadata_must_be_object';
  END IF;

  INSERT INTO public.enterprise_audit_events (
    enterprise_id,
    actor_user_id,
    event_type,
    target_type,
    target_id,
    before_state,
    after_state,
    metadata
  )
  VALUES (
    p_enterprise_id,
    v_actor_user_id,
    v_event_type,
    v_target_type,
    p_target_id,
    p_before_state,
    p_after_state,
    v_metadata
  )
  RETURNING id INTO v_event_id;

  RETURN v_event_id;
END;
$function$

CREATE OR REPLACE FUNCTION fixeo_private.climatisation_state_v1(mid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m public.missions%ROWTYPE; r public.service_requests%ROWTYPE; o public.fixeo_pricing_offers_v1%ROWTYPE;
 p fixeo_private.climatisation_proposals_v1%ROWTYPE; repair public.fixeo_pricing_offers_v1%ROWTYPE;
 decision boolean; has_decision boolean; credit bigint:=0; total bigint; proposal jsonb:=NULL; can_change boolean;
BEGIN
 SELECT * INTO m FROM public.missions WHERE id=mid;
 IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT * INTO o FROM public.fixeo_pricing_offers_v1 WHERE id=m.pricing_offer_id;
 IF NOT FOUND OR o.catalogue_version<>'climatisation-pilot-v1' OR fixeo_private.climatisation_tariff_v1(o.service_code) IS NULL THEN RETURN NULL; END IF;
 SELECT * INTO r FROM public.service_requests WHERE id::text=m.request_id;
 can_change:=m.status='pending' AND r.status='in_progress' AND m.final_price IS NULL AND NOT coalesce(r.commission_paid,false) AND r.commission_paid_at IS NULL AND coalesce(r.commission_status,'') NOT IN ('payée','paid');
 total:=o.client_total_minor;
 IF o.service_code<>'climatisation.diagnostic' THEN
  RETURN jsonb_build_object('mission_id',mid,'can_propose',false,'can_confirm_prework',can_change,
   'direct_service_code',o.service_code,'current_total_minor',o.client_total_minor,'vap_minor',o.vap_minor,'materials_minor',o.materials_minor,'commission_minor',o.commission_minor,
   'completion_required',(fixeo_private.climatisation_tariff_v1(o.service_code)->>'installation')::boolean,
   'completion_confirmed',EXISTS(SELECT 1 FROM fixeo_private.climatisation_completion_v1 WHERE mission_id=mid AND artisan_id=m.artisan_profile_id AND offer_id=o.id),
   'prework_confirmed',EXISTS(SELECT 1 FROM fixeo_private.climatisation_prework_v1 WHERE mission_id=mid AND artisan_id=m.artisan_profile_id AND offer_id=o.id));
 END IF;
 SELECT * INTO p FROM fixeo_private.climatisation_proposals_v1 WHERE mission_id=mid ORDER BY sequence_id DESC LIMIT 1;
 IF FOUND THEN
  SELECT accepted INTO decision FROM fixeo_private.climatisation_decisions_v1 WHERE proposal_id=p.id;
  has_decision:=FOUND;
  SELECT * INTO STRICT repair FROM public.fixeo_pricing_offers_v1 WHERE id=p.repair_offer_id;
  IF decision IS TRUE THEN total:=repair.client_total_minor; credit:=p.diagnostic_paid_minor; can_change:=false; END IF;
  proposal:=jsonb_build_object('id',p.id,'service_code',repair.service_code,'label',repair.scope->>'label','scope',repair.scope->>'description',
   'client_total_minor',repair.client_total_minor,'vap_minor',repair.vap_minor,'commission_minor',repair.commission_minor,
   'diagnostic_paid_minor',p.diagnostic_paid_minor,'remaining_due_minor',repair.client_total_minor-p.diagnostic_paid_minor,
   'expires_at',repair.expires_at,'status',CASE WHEN has_decision THEN CASE WHEN decision THEN 'ACCEPTED' ELSE 'DECLINED' END WHEN NOT can_change OR repair.expires_at<=now() THEN 'EXPIRED' ELSE 'PENDING' END);
 END IF;
 RETURN jsonb_build_object('mission_id',mid,'can_propose',can_change,'current_total_minor',total,'commission_minor',o.commission_minor,
  'diagnostic_paid_minor',credit,'remaining_due_minor',total-credit,'proposal',proposal);
END $function$

CREATE OR REPLACE FUNCTION fixeo_private.diagnostic_bind_v1(p_context jsonb, p_request uuid, p_offer uuid, p_booking jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE s fixeo_private.diagnostic_sessions_v1%ROWTYPE;
BEGIN
  s:=fixeo_private.diagnostic_lock_v1((p_context->>'session_id')::uuid,p_context->>'actor');
  IF s.state<>'ready' OR s.revision IS DISTINCT FROM (p_context->>'revision')::integer
    OR s.selected_run_id IS DISTINCT FROM (p_context->>'run_id')::uuid
    THEN RAISE EXCEPTION 'DIAGNOSTIC_IMMUTABLE'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.service_requests WHERE id=p_request AND pricing_offer_id IS NOT DISTINCT FROM p_offer)
    THEN RAISE EXCEPTION 'DIAGNOSTIC_REQUEST_MISMATCH'; END IF;
  UPDATE fixeo_private.diagnostic_sessions_v1 SET service_request_id=p_request,state='bound',
    booking_context=p_booking,expires_at=now()+interval '180 days',updated_at=now() WHERE id=s.id;
  UPDATE fixeo_private.diagnostic_media_v1 SET expires_at=now()+interval '90 days'
    WHERE session_id=s.id AND state='ready';
END $function$

CREATE OR REPLACE FUNCTION fixeo_private.diagnostic_booking_context_v1(p_context jsonb, p_city text, p_offer uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE s fixeo_private.diagnostic_sessions_v1%ROWTYPE; r fixeo_private.diagnostic_runs_v1%ROWTYPE; profile_id uuid;
BEGIN
  s:=fixeo_private.diagnostic_lock_v1((p_context->>'session_id')::uuid,p_context->>'actor');
  IF (p_context->>'revision')::integer IS DISTINCT FROM s.revision
    OR (p_context->>'run_id')::uuid IS DISTINCT FROM s.selected_run_id
    OR s.city_slug IS DISTINCT FROM p_city OR s.state NOT IN ('ready','bound')
    THEN RAISE EXCEPTION 'DIAGNOSTIC_REVISION_CONFLICT'; END IF;
  SELECT * INTO r FROM fixeo_private.diagnostic_runs_v1 WHERE id=s.selected_run_id AND session_id=s.id;
  IF NOT FOUND OR r.state<>'complete' OR r.revision<>s.revision
    OR r.result->'safety'->>'stop' IS DISTINCT FROM 'false'
    OR r.result->'safety'->>'urgency' IS NULL
    OR r.result->'safety'->>'urgency' NOT IN ('normale','urgent')
    OR r.result->'questions' IS NULL OR jsonb_array_length(r.result->'questions')<>0
    THEN RAISE EXCEPTION 'DIAGNOSTIC_NOT_QUALIFIED'; END IF;
  IF s.service_request_id IS NOT NULL AND NOT EXISTS(
    SELECT 1 FROM public.service_requests sr WHERE sr.id=s.service_request_id AND sr.pricing_offer_id IS NOT DISTINCT FROM p_offer
  ) THEN RAISE EXCEPTION 'DIAGNOSTIC_ALREADY_BOOKED'; END IF;
  IF s.owner_user_id IS NOT NULL THEN
    SELECT id INTO profile_id FROM public.profiles WHERE id=s.owner_user_id;
    IF profile_id IS NULL THEN RAISE EXCEPTION 'DIAGNOSTIC_PROFILE_REQUIRED'; END IF;
  END IF;
  RETURN jsonb_build_object('urgency',r.result->'safety'->>'urgency','client_profile_id',profile_id,'request_id',s.service_request_id);
END $function$

CREATE OR REPLACE FUNCTION fixeo_private.diagnostic_confirm_request_core_v1(p_context_id text, p_outcome_type text, p_service_code text, p_session_id text, p_amount_mad numeric, p_city_slug text, p_client_phone text, p_description text, p_tracking_ref text, p_guest_token_hash text, p_offer_id uuid, p_diagnostic jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_diagnostic_context jsonb;
  v_offer public.fixeo_pricing_offers_v1%ROWTYPE;
  v_context_id       text;
  v_outcome_type     text;
  v_service_code     text;
  v_session_id       text;
  v_city_slug        text;
  v_city              text;
  v_service_category text;
  v_phone             text;
  v_description       text;
  v_tracking_ref      text;
  v_guest_token_hash  text;
  v_idempotency_key   text;

  v_existing_outcome_type text;
  v_existing_service_code text;
  v_existing_session_id   text;
  v_existing_amount_mad   numeric;
  v_existing_state        text;
  v_existing_request_id   uuid;

  v_request_id              uuid;
  v_existing_tracking_ref   text;
  v_existing_request_status text;
  v_existing_guest_hash     text;
BEGIN
  SELECT * INTO v_offer FROM public.fixeo_pricing_offers_v1 WHERE id=p_offer_id;
  IF NOT FOUND OR v_offer.pricing_version <> 'vap-bp33-v1'
    OR v_offer.scope->>'context_id' IS DISTINCT FROM p_context_id
    OR v_offer.scope->>'session_id' IS DISTINCT FROM p_session_id
    OR v_offer.scope->>'outcome_type' IS DISTINCT FROM p_outcome_type
    OR v_offer.service_code IS DISTINCT FROM p_service_code
    OR v_offer.city IS DISTINCT FROM p_city_slug
    OR v_offer.client_total_minor::numeric/100 IS DISTINCT FROM p_amount_mad
  THEN RETURN jsonb_build_object('ok',false,'reason','offer_mismatch'); END IF;
  IF v_offer.expires_at <= now() AND NOT EXISTS (
    SELECT 1 FROM public.estimator_context_redemptions WHERE context_id=p_context_id AND state='committed'
  ) THEN RETURN jsonb_build_object('ok',false,'reason','offer_expired'); END IF;
  IF (v_offer.scope->'diagnostic') IS DISTINCT FROM (p_diagnostic - 'qualification_answers') THEN
    RETURN jsonb_build_object('ok',false,'reason','diagnostic_context_mismatch');
  END IF;
  IF p_diagnostic IS NOT NULL THEN
    v_diagnostic_context := fixeo_private.diagnostic_booking_context_v1(p_diagnostic,p_city_slug,p_offer_id);
  END IF;
  v_context_id := pg_catalog.btrim(COALESCE(p_context_id, ''));

  IF v_context_id !~ '^fxctx-[0-9a-f]{32}$' THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'invalid_context_id');
  END IF;

  v_outcome_type := pg_catalog.upper(pg_catalog.btrim(COALESCE(p_outcome_type, '')));

  IF NOT (
    v_outcome_type = ANY (
      ARRAY[
        'PRICE_READY',
        'DIAGNOSTIC_READY',
        'LABOUR_PLUS_PART_READY',
        'ADD_ON_READY'
      ]::text[]
    )
  ) THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'non_payable_outcome');
  END IF;

  v_service_code := pg_catalog.lower(pg_catalog.btrim(COALESCE(p_service_code, '')));

  IF
    v_service_code = ''
    OR pg_catalog.char_length(v_service_code) > 200
    OR v_service_code !~ '^[a-z0-9_]+([.][a-z0-9_]+)+$'
  THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'invalid_service_code');
  END IF;

  v_service_category := pg_catalog.split_part(v_service_code, '.', 1);

  IF NOT (
    v_service_category = ANY (
      ARRAY[
        'plomberie',
        'electricite',
        'serrurerie',
        'climatisation',
        'bricolage',
        'nettoyage',
        'peinture',
        'menuiserie', 'jardinage', 'carrelage', 'maconnerie', 'demenagement'
      ]::text[]
    )
  ) THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'unsupported_service_category');
  END IF;

  v_session_id := pg_catalog.btrim(COALESCE(p_session_id, ''));

  IF v_session_id = '' OR pg_catalog.char_length(v_session_id) > 200 THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'invalid_session_id');
  END IF;

  IF p_amount_mad IS NULL OR p_amount_mad <= 0 THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'invalid_canonical_amount');
  END IF;

  v_city_slug := pg_catalog.lower(pg_catalog.btrim(COALESCE(p_city_slug, '')));

  v_city :=
    CASE v_city_slug
      WHEN 'casablanca'  THEN 'Casablanca'
      WHEN 'rabat'       THEN 'Rabat'
      WHEN 'marrakech'   THEN 'Marrakech'
      WHEN 'fes'         THEN 'Fès'
      WHEN 'tanger'      THEN 'Tanger'
      WHEN 'agadir'      THEN 'Agadir'
      WHEN 'meknes'      THEN 'Meknès'
      WHEN 'oujda'       THEN 'Oujda'
      WHEN 'kenitra'     THEN 'Kénitra'
      WHEN 'tetouan'     THEN 'Tétouan'
      WHEN 'sale'        THEN 'Salé'
      WHEN 'temara'      THEN 'Temara'
      WHEN 'el-jadida'   THEN 'El Jadida'
      WHEN 'beni-mellal' THEN 'Béni Mellal'
      WHEN 'nador'       THEN 'Nador'
      WHEN 'khouribga'   THEN 'Khouribga'
      WHEN 'safi'        THEN 'Safi'
      WHEN 'taza'        THEN 'Taza'
      WHEN 'ouarzazate'  THEN 'Ouarzazate'
      WHEN 'mohammedia'  THEN 'Mohammedia'
      ELSE NULL
    END;

  IF v_city IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'invalid_city');
  END IF;

  v_phone := pg_catalog.regexp_replace(
    pg_catalog.btrim(COALESCE(p_client_phone, '')),
    '[[:space:]().-]+',
    '',
    'g'
  );

  IF v_phone !~ '^(\+212|0)[5-7][0-9]{8}$' THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'invalid_client_phone');
  END IF;

  v_description := pg_catalog.btrim(COALESCE(p_description, ''));

  IF v_description = '' OR pg_catalog.char_length(v_description) > 1000 THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'invalid_description');
  END IF;

  IF v_service_code = 'demenagement.manutention_2h' THEN
    v_description := 'Forfait FIXEO : équipe de 2 intervenants pendant 2 heures sur un même site, sans camion ni transport. 690 MAD client ; 600 MAD pour toute l’équipe ; 90 MAD FIXEO. Affaires préparées, accès dégagé sans portage en escalier. Pas de démontage ni objet exceptionnel. Pas de prolongation automatique. ' || pg_catalog.left(v_description, 650);
  END IF;

  v_tracking_ref := pg_catalog.upper(pg_catalog.btrim(COALESCE(p_tracking_ref, '')));

  IF
    pg_catalog.char_length(v_tracking_ref) > 32
    OR v_tracking_ref !~ '^FX-[A-Z0-9-]{1,29}$'
  THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'invalid_tracking_ref');
  END IF;

  v_guest_token_hash := pg_catalog.lower(pg_catalog.btrim(COALESCE(p_guest_token_hash, '')));

  IF v_guest_token_hash !~ '^[0-9a-f]{64}$' THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'invalid_guest_token_hash');
  END IF;

  v_idempotency_key := 'estimator:' || v_context_id;

  INSERT INTO public.estimator_context_redemptions (
    context_id,
    outcome_type,
    service_code,
    session_id,
    amount_mad,
    state,
    acquired_at
  )
  VALUES (
    v_context_id,
    v_outcome_type,
    v_service_code,
    v_session_id,
    p_amount_mad,
    'acquired',
    pg_catalog.now()
  )
  ON CONFLICT (context_id)
  DO NOTHING;

  SELECT
    ecr.outcome_type,
    ecr.service_code,
    ecr.session_id,
    ecr.amount_mad,
    ecr.state,
    ecr.service_request_id
  INTO
    v_existing_outcome_type,
    v_existing_service_code,
    v_existing_session_id,
    v_existing_amount_mad,
    v_existing_state,
    v_existing_request_id
  FROM public.estimator_context_redemptions ecr
  WHERE ecr.context_id = v_context_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      '7C.9M.2 invariant failure: redemption row not found after acquisition';
  END IF;

  IF
    v_existing_outcome_type IS DISTINCT FROM v_outcome_type
    OR v_existing_service_code IS DISTINCT FROM v_service_code
    OR v_existing_session_id IS DISTINCT FROM v_session_id
    OR v_existing_amount_mad IS DISTINCT FROM p_amount_mad
  THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'context_identity_mismatch');
  END IF;

  IF v_existing_state = 'committed' THEN
    IF v_existing_request_id IS NULL THEN
      RETURN pg_catalog.jsonb_build_object(
        'ok', false,
        'reason', 'context_already_consumed_without_request'
      );
    END IF;

    SELECT
      sr.tracking_ref,
      sr.status,
      sr.guest_token_hash
    INTO
      v_existing_tracking_ref,
      v_existing_request_status,
      v_existing_guest_hash
    FROM public.service_requests sr
    WHERE sr.id = v_existing_request_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION
        '7C.9M.2 invariant failure: committed redemption references missing request %',
        v_existing_request_id;
    END IF;

    IF
      v_existing_guest_hash IS NULL
      OR v_existing_guest_hash IS DISTINCT FROM v_guest_token_hash
    THEN
      RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'guest_token_mismatch');
    END IF;

    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'replayed', true,
      'request_id', v_existing_request_id,
      'tracking_ref', v_existing_tracking_ref,
      'service_category', v_service_category,
      'service_code', v_service_code,
      'city', v_city,
      'status', v_existing_request_status,
      'outcome_type', v_outcome_type,
      'amount_mad', p_amount_mad
    );
  END IF;

  IF v_existing_request_id IS NOT NULL THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'inconsistent_existing_request_binding'
    );
  END IF;

  IF v_existing_state = 'failed' THEN
    UPDATE public.estimator_context_redemptions
    SET
      state = 'acquired',
      acquired_at = pg_catalog.now(),
      failed_at = NULL,
      failure_reason = NULL,
      booking_ref = NULL,
      order_id = NULL
    WHERE context_id = v_context_id;
  ELSIF v_existing_state <> 'acquired' THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'invalid_redemption_state',
      'state', v_existing_state
    );
  END IF;

  INSERT INTO public.service_requests (
    service_category,
    city,
    description,
    client_phone,
    urgency,
    status,
    idempotency_key,
    tracking_ref,
    guest_token_hash, pricing_offer_id, client_profile_id
  )
  VALUES (
    v_service_category,
    v_city,
    v_description,
    v_phone,
    coalesce(v_diagnostic_context->>'urgency','normale'),
    'new',
    v_idempotency_key,
    v_tracking_ref,
    v_guest_token_hash, p_offer_id, (v_diagnostic_context->>'client_profile_id')::uuid
  )
  RETURNING id
  INTO v_request_id;

  IF p_diagnostic IS NOT NULL THEN
    PERFORM fixeo_private.diagnostic_bind_v1(p_diagnostic,v_request_id,p_offer_id,
      jsonb_build_object('service_code',v_service_code,'urgency',v_diagnostic_context->>'urgency',
        'urgency_provenance','ai_inferred','qualification_answers',coalesce(p_diagnostic->'qualification_answers','[]')));
  END IF;

  UPDATE public.estimator_context_redemptions
  SET
    state = 'committed',
    service_request_id = v_request_id,
    committed_at = pg_catalog.now(),
    failed_at = NULL,
    failure_reason = NULL
  WHERE context_id = v_context_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      '7C.9M.2 invariant failure: redemption disappeared before commit';
  END IF;

  RETURN pg_catalog.jsonb_build_object(
    'ok', true,
    'replayed', false,
    'request_id', v_request_id,
    'tracking_ref', v_tracking_ref,
    'service_category', v_service_category,
    'service_code', v_service_code,
    'city', v_city,
    'status', 'new',
    'outcome_type', v_outcome_type,
    'amount_mad', p_amount_mad
  );
END;
$function$

CREATE OR REPLACE FUNCTION fixeo_private.diagnostic_lock_v1(p_id uuid, p_actor text)
 RETURNS fixeo_private.diagnostic_sessions_v1
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE s fixeo_private.diagnostic_sessions_v1%ROWTYPE;
BEGIN
  SELECT * INTO s FROM fixeo_private.diagnostic_sessions_v1 WHERE id=p_id AND owner_key=p_actor FOR UPDATE;
  IF NOT FOUND OR s.expires_at <= now() OR s.state='expired'
    THEN RAISE EXCEPTION 'DIAGNOSTIC_NOT_FOUND'; END IF;
  RETURN s;
END $function$

CREATE OR REPLACE FUNCTION fixeo_private.diagnostic_quota_v1(p_limits jsonb, p_delta jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE lim jsonb; q fixeo_private.diagnostic_usage_windows_v1%ROWTYPE;
  w timestamptz := date_trunc('day',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC';
  dr bigint := coalesce((p_delta->>'requests')::bigint,0);
  ds bigint := coalesce((p_delta->>'sessions')::bigint,0);
  da bigint := coalesce((p_delta->>'analyses')::bigint,0);
  db bigint := coalesce((p_delta->>'bytes')::bigint,0);
  dc bigint := coalesce((p_delta->>'reserved_micro_usd')::bigint,0);
BEGIN
  IF p_limits IS NULL OR p_delta IS NULL OR jsonb_typeof(p_limits)<>'array' OR jsonb_array_length(p_limits) NOT BETWEEN 1 AND 3
    OR least(dr,ds,da,db,dc)<0 THEN RAISE EXCEPTION 'DIAGNOSTIC_QUOTA_INVALID'; END IF;
  -- Sorted row locking makes concurrent requests reserve all limits atomically.
  FOR lim IN SELECT value FROM jsonb_array_elements(p_limits) ORDER BY value->>'key' LOOP
    IF NOT (lim ?& ARRAY['key','requests','sessions','analyses','bytes','reserved_micro_usd'])
      OR EXISTS(SELECT 1 FROM jsonb_each(lim) x WHERE x.key IN ('requests','sessions','analyses','bytes','reserved_micro_usd') AND (jsonb_typeof(x.value)<>'number' OR x.value::text !~ '^[0-9]+$'))
      THEN RAISE EXCEPTION 'DIAGNOSTIC_QUOTA_INVALID'; END IF;
    INSERT INTO fixeo_private.diagnostic_usage_windows_v1(quota_key,window_start)
      VALUES(lim->>'key',w) ON CONFLICT DO NOTHING;
    SELECT * INTO q FROM fixeo_private.diagnostic_usage_windows_v1
      WHERE quota_key=lim->>'key' AND window_start=w FOR UPDATE;
    IF q.requests+dr>(lim->>'requests')::bigint OR q.sessions+ds>(lim->>'sessions')::bigint
      OR q.analyses+da>(lim->>'analyses')::bigint OR q.bytes+db>(lim->>'bytes')::bigint
      OR q.reserved_micro_usd+dc>(lim->>'reserved_micro_usd')::bigint
      THEN RAISE EXCEPTION 'DIAGNOSTIC_QUOTA_EXCEEDED'; END IF;
    UPDATE fixeo_private.diagnostic_usage_windows_v1 SET requests=requests+dr,
      sessions=sessions+ds, analyses=analyses+da, bytes=bytes+db,
      reserved_micro_usd=reserved_micro_usd+dc WHERE quota_key=q.quota_key AND window_start=w;
  END LOOP;
END $function$

CREATE OR REPLACE FUNCTION fixeo_private.electricity_state_v1(mid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m public.missions%ROWTYPE; r public.service_requests%ROWTYPE; o public.fixeo_pricing_offers_v1%ROWTYPE;
 p fixeo_private.electricity_proposals_v1%ROWTYPE; repair public.fixeo_pricing_offers_v1%ROWTYPE;
 decision boolean; has_decision boolean; credit bigint:=0; total bigint; proposal jsonb:=NULL; can_change boolean;
BEGIN
 SELECT * INTO m FROM public.missions WHERE id=mid;
 IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT * INTO o FROM public.fixeo_pricing_offers_v1 WHERE id=m.pricing_offer_id;
 IF NOT FOUND OR o.catalogue_version<>'electricity-pilot-v1' OR fixeo_private.electricity_tariff_v1(o.service_code) IS NULL THEN RETURN NULL; END IF;
 SELECT * INTO r FROM public.service_requests WHERE id::text=m.request_id;
 can_change:=m.status='pending' AND r.status='in_progress' AND m.final_price IS NULL AND NOT coalesce(r.commission_paid,false) AND r.commission_paid_at IS NULL AND coalesce(r.commission_status,'') NOT IN ('payée','paid');
 total:=o.client_total_minor;
 IF o.service_code<>'electricite.diagnostic' THEN
  RETURN jsonb_build_object('mission_id',mid,'can_propose',false,'can_confirm_prework',can_change,
   'direct_service_code',o.service_code,'current_total_minor',o.client_total_minor,
   'prework_confirmed',EXISTS(SELECT 1 FROM fixeo_private.electricity_prework_v1 WHERE mission_id=mid AND artisan_id=m.artisan_profile_id AND offer_id=o.id));
 END IF;
 SELECT * INTO p FROM fixeo_private.electricity_proposals_v1 WHERE mission_id=mid ORDER BY sequence_id DESC LIMIT 1;
 IF FOUND THEN
  SELECT accepted INTO decision FROM fixeo_private.electricity_decisions_v1 WHERE proposal_id=p.id;
  has_decision:=FOUND;
  SELECT * INTO STRICT repair FROM public.fixeo_pricing_offers_v1 WHERE id=p.repair_offer_id;
  IF decision IS TRUE THEN total:=repair.client_total_minor; credit:=p.diagnostic_paid_minor; can_change:=false; END IF;
  proposal:=jsonb_build_object('id',p.id,'service_code',repair.service_code,'label',repair.scope->>'label','scope',repair.scope->>'description',
   'client_total_minor',repair.client_total_minor,'vap_minor',repair.vap_minor,'commission_minor',repair.commission_minor,
   'diagnostic_paid_minor',p.diagnostic_paid_minor,'remaining_due_minor',repair.client_total_minor-p.diagnostic_paid_minor,
   'expires_at',repair.expires_at,'status',CASE WHEN has_decision THEN CASE WHEN decision THEN 'ACCEPTED' ELSE 'DECLINED' END WHEN NOT can_change OR repair.expires_at<=now() THEN 'EXPIRED' ELSE 'PENDING' END);
 END IF;
 RETURN jsonb_build_object('mission_id',mid,'can_propose',can_change,'current_total_minor',total,'commission_minor',o.commission_minor,
  'diagnostic_paid_minor',credit,'remaining_due_minor',total-credit,'proposal',proposal);
END $function$

CREATE OR REPLACE FUNCTION fixeo_private.enforce_profile_canonical_role_p0()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  canonical_role text;
BEGIN
  SELECT u.role INTO canonical_role FROM public.users u WHERE u.id = NEW.id;
  IF NOT FOUND OR canonical_role IS NULL
     OR canonical_role NOT IN ('admin','artisan','client') THEN
    RAISE EXCEPTION 'canonical_identity_missing_or_invalid' USING ERRCODE='23514';
  END IF;
  NEW.role := canonical_role;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION fixeo_private.guard_vap_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
 IF TG_TABLE_NAME='service_requests' THEN
  IF TG_OP='UPDATE' AND OLD.pricing_offer_id IS NOT NULL AND NEW.id IS DISTINCT FROM OLD.id THEN RAISE EXCEPTION 'Request identity immutable'; END IF;
  IF TG_OP='UPDATE' AND OLD.pricing_offer_id IS DISTINCT FROM NEW.pricing_offer_id THEN
   RAISE EXCEPTION 'Offer binding is immutable';
  END IF;
  IF TG_OP='INSERT' AND NEW.pricing_offer_id IS NOT NULL AND current_user NOT IN ('postgres','service_role') THEN
   RAISE EXCEPTION 'Server offer binding required';
  END IF;
 ELSE
  IF TG_OP='UPDATE' AND NEW.request_id IS DISTINCT FROM OLD.request_id AND fixeo_private.is_vap_request(NEW.request_id) THEN RAISE EXCEPTION 'Cannot rebind legacy mission'; END IF;
  IF TG_OP='INSERT' AND current_user NOT IN ('postgres','service_role') AND
    (NEW.pricing_offer_id IS NOT NULL OR fixeo_private.is_vap_request(NEW.request_id)) THEN
   RAISE EXCEPTION 'Use authenticated acceptance RPC';
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION fixeo_private.mission_vap_amounts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE offer public.fixeo_pricing_offers_v1%ROWTYPE; bound uuid; effective uuid; accepted_artisan uuid;
BEGIN
 IF TG_OP='UPDATE' THEN
  IF NEW.pricing_offer_id IS DISTINCT FROM OLD.pricing_offer_id THEN RAISE EXCEPTION 'Offer binding is immutable'; END IF;
  IF OLD.pricing_offer_id IS NULL THEN RETURN NEW; END IF;
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.request_id IS DISTINCT FROM OLD.request_id THEN RAISE EXCEPTION 'Mission binding is immutable'; END IF;
  bound:=OLD.pricing_offer_id;
  IF EXISTS(SELECT 1 FROM (SELECT proposal_id,mission_id,request_id,accepted FROM fixeo_private.plumbing_decisions_v1 UNION ALL SELECT proposal_id,mission_id,request_id,accepted FROM fixeo_private.electricity_decisions_v1 UNION ALL SELECT proposal_id,mission_id,request_id,accepted FROM fixeo_private.climatisation_decisions_v1 UNION ALL SELECT proposal_id,mission_id,request_id,accepted FROM fixeo_private.serrurerie_decisions_v1) d WHERE request_id::text=NEW.request_id AND mission_id<>OLD.id AND accepted) AND (NEW.status IS DISTINCT FROM 'cancelled' OR NEW.final_price IS NOT NULL) THEN RAISE EXCEPTION 'Accepted repair already has its mission'; END IF;
  SELECT a.repair_offer_id,a.artisan_id INTO effective,accepted_artisan FROM (SELECT d.mission_id,p.repair_offer_id,p.artisan_id FROM fixeo_private.plumbing_decisions_v1 d JOIN fixeo_private.plumbing_proposals_v1 p ON p.id=d.proposal_id WHERE d.accepted UNION ALL SELECT d.mission_id,p.repair_offer_id,p.artisan_id FROM fixeo_private.electricity_decisions_v1 d JOIN fixeo_private.electricity_proposals_v1 p ON p.id=d.proposal_id WHERE d.accepted UNION ALL SELECT d.mission_id,p.repair_offer_id,p.artisan_id FROM fixeo_private.climatisation_decisions_v1 d JOIN fixeo_private.climatisation_proposals_v1 p ON p.id=d.proposal_id WHERE d.accepted UNION ALL SELECT d.mission_id,p.repair_offer_id,p.artisan_id FROM fixeo_private.serrurerie_decisions_v1 d JOIN fixeo_private.serrurerie_proposals_v1 p ON p.id=d.proposal_id WHERE d.accepted) a WHERE a.mission_id=OLD.id;
  IF effective IS NOT NULL AND NEW.artisan_profile_id IS DISTINCT FROM accepted_artisan THEN RAISE EXCEPTION 'Accepted same visit artisan is immutable'; END IF;
 ELSE
  SELECT pricing_offer_id INTO bound FROM public.service_requests WHERE id::text=NEW.request_id;
  IF NEW.pricing_offer_id IS NOT NULL AND NEW.pricing_offer_id IS DISTINCT FROM bound THEN RAISE EXCEPTION 'Offer mismatch'; END IF;
  IF bound IS NULL THEN RETURN NEW; END IF;
  IF EXISTS(SELECT 1 FROM (SELECT proposal_id,mission_id,request_id,accepted FROM fixeo_private.plumbing_decisions_v1 UNION ALL SELECT proposal_id,mission_id,request_id,accepted FROM fixeo_private.electricity_decisions_v1 UNION ALL SELECT proposal_id,mission_id,request_id,accepted FROM fixeo_private.climatisation_decisions_v1 UNION ALL SELECT proposal_id,mission_id,request_id,accepted FROM fixeo_private.serrurerie_decisions_v1) d WHERE request_id::text=NEW.request_id AND accepted) THEN RAISE EXCEPTION 'Accepted repair already has its mission'; END IF;
 END IF;
 SELECT * INTO STRICT offer FROM public.fixeo_pricing_offers_v1 WHERE id=coalesce(effective,bound);
 IF offer.catalogue_version='electricity-pilot-v1' AND offer.service_code<>'electricite.diagnostic' AND effective IS NULL THEN
  IF EXISTS(SELECT 1 FROM fixeo_private.electricity_prework_v1 WHERE mission_id=NEW.id AND artisan_id IS DISTINCT FROM NEW.artisan_profile_id) THEN
   RAISE EXCEPTION 'Pre-work artisan is immutable';
  END IF;
  IF (NEW.status IN ('done','validated') OR NEW.final_price IS NOT NULL) AND NOT EXISTS(
   SELECT 1 FROM fixeo_private.electricity_prework_v1 WHERE mission_id=NEW.id AND artisan_id=NEW.artisan_profile_id AND offer_id=bound
  ) THEN RAISE EXCEPTION 'Electrical pre-work checks required before completion or settlement' USING ERRCODE='22023'; END IF;
 END IF;
 IF offer.catalogue_version='climatisation-pilot-v1' AND effective IS NULL THEN
  IF offer.service_code IN ('climatisation.installation.standard','climatisation.installation.mono_split_5m') AND (NEW.status IN ('pending','done','validated') OR NEW.final_price IS NOT NULL) AND NOT EXISTS(
   SELECT 1 FROM fixeo_private.climatisation_offer_checks_v1 WHERE request_id::text=NEW.request_id AND artisan_id=NEW.artisan_profile_id AND offer_id=bound
  ) THEN RAISE EXCEPTION 'Climatisation kit and capability confirmation required before acceptance' USING ERRCODE='22023'; END IF;
  IF EXISTS(SELECT 1 FROM fixeo_private.climatisation_prework_v1 WHERE mission_id=NEW.id AND artisan_id IS DISTINCT FROM NEW.artisan_profile_id) THEN
   RAISE EXCEPTION 'Pre-work artisan is immutable';
  END IF;
  IF offer.service_code<>'climatisation.diagnostic' AND (NEW.status IN ('done','validated') OR NEW.final_price IS NOT NULL) AND NOT EXISTS(
   SELECT 1 FROM fixeo_private.climatisation_prework_v1 WHERE mission_id=NEW.id AND artisan_id=NEW.artisan_profile_id AND offer_id=bound
  ) THEN RAISE EXCEPTION 'Climatisation pre-work checks required before completion or settlement' USING ERRCODE='22023'; END IF;
  IF offer.service_code IN ('climatisation.installation.standard','climatisation.installation.mono_split_5m') AND (NEW.status IN ('done','validated') OR NEW.final_price IS NOT NULL) AND NOT EXISTS(
   SELECT 1 FROM fixeo_private.climatisation_completion_v1 WHERE mission_id=NEW.id AND artisan_id=NEW.artisan_profile_id AND offer_id=bound
  ) THEN RAISE EXCEPTION 'Climatisation commissioning checks required before completion or settlement' USING ERRCODE='22023'; END IF;
 END IF;
 IF offer.catalogue_version='serrurerie-pilot-v1' THEN
  IF effective IS NULL AND (NEW.status IN ('pending','done','validated') OR NEW.final_price IS NOT NULL) AND NOT EXISTS(
   SELECT 1 FROM fixeo_private.serrurerie_offer_checks_v1 WHERE request_id::text=NEW.request_id AND artisan_id=NEW.artisan_profile_id AND offer_id=bound
  ) THEN RAISE EXCEPTION 'Serrurerie scope and capability confirmation required before acceptance' USING ERRCODE='22023'; END IF;
  IF EXISTS(SELECT 1 FROM fixeo_private.serrurerie_prework_v1 WHERE mission_id=NEW.id AND artisan_id IS DISTINCT FROM NEW.artisan_profile_id) THEN
   RAISE EXCEPTION 'Pre-work artisan is immutable';
  END IF;
  IF (NEW.status IN ('done','validated') OR NEW.final_price IS NOT NULL) AND NOT EXISTS(
   SELECT 1 FROM fixeo_private.serrurerie_prework_v1 WHERE mission_id=NEW.id AND artisan_id=NEW.artisan_profile_id AND offer_id=offer.id
  ) THEN RAISE EXCEPTION 'Serrurerie access and pre-work checks required before completion or settlement' USING ERRCODE='22023'; END IF;
  IF (NEW.status IN ('done','validated') OR NEW.final_price IS NOT NULL) AND NOT EXISTS(
   SELECT 1 FROM fixeo_private.serrurerie_completion_v1 WHERE mission_id=NEW.id AND artisan_id=NEW.artisan_profile_id AND offer_id=offer.id
  ) THEN RAISE EXCEPTION 'Serrurerie result confirmation required before completion or settlement' USING ERRCODE='22023'; END IF;
 END IF;
 IF NEW.final_price IS NOT NULL AND NEW.final_price IS DISTINCT FROM offer.client_total_minor::numeric/100 THEN RAISE EXCEPTION 'New scope requires a new accepted offer'; END IF;
 IF TG_OP='UPDATE' AND OLD.final_price IS NOT NULL AND NEW.final_price IS NULL THEN RAISE EXCEPTION 'Cannot clear settlement'; END IF;
 NEW.pricing_offer_id:=bound;
 NEW.agreed_price:=offer.client_total_minor::numeric/100;
 NEW.commission_amount:=offer.commission_minor::numeric/100;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION fixeo_private.plumbing_state_v1(mid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m public.missions%ROWTYPE; r public.service_requests%ROWTYPE; o public.fixeo_pricing_offers_v1%ROWTYPE;
 p fixeo_private.plumbing_proposals_v1%ROWTYPE; repair public.fixeo_pricing_offers_v1%ROWTYPE;
 decision boolean; has_decision boolean; credit bigint:=0; total bigint; proposal jsonb:=NULL; can_change boolean;
BEGIN
 SELECT * INTO m FROM public.missions WHERE id=mid;
 IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT * INTO o FROM public.fixeo_pricing_offers_v1 WHERE id=m.pricing_offer_id;
 IF NOT FOUND OR o.service_code<>'plomberie.diagnostic' OR o.catalogue_version<>'plumbing-pilot-v1' THEN RETURN NULL; END IF;
 SELECT * INTO r FROM public.service_requests WHERE id::text=m.request_id;
 can_change:=m.status='pending' AND r.status='in_progress' AND m.final_price IS NULL AND NOT coalesce(r.commission_paid,false) AND r.commission_paid_at IS NULL AND coalesce(r.commission_status,'') NOT IN ('payée','paid');
 total:=o.client_total_minor;
 SELECT * INTO p FROM fixeo_private.plumbing_proposals_v1 WHERE mission_id=mid ORDER BY sequence_id DESC LIMIT 1;
 IF FOUND THEN
  SELECT accepted INTO decision FROM fixeo_private.plumbing_decisions_v1 WHERE proposal_id=p.id;
  has_decision:=FOUND;
  SELECT * INTO STRICT repair FROM public.fixeo_pricing_offers_v1 WHERE id=p.repair_offer_id;
  IF decision IS TRUE THEN total:=repair.client_total_minor; credit:=p.diagnostic_paid_minor; can_change:=false; END IF;
  proposal:=jsonb_build_object('id',p.id,'service_code',repair.service_code,'label',repair.scope->>'label','scope',repair.scope->>'description',
   'client_total_minor',repair.client_total_minor,'vap_minor',repair.vap_minor,'commission_minor',repair.commission_minor,
   'diagnostic_paid_minor',p.diagnostic_paid_minor,'remaining_due_minor',repair.client_total_minor-p.diagnostic_paid_minor,
   'expires_at',repair.expires_at,'status',CASE WHEN has_decision THEN CASE WHEN decision THEN 'ACCEPTED' ELSE 'DECLINED' END WHEN NOT can_change OR repair.expires_at<=now() THEN 'EXPIRED' ELSE 'PENDING' END);
 END IF;
 RETURN jsonb_build_object('mission_id',mid,'can_propose',can_change,'current_total_minor',total,'commission_minor',o.commission_minor,
  'diagnostic_paid_minor',credit,'remaining_due_minor',total-credit,'proposal',proposal);
END $function$

CREATE OR REPLACE FUNCTION fixeo_private.serrurerie_offer_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE tariff jsonb;
BEGIN
 IF NEW.service_code NOT LIKE 'serrurerie.%' THEN RETURN NEW; END IF;
 tariff:=fixeo_private.serrurerie_tariff_v1(NEW.service_code);
 IF tariff IS NULL OR NEW.catalogue_version IS DISTINCT FROM 'serrurerie-pilot-v1'
  OR NEW.pricing_version IS DISTINCT FROM 'vap-bp33-v1' OR NEW.currency IS DISTINCT FROM 'MAD'
  OR NEW.scope->'inputs' IS DISTINCT FROM tariff->'inputs'
  OR NEW.vap_minor IS DISTINCT FROM (tariff->>'vap_minor')::bigint OR NEW.materials_minor IS DISTINCT FROM 0
  OR NEW.commission_minor IS DISTINCT FROM 6000 OR NEW.client_total_minor IS DISTINCT FROM (tariff->>'total_minor')::bigint
  OR NEW.city IS NULL OR NEW.city NOT IN ('agadir','beni-mellal','casablanca','el-jadida','fes','kenitra','khouribga','marrakech','meknes','mohammedia','nador','ouarzazate','oujda','rabat','safi','sale','tanger','taza','temara','tetouan') THEN
  RAISE EXCEPTION 'Serrurerie offer requires approved city, exact scope and tariff' USING ERRCODE='22023';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION fixeo_private.serrurerie_state_v1(mid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m public.missions%ROWTYPE; r public.service_requests%ROWTYPE; original public.fixeo_pricing_offers_v1%ROWTYPE;
 o public.fixeo_pricing_offers_v1%ROWTYPE; p fixeo_private.serrurerie_proposals_v1%ROWTYPE;
 repair public.fixeo_pricing_offers_v1%ROWTYPE; decision boolean; has_decision boolean; credit bigint:=0;
 proposal jsonb:=NULL; can_change boolean; prework boolean; completed boolean;
BEGIN
 SELECT * INTO m FROM public.missions WHERE id=mid;
 IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT * INTO original FROM public.fixeo_pricing_offers_v1 WHERE id=m.pricing_offer_id;
 IF NOT FOUND OR original.catalogue_version<>'serrurerie-pilot-v1' OR fixeo_private.serrurerie_tariff_v1(original.service_code) IS NULL THEN RETURN NULL; END IF;
 SELECT * INTO r FROM public.service_requests WHERE id::text=m.request_id;
 can_change:=m.status='pending' AND r.status='in_progress' AND m.final_price IS NULL AND NOT coalesce(r.commission_paid,false) AND r.commission_paid_at IS NULL AND coalesce(r.commission_status,'') NOT IN ('payée','paid');
 o:=original;
 IF original.service_code='serrurerie.diagnostic' THEN
  SELECT * INTO p FROM fixeo_private.serrurerie_proposals_v1 WHERE mission_id=mid ORDER BY sequence_id DESC LIMIT 1;
  IF FOUND THEN
   SELECT accepted INTO decision FROM fixeo_private.serrurerie_decisions_v1 WHERE proposal_id=p.id; has_decision:=FOUND;
   SELECT * INTO STRICT repair FROM public.fixeo_pricing_offers_v1 WHERE id=p.repair_offer_id;
   IF decision IS TRUE THEN o:=repair; credit:=p.diagnostic_paid_minor; END IF;
   proposal:=jsonb_build_object('id',p.id,'service_code',repair.service_code,'label',repair.scope->>'label','scope',repair.scope->>'description',
    'client_total_minor',repair.client_total_minor,'vap_minor',repair.vap_minor,'commission_minor',repair.commission_minor,
    'diagnostic_paid_minor',p.diagnostic_paid_minor,'remaining_due_minor',repair.client_total_minor-p.diagnostic_paid_minor,
    'expires_at',repair.expires_at,'status',CASE WHEN has_decision THEN CASE WHEN decision THEN 'ACCEPTED' ELSE 'DECLINED' END WHEN NOT can_change OR repair.expires_at<=now() THEN 'EXPIRED' ELSE 'PENDING' END);
  END IF;
 END IF;
 prework:=EXISTS(SELECT 1 FROM fixeo_private.serrurerie_prework_v1 WHERE mission_id=mid AND offer_id=o.id AND artisan_id=m.artisan_profile_id);
 completed:=EXISTS(SELECT 1 FROM fixeo_private.serrurerie_completion_v1 WHERE mission_id=mid AND offer_id=o.id AND artisan_id=m.artisan_profile_id);
 -- No proof type, identity number, document or raw professional attestation in this shared/public view.
 RETURN jsonb_build_object('mission_id',mid,'direct_service_code',o.service_code,'can_confirm_prework',can_change,
  'can_propose',can_change AND o.service_code='serrurerie.diagnostic' AND prework AND completed,
  'current_total_minor',o.client_total_minor,'vap_minor',o.vap_minor,'materials_minor',o.materials_minor,'commission_minor',o.commission_minor,
  'prework_confirmed',prework,'completion_required',true,'completion_confirmed',completed,
  'diagnostic_paid_minor',credit,'remaining_due_minor',o.client_total_minor-credit,'proposal',proposal);
END $function$

CREATE OR REPLACE FUNCTION public.accept_enterprise_invitation(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_enterprise_status text;
  v_caller_id uuid;
  v_caller_email text;
  v_public_user_exists boolean;

  v_token_hash text;

  v_probe_enterprise_id uuid;

  v_invitation_id uuid;
  v_enterprise_id uuid;
  v_invitation_email text;
  v_invitation_role text;
  v_invitation_status text;
  v_target_user_id uuid;
  v_expires_at timestamptz;

  v_member_id uuid;
  v_member_status text;
BEGIN
  v_caller_id := auth.uid();

  IF v_caller_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','unauthenticated');
  END IF;

  IF p_token IS NULL
     OR pg_catalog.char_length(p_token) <> 64
     OR p_token !~ '^[0-9a-fA-F]{64}$'
  THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invalid_token');
  END IF;

  SELECT pg_catalog.lower(pg_catalog.btrim(au.email::text))
  INTO v_caller_email
  FROM auth.users au
  WHERE au.id = v_caller_id;

  IF NOT FOUND OR v_caller_email IS NULL OR v_caller_email = '' THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',false,
      'reason','identity_email_unavailable'
    );
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.users u WHERE u.id = v_caller_id
  )
  INTO v_public_user_exists;

  IF NOT v_public_user_exists THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',false,
      'reason','identity_not_ready'
    );
  END IF;

  v_token_hash :=
    pg_catalog.encode(
      extensions.digest(
        pg_catalog.convert_to(pg_catalog.lower(p_token),'UTF8'),
        'sha256'
      ),
      'hex'
    );

  -- Probe only: no lock yet.
  SELECT ei.enterprise_id
  INTO v_probe_enterprise_id
  FROM public.enterprise_invitations ei
  WHERE ei.token_hash = v_token_hash;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invitation_not_found');
  END IF;

  -- LOCK ORDER #1: enterprise account.
  SELECT ea.status
  INTO v_enterprise_status
  FROM public.enterprise_accounts ea
  WHERE ea.id = v_probe_enterprise_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','enterprise_not_found');
  END IF;

  IF v_enterprise_status <> 'active' THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','enterprise_not_active',
      'enterprise_status',v_enterprise_status);
  END IF;

  -- LOCK ORDER #2: invitation. Re-read all mutable fields after account lock.
  SELECT
    ei.id,
    ei.enterprise_id,
    ei.email_normalized,
    ei.role,
    ei.status,
    ei.target_user_id,
    ei.expires_at
  INTO
    v_invitation_id,
    v_enterprise_id,
    v_invitation_email,
    v_invitation_role,
    v_invitation_status,
    v_target_user_id,
    v_expires_at
  FROM public.enterprise_invitations ei
  WHERE ei.token_hash = v_token_hash
    AND ei.enterprise_id = v_probe_enterprise_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invitation_not_found');
  END IF;

  IF v_invitation_status <> 'pending' THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',false,
      'reason','invitation_not_pending'
    );
  END IF;

  IF v_expires_at <= pg_catalog.now() THEN
    UPDATE public.enterprise_invitations
    SET status='expired',
        updated_at=pg_catalog.now()
    WHERE id=v_invitation_id;

    -- LOCK ORDER #3: invited membership, if one was materialized.
    IF v_target_user_id IS NOT NULL THEN
      SELECT em.id, em.status
      INTO v_member_id, v_member_status
      FROM public.enterprise_members em
      WHERE em.enterprise_id=v_enterprise_id
        AND em.user_id=v_target_user_id
      FOR UPDATE;

      IF FOUND AND v_member_status='invited' THEN
        UPDATE public.enterprise_members
        SET status='removed',
            updated_at=pg_catalog.now()
        WHERE id=v_member_id;
      END IF;
    END IF;

    PERFORM fixeo_private._write_enterprise_audit_event(
      v_enterprise_id,
      'member.invitation_expired',
      'enterprise_invitation',
      v_invitation_id,
      pg_catalog.jsonb_build_object('status','pending'),
      pg_catalog.jsonb_build_object('status','expired'),
      pg_catalog.jsonb_build_object('member_id',v_member_id)
    );

    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invitation_expired');
  END IF;

  IF v_caller_email <> v_invitation_email THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',false,
      'reason','invitation_identity_mismatch'
    );
  END IF;

  IF v_target_user_id IS NOT NULL
     AND v_target_user_id <> v_caller_id
  THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',false,
      'reason','invitation_identity_mismatch'
    );
  END IF;

  -- LOCK ORDER #3: membership.
  SELECT em.id, em.status
  INTO v_member_id, v_member_status
  FROM public.enterprise_members em
  WHERE em.enterprise_id=v_enterprise_id
    AND em.user_id=v_caller_id
  FOR UPDATE;

  IF FOUND THEN
    IF v_member_status IN ('active','suspended') THEN
      RETURN pg_catalog.jsonb_build_object(
        'ok',false,
        'reason','membership_conflict',
        'member_status',v_member_status
      );
    END IF;

    IF v_member_status NOT IN ('invited','removed') THEN
      RETURN pg_catalog.jsonb_build_object(
        'ok',false,
        'reason','membership_state_unsupported',
        'member_status',v_member_status
      );
    END IF;

    -- 'removed' is valid here when the invitation was created before this
    -- auth identity existed, or after an older invitation lifecycle ended.
    -- Acceptance reuses the historical membership row; no physical DELETE.
    UPDATE public.enterprise_members
    SET role=v_invitation_role,
        status='active',
        invited_by=(
          SELECT ei.invited_by
          FROM public.enterprise_invitations ei
          WHERE ei.id=v_invitation_id
        ),
        updated_at=pg_catalog.now()
    WHERE id=v_member_id;

  ELSE
    INSERT INTO public.enterprise_members (
      enterprise_id,
      user_id,
      role,
      status,
      invited_by
    )
    SELECT
      ei.enterprise_id,
      v_caller_id,
      ei.role,
      'active',
      ei.invited_by
    FROM public.enterprise_invitations ei
    WHERE ei.id=v_invitation_id
    RETURNING id INTO v_member_id;
  END IF;

  UPDATE public.enterprise_invitations
  SET status='accepted',
      target_user_id=v_caller_id,
      accepted_at=pg_catalog.now(),
      accepted_by=v_caller_id,
      updated_at=pg_catalog.now()
  WHERE id=v_invitation_id;

  PERFORM fixeo_private._write_enterprise_audit_event(
    v_enterprise_id,
    'member.invitation_accepted',
    'enterprise_invitation',
    v_invitation_id,
    pg_catalog.jsonb_build_object(
      'status','pending',
      'role',v_invitation_role
    ),
    pg_catalog.jsonb_build_object(
      'status','accepted',
      'role',v_invitation_role,
      'member_id',v_member_id
    ),
    pg_catalog.jsonb_build_object(
      'accepted_user_id',v_caller_id
    )
  );

  RETURN pg_catalog.jsonb_build_object(
    'ok',true,
    'invitation_id',v_invitation_id,
    'enterprise_id',v_enterprise_id,
    'member_id',v_member_id,
    'role',v_invitation_role,
    'status','active'
  );

EXCEPTION
  WHEN unique_violation THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',false,
      'reason','membership_conflict'
    );

  WHEN OTHERS THEN
    RAISE WARNING '[accept_enterprise_invitation] error: % (SQLSTATE: %)',
      SQLERRM, SQLSTATE;
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','internal_error');
END;
$function$

CREATE OR REPLACE FUNCTION public.accept_my_dispatch_offer_v1(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_artisan_id       uuid;
  v_request_status   text;
  v_queue_status     text;
  v_existing_winner  uuid;
  v_mission_id       uuid;
BEGIN

  /* Authentication required. */
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'unauthenticated'
    );
  END IF;

  IF p_request_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'request_id_required'
    );
  END IF;

  /*
   * Resolve the canonical artisan owned by this account.
   */
  SELECT a.id
  INTO v_artisan_id
  FROM public.artisans a
  WHERE a.owner_user_id = auth.uid()
  LIMIT 1;

  IF v_artisan_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'artisan_not_found'
    );
  END IF;

  /*
   * Serialize acceptance on the canonical request.
   *
   * Two artisans attempting acceptance concurrently will
   * therefore execute this critical section one after another.
   */
  SELECT sr.status
  INTO v_request_status
  FROM public.service_requests sr
  WHERE sr.id = p_request_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'request_not_found'
    );
  END IF;

  /*
   * Verify that THIS authenticated artisan really owns
   * an active queue opportunity for this request.
   */
  SELECT q.execution_status
  INTO v_queue_status
  FROM public.dispatch_execution_queue q
  WHERE q.request_id = p_request_id
    AND q.artisan_id = v_artisan_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'offer_not_found'
    );
  END IF;

  /*
   * Idempotent success if this artisan already won.
   */
  IF v_queue_status = 'ACCEPTED' THEN

    SELECT m.id
    INTO v_mission_id
    FROM public.missions m
    WHERE m.request_id = p_request_id::text
      AND m.artisan_profile_id = v_artisan_id
      AND m.status = 'pending'
    LIMIT 1;

    RETURN jsonb_build_object(
      'ok', true,
      'reason', 'already_accepted',
      'request_id', p_request_id,
      'artisan_id', v_artisan_id,
      'mission_id', v_mission_id
    );
  END IF;

  /*
   * Only an active V2 opportunity may be accepted.
   *
   * QUEUED is allowed for dashboard acceptance.
   * CONTACTED remains allowed for notification-driven acceptance.
   */
  IF v_queue_status NOT IN ('QUEUED', 'CONTACTED') THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'offer_not_active',
      'queue_status', v_queue_status
    );
  END IF;

  /*
   * The request itself is the authoritative winner gate.
   */
  IF v_request_status <> 'new' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'already_claimed',
      'status', v_request_status
    );
  END IF;

  /*
   * Defense in depth: check for an already-persisted pending winner.
   */
  SELECT m.id
  INTO v_existing_winner
  FROM public.missions m
  WHERE m.request_id = p_request_id::text
    AND m.status = 'pending'
  LIMIT 1;

  IF v_existing_winner IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'already_claimed',
      'mission_id', v_existing_winner
    );
  END IF;

  /*
   * Atomic winner mutation.
   *
   * The service_request row is already locked, so another
   * concurrent acceptance cannot pass the "new" gate.
   */
  BEGIN

    INSERT INTO public.missions (
      request_id,
      artisan_profile_id,
      status,
      agreed_price,
      accepted_at
    )
    VALUES (
      p_request_id::text,
      v_artisan_id,
      'pending',
      NULL,
      now()
    )
    RETURNING id
    INTO v_mission_id;

    UPDATE public.service_requests sr
    SET status = 'assigned'
    WHERE sr.id = p_request_id
      AND sr.status = 'new';

    IF NOT FOUND THEN
      RAISE EXCEPTION
        'request acceptance conflict'
        USING ERRCODE = 'P0001';
    END IF;

    UPDATE public.dispatch_execution_queue q
    SET
      execution_status = 'ACCEPTED',
      updated_at = now()
    WHERE q.request_id = p_request_id
      AND q.artisan_id = v_artisan_id;

    UPDATE public.dispatch_execution_queue q
    SET
      execution_status = 'CANCELLED',
      updated_at = now()
    WHERE q.request_id = p_request_id
      AND q.artisan_id <> v_artisan_id
      AND q.execution_status IN ('QUEUED', 'CONTACTED');

  EXCEPTION
    WHEN unique_violation THEN
      RETURN jsonb_build_object(
        'ok', false,
        'reason', 'already_claimed'
      );

    WHEN SQLSTATE 'P0001' THEN
      RETURN jsonb_build_object(
        'ok', false,
        'reason', 'already_claimed'
      );
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'reason', 'accepted',
    'request_id', p_request_id,
    'artisan_id', v_artisan_id,
    'mission_id', v_mission_id
  );

END;
$function$

CREATE OR REPLACE FUNCTION public.accept_my_enterprise_workforce_offer_v1(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_worker_id uuid;
  v_enterprise_id uuid;
  v_offer_id uuid;
  v_offer_status text;
  v_expires_at timestamptz;
  v_request_status text;
  v_assignment_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','unauthenticated');
  END IF;

  SELECT w.id,w.enterprise_id
  INTO v_worker_id,v_enterprise_id
  FROM public.enterprise_workforce_workers w
  JOIN public.enterprise_members em
    ON em.id=w.member_id
   AND em.enterprise_id=w.enterprise_id
  WHERE em.user_id=auth.uid()
    AND em.status='active'
    AND w.status='active'
  LIMIT 1;

  IF v_worker_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','worker_not_found');
  END IF;

  SELECT sr.status
  INTO v_request_status
  FROM public.service_requests sr
  WHERE sr.id=p_request_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','request_not_found');
  END IF;

  SELECT o.id,o.status,o.expires_at
  INTO v_offer_id,v_offer_status,v_expires_at
  FROM public.enterprise_internal_dispatch_offers o
  WHERE o.service_request_id=p_request_id
    AND o.worker_id=v_worker_id
    AND o.enterprise_id=v_enterprise_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','offer_not_found');
  END IF;

  IF v_offer_status='accepted' THEN
    SELECT ia.id
    INTO v_assignment_id
    FROM public.enterprise_internal_assignments ia
    WHERE ia.service_request_id=p_request_id
      AND ia.worker_id=v_worker_id
    LIMIT 1;

    RETURN pg_catalog.jsonb_build_object(
      'ok',true,'reason','already_accepted','assignment_id',v_assignment_id
    );
  END IF;

  IF v_offer_status<>'offered' THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','offer_not_active');
  END IF;

  IF v_expires_at<=now() THEN
    UPDATE public.enterprise_internal_dispatch_offers
    SET status='expired',responded_at=now()
    WHERE id=v_offer_id;
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','offer_expired');
  END IF;

  IF v_request_status<>'new' THEN
    UPDATE public.enterprise_internal_dispatch_offers
    SET status='cancelled',responded_at=now()
    WHERE id=v_offer_id;
    RETURN pg_catalog.jsonb_build_object(
      'ok',false,'reason','already_claimed','status',v_request_status
    );
  END IF;

  INSERT INTO public.enterprise_internal_assignments(
    enterprise_id,service_request_id,worker_id,offer_id,status,assigned_at,updated_at
  )
  VALUES(
    v_enterprise_id,p_request_id,v_worker_id,v_offer_id,'assigned',now(),now()
  )
  RETURNING id INTO v_assignment_id;

  UPDATE public.service_requests
  SET status='assigned'
  WHERE id=p_request_id AND status='new';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'internal_acceptance_conflict' USING ERRCODE='P0001';
  END IF;

  UPDATE public.enterprise_internal_dispatch_offers
  SET status='accepted',responded_at=now()
  WHERE id=v_offer_id;

  UPDATE public.enterprise_internal_dispatch_offers
  SET status='cancelled',responded_at=now()
  WHERE service_request_id=p_request_id
    AND id<>v_offer_id
    AND status='offered';

  UPDATE public.dispatch_execution_queue
  SET execution_status='CANCELLED',updated_at=now()
  WHERE request_id=p_request_id
    AND execution_status IN ('QUEUED','CONTACTED');

  UPDATE public.enterprise_hybrid_dispatch_state
  SET status='internal_assigned',
      fallback_due_at=NULL,
      updated_at=now()
  WHERE service_request_id=p_request_id;

  PERFORM fixeo_private._write_enterprise_audit_event(
    v_enterprise_id,
    'dispatch.internal_accepted',
    'enterprise_internal_assignment',
    v_assignment_id,
    NULL,
    pg_catalog.jsonb_build_object(
      'status','assigned',
      'worker_id',v_worker_id,
      'service_request_id',p_request_id
    ),
    pg_catalog.jsonb_build_object('offer_id',v_offer_id)
  );

  RETURN pg_catalog.jsonb_build_object(
    'ok',true,
    'reason','accepted',
    'assignment_id',v_assignment_id,
    'worker_id',v_worker_id,
    'request_id',p_request_id
  );

EXCEPTION
  WHEN unique_violation OR SQLSTATE 'P0001' THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','already_claimed');
  WHEN OTHERS THEN
    RAISE WARNING '[accept_my_enterprise_workforce_offer_v1] % %',SQLSTATE,SQLERRM;
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','internal_error');
END;
$function$

CREATE OR REPLACE FUNCTION public.accept_quote_v2(p_quote_id uuid)
 RETURNS missions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_quote public.quotes%rowtype;
  v_req public.service_requests%rowtype;
  v_mission public.missions%rowtype;
  v_artisan_uid uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
  select * into v_quote from public.quotes where id=p_quote_id for update;
  if not found or v_quote.status <> 'pending' then raise exception 'QUOTE_NOT_PENDING'; end if;
  select * into v_req from public.service_requests where id=v_quote.request_id for update;
  if not found or v_req.client_profile_id is distinct from v_uid then raise exception 'FORBIDDEN'; end if;

  update public.quotes set status='accepted' where id=v_quote.id;
  update public.quotes set status='rejected'
   where request_id=v_req.id and id<>v_quote.id and status='pending';

  select * into v_mission from public.missions where request_id=v_req.id::text order by created_at desc limit 1 for update;
  if not found then
    insert into public.missions(request_id,client_profile_id,artisan_profile_id,agreed_price,commission_amount,status,accepted_at)
    values(v_req.id::text,v_req.client_profile_id,v_quote.artisan_profile_id,v_quote.proposed_price,
      round(v_quote.proposed_price*0.15,2),'validated',now())
    returning * into v_mission;
  end if;

  select owner_user_id into v_artisan_uid from public.artisans where id=v_quote.artisan_profile_id;
  if v_artisan_uid is not null then
    insert into public.notifications(recipient_user_id,recipient_role,type,title,message,related_entity_type,related_entity_id,metadata)
    values(v_artisan_uid,'artisan','quote_accepted','Devis accepté',
      'Votre devis a été accepté. La mission est maintenant créée.','mission',v_mission.id::text,
      jsonb_build_object('quote_id',v_quote.id,'mission_id',v_mission.id,'request_id',v_req.id));
  end if;
  return v_mission;
end $function$

CREATE OR REPLACE FUNCTION public.admin_targeted_dispatch_notifications_s1b2(p_request_id uuid, p_artisan_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_result jsonb; v_mission uuid;
BEGIN
  v_result := public.admin_targeted_dispatch_v1(p_request_id,p_artisan_id);
  IF v_result->>'ok' IS DISTINCT FROM 'true' THEN RETURN v_result; END IF;
  v_mission := (v_result->>'mission_id')::uuid;
  IF NOT EXISTS (SELECT 1 FROM public.missions m JOIN public.service_requests s ON s.id=p_request_id
    WHERE m.id=v_mission AND m.request_id=p_request_id::text AND m.artisan_profile_id=p_artisan_id
      AND m.status='offered' AND m.accepted_at IS NULL AND s.status='new' AND s.target_artisan_id=p_artisan_id) THEN
    RAISE EXCEPTION 'S1B2 canonical assignment evidence missing' USING ERRCODE='55000';
  END IF;
  INSERT INTO fixeo_private.notification_assignment_events_s1b2(mission_id,request_id,artisan_id)
    VALUES(v_mission,p_request_id,p_artisan_id) ON CONFLICT(mission_id) DO NOTHING;
  RETURN v_result;
END $function$

CREATE OR REPLACE FUNCTION public.admin_targeted_dispatch_v1(p_request_id uuid, p_artisan_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_request_id_text         text;
  v_sr_status               text;

  v_artisan_exists          uuid;

  v_pending_mission_id      uuid;

  v_existing_offer_id       uuid;
  v_existing_offer_artisan  uuid;

  v_dispatch_result         jsonb;
  v_dispatch_reason         text;

  v_new_mission_id          uuid;
  v_new_mission_artisan     uuid;

  v_rows_updated            integer;
  v_fail_reason             text;
BEGIN

  -- ── GUARD 0: required parameters ──────────────────────────
  IF p_request_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'request_id_required'
    );
  END IF;

  IF p_artisan_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'artisan_id_required'
    );
  END IF;

  v_request_id_text := p_request_id::text;


  -- ── GUARD 1: lock canonical service_request ───────────────
  SELECT sr.status
  INTO   v_sr_status
  FROM   public.service_requests sr
  WHERE  sr.id = p_request_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'request_not_found'
    );
  END IF;


  -- Admin targeted dispatch applies only before acceptance.
  IF v_sr_status != 'new' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'request_not_dispatchable',
      'status', v_sr_status
    );
  END IF;


  -- ── GUARD 2: target artisan must exist ────────────────────
  SELECT a.id
  INTO   v_artisan_exists
  FROM   public.artisans a
  WHERE  a.id = p_artisan_id
  LIMIT  1;

  IF v_artisan_exists IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'artisan_not_found'
    );
  END IF;


  -- ── GUARD 3: no accepted winner may already exist ─────────
  SELECT m.id
  INTO   v_pending_mission_id
  FROM   public.missions m
  WHERE  m.request_id = v_request_id_text
    AND  m.status = 'pending'
  LIMIT  1
  FOR UPDATE;

  IF v_pending_mission_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'already_claimed',
      'mission_id', v_pending_mission_id
    );
  END IF;


  -- ── STEP 4: find current active offer, if any ──────────────
  SELECT
    m.id,
    m.artisan_profile_id
  INTO
    v_existing_offer_id,
    v_existing_offer_artisan
  FROM public.missions m
  WHERE m.request_id = v_request_id_text
    AND m.status = 'offered'
  LIMIT 1
  FOR UPDATE;


  -- ==========================================================
  -- ATOMIC MUTATION BLOCK
  --
  -- Any exception inside this block rolls back:
  --   - old offer expiration
  --   - target_artisan_id mutation
  --   - mission created by dispatch_request_v1()
  --
  -- Therefore a failed replacement never destroys the
  -- previously valid offer.
  -- ==========================================================

  BEGIN

    -- ── STEP 5A: same artisan already has active offer ───────
    --
    -- Idempotent Admin action.
    -- Record the explicit target but DO NOT create another mission.

    IF v_existing_offer_id IS NOT NULL
       AND v_existing_offer_artisan = p_artisan_id THEN

      UPDATE public.service_requests
      SET target_artisan_id = p_artisan_id
      WHERE id = p_request_id;

      RETURN jsonb_build_object(
        'ok', true,
        'reason', 'existing_target_offer',
        'request_id', p_request_id,
        'artisan_id', p_artisan_id,
        'mission_id', v_existing_offer_id
      );
    END IF;


    -- ── STEP 5B: expire previous offer when changing artisan ─
    IF v_existing_offer_id IS NOT NULL THEN

      UPDATE public.missions
      SET status = 'expired'
      WHERE id = v_existing_offer_id
        AND status = 'offered';

      GET DIAGNOSTICS v_rows_updated = ROW_COUNT;

      IF v_rows_updated != 1 THEN
        v_fail_reason := 'offer_conflict';

        RAISE EXCEPTION
          'admin_targeted_dispatch_v1: active offer transition conflict'
          USING ERRCODE = 'P0001';
      END IF;

    END IF;


    -- ── STEP 6: persist explicit Admin target ────────────────
    UPDATE public.service_requests
    SET target_artisan_id = p_artisan_id
    WHERE id = p_request_id
      AND status = 'new';

    GET DIAGNOSTICS v_rows_updated = ROW_COUNT;

    IF v_rows_updated != 1 THEN
      v_fail_reason := 'request_conflict';

      RAISE EXCEPTION
        'admin_targeted_dispatch_v1: request no longer dispatchable'
        USING ERRCODE = 'P0001';
    END IF;


    -- ── STEP 7: canonical dispatch engine ────────────────────
    --
    -- dispatch_request_v1() sees target_artisan_id and therefore
    -- restricts candidate selection to p_artisan_id.
    --
    -- It retains all canonical eligibility checks:
    -- availability, service, city/zone, prior mission exclusion,
    -- unique-offer protection, etc.

    v_dispatch_result :=
      public.dispatch_request_v1(p_request_id);


    IF COALESCE(v_dispatch_result ->> 'ok', 'false') != 'true' THEN

      v_fail_reason :=
        COALESCE(
          v_dispatch_result ->> 'reason',
          'dispatch_failed'
        );

      RAISE EXCEPTION
        'admin_targeted_dispatch_v1: targeted dispatch failed: %',
        v_fail_reason
        USING ERRCODE = 'P0001';

    END IF;


    -- ── STEP 8: verify persisted mission ─────────────────────
    --
    -- Never trust ok=true alone.
    -- Verify that the returned mission is actually:
    --   offered
    --   linked to this request
    --   linked to the exact Admin-selected artisan.

    BEGIN
      v_new_mission_id :=
        (v_dispatch_result ->> 'mission_id')::uuid;
    EXCEPTION
      WHEN OTHERS THEN
        v_new_mission_id := NULL;
    END;


    IF v_new_mission_id IS NULL THEN
      v_fail_reason := 'invalid_dispatch_result';

      RAISE EXCEPTION
        'admin_targeted_dispatch_v1: dispatch returned no valid mission_id'
        USING ERRCODE = 'P0001';
    END IF;


    SELECT m.artisan_profile_id
    INTO   v_new_mission_artisan
    FROM   public.missions m
    WHERE  m.id = v_new_mission_id
      AND  m.request_id = v_request_id_text
      AND  m.status = 'offered';

    IF NOT FOUND
       OR v_new_mission_artisan IS DISTINCT FROM p_artisan_id THEN

      v_fail_reason := 'target_verification_failed';

      RAISE EXCEPTION
        'admin_targeted_dispatch_v1: persisted offer does not match requested artisan'
        USING ERRCODE = 'P0001';

    END IF;


    -- ── SUCCESS ──────────────────────────────────────────────
    --
    -- Canonical state now:
    --   service_requests.status            = new
    --   service_requests.target_artisan_id = selected artisan
    --   missions.status                    = offered
    --
    -- claim_mission() remains the ONLY authority that transitions:
    --   service_requests new      → assigned
    --   missions         offered  → pending

    RETURN jsonb_build_object(
      'ok', true,
      'reason', 'targeted_dispatched',
      'request_id', p_request_id,
      'artisan_id', p_artisan_id,
      'mission_id', v_new_mission_id,
      'replaced_mission_id', v_existing_offer_id,
      'dispatch', v_dispatch_result
    );


  EXCEPTION

    -- Expected controlled rollback.
    WHEN SQLSTATE 'P0001' THEN

      RETURN jsonb_build_object(
        'ok', false,
        'reason', COALESCE(v_fail_reason, 'dispatch_failed'),
        'request_id', p_request_id,
        'artisan_id', p_artisan_id
      );


    -- Unexpected failure.
    -- Because this is an EXCEPTION block, PostgreSQL rolls back
    -- every mutation performed inside the atomic block above.
    WHEN OTHERS THEN

      RAISE WARNING
        '[admin_targeted_dispatch_v1] unexpected error: %',
        SQLERRM;

      RETURN jsonb_build_object(
        'ok', false,
        'reason', 'internal_error',
        'request_id', p_request_id,
        'artisan_id', p_artisan_id
      );

  END;

END;
$function$

CREATE OR REPLACE FUNCTION public.artisan_business_accept_quote(p_quote_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_q public.artisan_business_quotes%rowtype;
  v_job uuid;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;

  select *
    into v_q
  from public.artisan_business_quotes
  where id = p_quote_id
    and owner_user_id = v_uid
    and source = 'personal'
  for update;

  if not found then raise exception 'QUOTE_NOT_FOUND'; end if;

  select id into v_job
  from public.artisan_business_jobs
  where quote_id = p_quote_id
    and owner_user_id = v_uid
  limit 1;

  if v_job is not null then
    return v_job;
  end if;

  if v_q.status in ('rejected','expired','cancelled') then
    raise exception 'QUOTE_NOT_ACCEPTABLE';
  end if;

  update public.artisan_business_quotes
  set status = 'accepted',
      accepted_at = coalesce(accepted_at, now()),
      client_decision_at = coalesce(client_decision_at, now()),
      updated_at = now()
  where id = p_quote_id;

  insert into public.artisan_business_jobs(
    owner_user_id, client_id, quote_id, source, title, status, amount, notes
  )
  values(
    v_uid, v_q.client_id, v_q.id, 'personal', v_q.title, 'planned', v_q.total, v_q.description
  )
  returning id into v_job;

  return v_job;
end
$function$

CREATE OR REPLACE FUNCTION public.artisan_business_next_quote_number()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_n integer;
  v_year text := to_char(current_date,'YYYY');
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;

  perform pg_advisory_xact_lock(hashtextextended(v_uid::text, 0));

  select coalesce(max(nullif(substring(quote_number from '([0-9]+)$'),'')::integer), 0) + 1
    into v_n
  from public.artisan_business_quotes
  where owner_user_id = v_uid
    and quote_number like ('DEV-' || v_year || '-%');

  return 'DEV-' || v_year || '-' || lpad(v_n::text, 4, '0');
end
$function$

CREATE OR REPLACE FUNCTION public.artisan_business_validate_links()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.client_id is not null
     and not exists (
       select 1 from public.artisan_business_clients c
       where c.id = new.client_id and c.owner_user_id = new.owner_user_id
     )
  then
    raise exception 'BUSINESS_CLIENT_NOT_OWNED';
  end if;

  if tg_table_name in ('artisan_business_jobs','artisan_business_ledger') then
    if new.quote_id is not null
       and not exists (
         select 1 from public.artisan_business_quotes q
         where q.id = new.quote_id and q.owner_user_id = new.owner_user_id
       )
    then
      raise exception 'BUSINESS_QUOTE_NOT_OWNED';
    end if;
  end if;

  if tg_table_name = 'artisan_business_ledger' then
    if new.job_id is not null
       and not exists (
         select 1 from public.artisan_business_jobs j
         where j.id = new.job_id and j.owner_user_id = new.owner_user_id
       )
    then
      raise exception 'BUSINESS_JOB_NOT_OWNED';
    end if;
  end if;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.assign_enterprise_internal_worker_v1(p_enterprise_id uuid, p_request_id uuid, p_worker_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_site_id uuid;
  v_request_status text;
  v_assignment_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','unauthenticated');
  END IF;

  IF NOT fixeo_private._fixeo_is_enterprise_dispatch_operator(p_enterprise_id) THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','forbidden');
  END IF;

  SELECT erc.site_id,sr.status
  INTO v_site_id,v_request_status
  FROM public.enterprise_request_context erc
  JOIN public.service_requests sr ON sr.id=erc.service_request_id
  WHERE erc.enterprise_id=p_enterprise_id
    AND erc.service_request_id=p_request_id
  FOR UPDATE OF sr;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','request_not_found');
  END IF;

  IF v_request_status<>'new' THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','already_claimed','status',v_request_status);
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.enterprise_workforce_workers w
    JOIN public.enterprise_members em
      ON em.id=w.member_id
     AND em.enterprise_id=w.enterprise_id
    WHERE w.id=p_worker_id
      AND w.enterprise_id=p_enterprise_id
      AND w.status='active'
      AND w.availability='available'
      AND em.status='active'
      AND (
        w.all_sites
        OR EXISTS (
          SELECT 1 FROM public.enterprise_workforce_sites ws
          WHERE ws.worker_id=w.id
            AND ws.enterprise_id=p_enterprise_id
            AND ws.site_id=v_site_id
        )
      )
  ) THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','worker_not_eligible');
  END IF;

  INSERT INTO public.enterprise_internal_assignments(
    enterprise_id,service_request_id,worker_id,status,assigned_at,updated_at
  )
  VALUES(p_enterprise_id,p_request_id,p_worker_id,'assigned',now(),now())
  RETURNING id INTO v_assignment_id;

  UPDATE public.service_requests
  SET status='assigned'
  WHERE id=p_request_id AND status='new';

  UPDATE public.enterprise_internal_dispatch_offers
  SET status='cancelled',responded_at=now()
  WHERE service_request_id=p_request_id AND status='offered';

  UPDATE public.dispatch_execution_queue
  SET execution_status='CANCELLED',updated_at=now()
  WHERE request_id=p_request_id
    AND execution_status IN ('QUEUED','CONTACTED');

  INSERT INTO public.enterprise_hybrid_dispatch_state(
    service_request_id,enterprise_id,mode,status,created_at,updated_at
  )
  VALUES(p_request_id,p_enterprise_id,'internal_only','internal_assigned',now(),now())
  ON CONFLICT (service_request_id)
  DO UPDATE SET
    status='internal_assigned',
    fallback_due_at=NULL,
    updated_at=now();

  PERFORM fixeo_private._write_enterprise_audit_event(
    p_enterprise_id,
    'dispatch.internal_accepted',
    'enterprise_internal_assignment',
    v_assignment_id,
    NULL,
    pg_catalog.jsonb_build_object(
      'status','assigned',
      'worker_id',p_worker_id,
      'service_request_id',p_request_id
    ),
    pg_catalog.jsonb_build_object('source','manager_assignment')
  );

  RETURN pg_catalog.jsonb_build_object(
    'ok',true,'assignment_id',v_assignment_id,'request_id',p_request_id,'worker_id',p_worker_id
  );

EXCEPTION
  WHEN unique_violation THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','already_claimed');
  WHEN OTHERS THEN
    RAISE WARNING '[assign_enterprise_internal_worker_v1] % %',SQLSTATE,SQLERRM;
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','internal_error');
END;
$function$

CREATE OR REPLACE FUNCTION public.assign_enterprise_member_site(p_enterprise_id uuid, p_member_id uuid, p_site_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_caller_id uuid := auth.uid();
  v_caller_role text;
  v_caller_status text;
  v_enterprise_status text;
  v_member_enterprise uuid;
  v_member_role text;
  v_member_status text;
  v_site_enterprise uuid;
  v_assignment_id uuid;
BEGIN
  IF v_caller_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','unauthenticated');
  END IF;

  IF p_enterprise_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','enterprise_required');
  END IF;
  IF p_member_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','member_required');
  END IF;
  IF p_site_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','site_required');
  END IF;

  SELECT ea.status INTO v_enterprise_status
  FROM public.enterprise_accounts ea
  WHERE ea.id=p_enterprise_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','enterprise_not_found');
  END IF;

  IF v_enterprise_status <> 'active' THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',false,'reason','enterprise_not_active',
      'enterprise_status',v_enterprise_status
    );
  END IF;

  IF NOT fixeo_private._fixeo_is_admin() THEN
    SELECT em.role,em.status
    INTO v_caller_role,v_caller_status
    FROM public.enterprise_members em
    WHERE em.enterprise_id=p_enterprise_id
      AND em.user_id=v_caller_id;

    IF NOT FOUND THEN
      RETURN pg_catalog.jsonb_build_object('ok',false,'reason','not_a_member');
    END IF;

    IF v_caller_status <> 'active'
       OR v_caller_role NOT IN ('owner','admin')
    THEN
      RETURN pg_catalog.jsonb_build_object('ok',false,'reason','forbidden');
    END IF;
  END IF;

  SELECT em.enterprise_id,em.role,em.status
  INTO v_member_enterprise,v_member_role,v_member_status
  FROM public.enterprise_members em
  WHERE em.id=p_member_id
  FOR SHARE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','member_not_found');
  END IF;

  IF v_member_enterprise <> p_enterprise_id THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','member_enterprise_mismatch');
  END IF;

  IF v_member_role <> 'site_manager' THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','member_role_not_site_manager');
  END IF;

  IF v_member_status <> 'active' THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','member_not_active');
  END IF;

  SELECT es.enterprise_id
  INTO v_site_enterprise
  FROM public.enterprise_sites es
  WHERE es.id=p_site_id
  FOR SHARE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','site_not_found');
  END IF;

  IF v_site_enterprise <> p_enterprise_id THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','site_enterprise_mismatch');
  END IF;

  SELECT ems.id INTO v_assignment_id
  FROM public.enterprise_member_sites ems
  WHERE ems.enterprise_id=p_enterprise_id
    AND ems.member_id=p_member_id
    AND ems.site_id=p_site_id;

  IF FOUND THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',true,'reason','already_assigned',
      'assignment_id',v_assignment_id
    );
  END IF;

  INSERT INTO public.enterprise_member_sites(
    enterprise_id,member_id,site_id,assigned_by
  )
  VALUES (
    p_enterprise_id,p_member_id,p_site_id,v_caller_id
  )
  RETURNING id INTO v_assignment_id;

  PERFORM fixeo_private._write_enterprise_audit_event(
    p_enterprise_id,
    'member.site_assigned',
    'enterprise_member_site',
    v_assignment_id,
    NULL,
    pg_catalog.jsonb_build_object(
      'assignment_id',v_assignment_id,
      'member_id',p_member_id,
      'site_id',p_site_id
    ),
    pg_catalog.jsonb_build_object(
      'member_id',p_member_id,
      'site_id',p_site_id
    )
  );

  RETURN pg_catalog.jsonb_build_object(
    'ok',true,
    'assignment_id',v_assignment_id,
    'enterprise_id',p_enterprise_id,
    'member_id',p_member_id,
    'site_id',p_site_id
  );

EXCEPTION WHEN OTHERS THEN
  RAISE WARNING '[assign_enterprise_member_site] error: % (SQLSTATE: %)',
    SQLERRM,SQLSTATE;
  RETURN pg_catalog.jsonb_build_object('ok',false,'reason','internal_error');
END;
$function$

CREATE OR REPLACE FUNCTION public.audit_enterprise_rafi_action_v1(p_enterprise_id uuid, p_action_type text, p_target_id uuid, p_result text, p_details jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_actor uuid:=auth.uid();v_role text;v_safe jsonb;
BEGIN
 IF v_actor IS NULL THEN RETURN jsonb_build_object('ok',false,'reason','unauthenticated'); END IF;
 SELECT em.role INTO v_role FROM public.enterprise_members em
 WHERE em.enterprise_id=p_enterprise_id AND em.user_id=v_actor AND em.status='active' LIMIT 1;
 IF v_role IS NULL THEN RETURN jsonb_build_object('ok',false,'reason','forbidden'); END IF;
 IF p_action_type NOT IN ('create_governed_request','propose_internal_assignment','propose_hybrid_dispatch','decide_approval','upsert_control_tower_escalation','prepare_maintenance_action')
 THEN RETURN jsonb_build_object('ok',false,'reason','invalid_action_type'); END IF;
 IF p_result NOT IN ('executed','pending_approval') THEN RETURN jsonb_build_object('ok',false,'reason','invalid_result'); END IF;
 IF p_target_id IS NULL THEN RETURN jsonb_build_object('ok',false,'reason','invalid_target'); END IF;
 IF p_details IS NULL OR jsonb_typeof(p_details)<>'object' THEN RETURN jsonb_build_object('ok',false,'reason','invalid_details'); END IF;
 v_safe:=jsonb_strip_nulls(jsonb_build_object(
   'action_type',p_action_type,'result',p_result,'actor_role',v_role,
   'workflow',left(coalesce(p_details->>'workflow',''),120),
   'governance_status',left(coalesce(p_details->>'governance_status',''),40)
 ));
 PERFORM fixeo_private._write_enterprise_audit_event(
   p_enterprise_id,'rafi.action_confirmed','rafi_action',p_target_id,NULL,
   jsonb_build_object('result',p_result),v_safe
 );
 RETURN jsonb_build_object('ok',true);
EXCEPTION WHEN OTHERS THEN
 RAISE WARNING '[audit_enterprise_rafi_action_v1] % %',SQLSTATE,SQLERRM;
 RETURN jsonb_build_object('ok',false,'reason','internal_error');
END $function$

