CREATE OR REPLACE FUNCTION public.climatisation_repair_artisan_v1(p_mission_id uuid, p_service_code text DEFAULT NULL::text, p_inputs jsonb DEFAULT '{}'::jsonb, p_paid_minor bigint DEFAULT 0, p_proposal_id uuid DEFAULT NULL::uuid, p_same_visit boolean DEFAULT false, p_professional_checks jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m public.missions%ROWTYPE; r public.service_requests%ROWTYPE; original public.fixeo_pricing_offers_v1%ROWTYPE;
 tariff jsonb; previous fixeo_private.climatisation_proposals_v1%ROWTYPE; repair_id uuid;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
 SELECT * INTO m FROM public.missions WHERE id=p_mission_id FOR UPDATE;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.artisans WHERE id=m.artisan_profile_id AND owner_user_id=auth.uid()) THEN
  RAISE EXCEPTION 'Mission not available' USING ERRCODE='42501';
 END IF;
 IF p_service_code IS NULL THEN RETURN fixeo_private.climatisation_state_v1(m.id); END IF;
 SELECT * INTO r FROM public.service_requests WHERE id::text=m.request_id FOR UPDATE;
 SELECT * INTO original FROM public.fixeo_pricing_offers_v1 WHERE id=m.pricing_offer_id;
 tariff:=fixeo_private.climatisation_tariff_v1(p_service_code);
 IF tariff IS NULL OR tariff->>'followup' IS DISTINCT FROM 'true' OR p_inputs IS DISTINCT FROM tariff->'inputs'
  OR p_professional_checks IS DISTINCT FROM tariff->'professional_checks' OR p_same_visit IS DISTINCT FROM true OR p_paid_minor IS NULL OR p_paid_minor NOT IN (0,26000) OR p_proposal_id IS NULL THEN
  RAISE EXCEPTION 'Repair scope, cash credit and same visit must be confirmed' USING ERRCODE='22023';
 END IF;
 SELECT * INTO previous FROM fixeo_private.climatisation_proposals_v1 WHERE id=p_proposal_id;
 IF FOUND THEN
  IF previous.mission_id IS DISTINCT FROM m.id OR previous.artisan_id IS DISTINCT FROM m.artisan_profile_id
   OR previous.diagnostic_paid_minor IS DISTINCT FROM p_paid_minor OR NOT EXISTS(
    SELECT 1 FROM public.fixeo_pricing_offers_v1 WHERE id=previous.repair_offer_id AND service_code=p_service_code AND scope->'inputs'=p_inputs AND scope->'professional_checks'=p_professional_checks
   ) THEN RAISE EXCEPTION 'Idempotency conflict' USING ERRCODE='22023'; END IF;
  RETURN fixeo_private.climatisation_state_v1(m.id);
 END IF;
 IF original.service_code IS DISTINCT FROM 'climatisation.diagnostic' OR original.catalogue_version IS DISTINCT FROM 'climatisation-pilot-v1'
  OR original.client_total_minor IS DISTINCT FROM 26000 OR original.commission_minor IS DISTINCT FROM 6000
  OR r.pricing_offer_id IS DISTINCT FROM original.id OR m.status IS DISTINCT FROM 'pending' OR r.status IS DISTINCT FROM 'in_progress'
  OR m.final_price IS NOT NULL OR coalesce(r.commission_paid,false) OR r.commission_paid_at IS NOT NULL OR coalesce(r.commission_status,'') IN ('payée','paid')
  OR EXISTS(SELECT 1 FROM public.missions WHERE request_id=r.id::text AND id<>m.id AND status IN ('pending','done','validated'))
  OR EXISTS(SELECT 1 FROM fixeo_private.climatisation_decisions_v1 WHERE request_id=r.id AND accepted) THEN
  RAISE EXCEPTION 'Same visit repair is not available' USING ERRCODE='22023';
 END IF;
 INSERT INTO public.fixeo_pricing_offers_v1(offer_key,pricing_version,currency,service_code,catalogue_version,city,scope,vap_minor,materials_minor,commission_minor,client_total_minor,expires_at)
 VALUES(gen_random_uuid(),'vap-bp33-v1','MAD',p_service_code,'climatisation-pilot-v1',original.city,
  jsonb_build_object('kind','SAME_VISIT_REPAIR','mission_id',m.id,'original_offer_id',original.id,'inputs',p_inputs,'professional_checks',p_professional_checks,'label',tariff->>'label','description',tariff->>'scope'),
  (tariff->>'vap_minor')::bigint,0,6000,(tariff->>'total_minor')::bigint,clock_timestamp()+interval '45 minutes') RETURNING id INTO repair_id;
 INSERT INTO fixeo_private.climatisation_proposals_v1(id,mission_id,request_id,artisan_id,original_offer_id,repair_offer_id,diagnostic_paid_minor,same_visit)
 VALUES(p_proposal_id,m.id,r.id,m.artisan_profile_id,original.id,repair_id,p_paid_minor,true);
 RETURN fixeo_private.climatisation_state_v1(m.id);
END $function$

CREATE OR REPLACE FUNCTION public.climatisation_repair_guest_v1(p_tracking_ref text, p_guest_hash text, p_action text DEFAULT 'read'::text, p_proposal_id uuid DEFAULT NULL::uuid, p_expected_paid_minor bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.service_requests%ROWTYPE; m public.missions%ROWTYPE; p fixeo_private.climatisation_proposals_v1%ROWTYPE;
 repair public.fixeo_pricing_offers_v1%ROWTYPE; decision boolean;
BEGIN
 SELECT * INTO r FROM public.service_requests WHERE tracking_ref=p_tracking_ref;
 IF NOT FOUND OR r.guest_token_hash IS NULL OR p_guest_hash IS NULL OR p_guest_hash<>r.guest_token_hash THEN
  RAISE EXCEPTION 'Request not found' USING ERRCODE='42501';
 END IF;
 IF p_action='read' THEN
  SELECT * INTO m FROM public.missions WHERE request_id=r.id::text AND status IN ('pending','done','validated') ORDER BY id LIMIT 1;
  RETURN fixeo_private.climatisation_state_v1(m.id);
 END IF;
 IF p_action IS NULL OR p_action NOT IN ('accept','decline') THEN RAISE EXCEPTION 'Invalid decision' USING ERRCODE='22023'; END IF;
 SELECT * INTO p FROM fixeo_private.climatisation_proposals_v1 WHERE id=p_proposal_id AND request_id=r.id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Proposal not found' USING ERRCODE='22023'; END IF;
 -- Same locking order as proposal, lifecycle and financial mission updates.
 SELECT * INTO m FROM public.missions WHERE id=p.mission_id FOR UPDATE;
 SELECT * INTO r FROM public.service_requests WHERE id=p.request_id FOR UPDATE;
 IF p_guest_hash IS DISTINCT FROM r.guest_token_hash THEN RAISE EXCEPTION 'Request not found' USING ERRCODE='42501'; END IF;
 IF p_expected_paid_minor IS DISTINCT FROM p.diagnostic_paid_minor THEN RAISE EXCEPTION 'Cash credit must match the displayed proposal' USING ERRCODE='22023'; END IF;
 SELECT accepted INTO decision FROM fixeo_private.climatisation_decisions_v1 WHERE proposal_id=p.id;
 IF FOUND THEN
  IF decision IS DISTINCT FROM (p_action='accept') THEN RAISE EXCEPTION 'Decision already recorded' USING ERRCODE='22023'; END IF;
  RETURN fixeo_private.climatisation_state_v1(m.id);
 END IF;
 SELECT * INTO STRICT repair FROM public.fixeo_pricing_offers_v1 WHERE id=p.repair_offer_id;
 IF m.status IS DISTINCT FROM 'pending' OR r.status IS DISTINCT FROM 'in_progress' OR m.final_price IS NOT NULL
  OR coalesce(r.commission_paid,false) OR r.commission_paid_at IS NOT NULL OR coalesce(r.commission_status,'') IN ('payée','paid') OR repair.expires_at<=now()
  OR m.artisan_profile_id IS DISTINCT FROM p.artisan_id OR m.pricing_offer_id IS DISTINCT FROM p.original_offer_id
  OR r.pricing_offer_id IS DISTINCT FROM p.original_offer_id
  OR EXISTS(SELECT 1 FROM fixeo_private.climatisation_proposals_v1 WHERE mission_id=m.id AND sequence_id>p.sequence_id)
  OR EXISTS(SELECT 1 FROM public.missions WHERE request_id=r.id::text AND id<>m.id AND status IN ('pending','done','validated'))
  OR EXISTS(SELECT 1 FROM fixeo_private.climatisation_decisions_v1 WHERE request_id=r.id AND accepted) THEN
  RAISE EXCEPTION 'Proposal no longer available' USING ERRCODE='22023';
 END IF;
 INSERT INTO fixeo_private.climatisation_decisions_v1(proposal_id,mission_id,request_id,accepted) VALUES(p.id,m.id,r.id,p_action='accept');
 IF p_action='accept' THEN UPDATE public.missions SET agreed_price=agreed_price WHERE id=m.id; END IF;
 RETURN fixeo_private.climatisation_state_v1(m.id);
END $function$

CREATE OR REPLACE FUNCTION public.complete_artisan_onboarding()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid               uuid;
  v_artisan_id        uuid;
  v_full_name         text;
  v_service_category  text;
  v_city              text;
  v_claimed           boolean;
  v_claim_status      text;
  v_onboarding_done   boolean;
  v_missing_fields    text[];
BEGIN

  -- ── Guard: authentication ─────────────────────────────────────────────────
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'unauthenticated');
  END IF;

  -- ── Lock owned artisan row ────────────────────────────────────────────────
  -- PRE-READ (non-locking) is unnecessary; go straight to locking SELECT
  -- because we need all fields in one pass and there is no secondary lock.
  SELECT
    a.id,
    a.full_name,
    a.service_category,
    a.city,
    a.claimed,
    a.claim_status,
    a.onboarding_completed
  INTO
    v_artisan_id,
    v_full_name,
    v_service_category,
    v_city,
    v_claimed,
    v_claim_status,
    v_onboarding_done
  FROM public.artisans a
  WHERE a.owner_user_id = v_uid
  LIMIT 1
  FOR UPDATE;

  IF v_artisan_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_owner',
      'message', 'Aucun profil artisan trouvé pour ce compte.');
  END IF;

  -- ── Idempotency: already completed ───────────────────────────────────────
  IF v_onboarding_done = true THEN
    RETURN jsonb_build_object(
      'ok',         true,
      'reason',     'already_completed',
      'artisan_id', v_artisan_id
    );
  END IF;

  -- ── Guard: must be approved ───────────────────────────────────────────────
  IF v_claimed IS NOT TRUE OR v_claim_status != 'approved' THEN
    RETURN jsonb_build_object(
      'ok',     false,
      'reason', 'not_approved',
      'message', 'Le compte artisan doit être approuvé avant de compléter le profil.'
    );
  END IF;

  -- ── Guard: required profile fields ───────────────────────────────────────
  -- Minimum canonical fields: full_name (≥3 chars), service_category, city.
  -- description is optional — not required for dispatch eligibility.
  v_missing_fields := ARRAY[]::text[];
  IF length(trim(COALESCE(v_full_name, ''))) < 3 THEN
    v_missing_fields := v_missing_fields || ARRAY['full_name'];
  END IF;
  IF length(trim(COALESCE(v_service_category, ''))) = 0 THEN
    v_missing_fields := v_missing_fields || ARRAY['service_category'];
  END IF;
  IF length(trim(COALESCE(v_city, ''))) = 0 THEN
    v_missing_fields := v_missing_fields || ARRAY['city'];
  END IF;

  IF array_length(v_missing_fields, 1) > 0 THEN
    RETURN jsonb_build_object(
      'ok',             false,
      'reason',         'profile_incomplete',
      'missing_fields', to_jsonb(v_missing_fields),
      'message',        'Profil incomplet. Champs manquants: ' || array_to_string(v_missing_fields, ', ')
    );
  END IF;

  -- ── Atomic completion: set onboarding_completed=true + availability='available' ──
  -- Security invariants maintained:
  --   owner_user_id  NOT written  (never mutated after registration)
  --   claimed        NOT written  (was true; remains true)
  --   claim_status   NOT written  (was 'approved'; remains 'approved')
  --   verified       NOT written  (always false until admin action)
  UPDATE public.artisans
  SET
    onboarding_completed = true,
    availability         = 'available',
    updated_at           = now()
  WHERE id = v_artisan_id;

  RETURN jsonb_build_object(
    'ok',         true,
    'reason',     'completed',
    'artisan_id', v_artisan_id,
    'message',    'Profil complété. Vous êtes maintenant disponible pour recevoir des missions.'
  );

EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING '[complete_artisan_onboarding] unexpected error for uid %: %', v_uid, SQLERRM;
    RETURN jsonb_build_object('ok', false, 'reason', 'internal_error');
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_mission(p_mission_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_artisan_id         uuid;
  v_request_id         text;
  v_mission_status     text;
  v_mission_artisan    uuid;
  v_sr_status          text;
  v_rows_m             integer;
  v_rows_sr            integer;
  v_mission_status_now text;
BEGIN

  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'unauthenticated');
  END IF;

  SELECT a.id
  INTO   v_artisan_id
  FROM   public.artisans a
  WHERE  a.owner_user_id = auth.uid()
  LIMIT  1;

  IF v_artisan_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'artisan_not_found');
  END IF;

  SELECT m.request_id, m.status, m.artisan_profile_id
  INTO   v_request_id, v_mission_status, v_mission_artisan
  FROM   public.missions m
  WHERE  m.id = p_mission_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'mission_not_found');
  END IF;

  IF v_mission_artisan != v_artisan_id THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_your_mission');
  END IF;

  IF v_mission_status = 'done' THEN

    SELECT sr.status INTO v_sr_status
    FROM   public.service_requests sr
    WHERE  sr.id::text = v_request_id;

    IF v_sr_status IN ('completed', 'validated') THEN
      RETURN jsonb_build_object(
        'ok', true,
        'mission_id', p_mission_id,
        'already_completed', true
      );
    ELSE
      RETURN jsonb_build_object(
        'ok', false,
        'reason', 'inconsistent_state'
      );
    END IF;

  END IF;

  IF v_mission_status != 'pending' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_started');
  END IF;

  SELECT sr.status INTO v_sr_status
  FROM   public.service_requests sr
  WHERE  sr.id::text = v_request_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_request_state');
  END IF;

  IF v_sr_status != 'in_progress' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_started');
  END IF;

  UPDATE public.missions
  SET    status = 'done'
  WHERE  id     = p_mission_id
    AND  status = 'pending';

  GET DIAGNOSTICS v_rows_m = ROW_COUNT;

  IF v_rows_m = 0 THEN

    SELECT m.status INTO v_mission_status_now
    FROM   public.missions m
    WHERE  m.id = p_mission_id;

    SELECT sr.status INTO v_sr_status
    FROM   public.service_requests sr
    WHERE  sr.id::text = v_request_id;

    IF v_mission_status_now IN ('done', 'validated')
       AND v_sr_status IN ('completed', 'validated') THEN

      RETURN jsonb_build_object(
        'ok', true,
        'mission_id', p_mission_id,
        'already_completed', true
      );

    ELSE

      RETURN jsonb_build_object(
        'ok', false,
        'reason', 'inconsistent_state'
      );

    END IF;

  END IF;

  UPDATE public.service_requests
  SET    status = 'completed'
  WHERE  id::text = v_request_id
    AND  status   = 'in_progress';

  GET DIAGNOSTICS v_rows_sr = ROW_COUNT;

  IF v_rows_sr = 0 THEN
    RAISE EXCEPTION
      '[complete_mission] atomicity violation: mission % set done but service_request % could not be set completed (status=%). Rolling back.',
      p_mission_id,
      v_request_id,
      v_sr_status
      USING ERRCODE = 'P0001';
  END IF;

  RETURN jsonb_build_object(
    'ok',         true,
    'mission_id', p_mission_id
  );

EXCEPTION
  WHEN SQLSTATE 'P0001' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'atomicity_error'
    );

  WHEN OTHERS THEN
    RAISE WARNING '[complete_mission] unexpected error: %', SQLERRM;
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'internal_error'
    );
END;

$function$

CREATE OR REPLACE FUNCTION public.confirm_completed_mission(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_client_id       uuid;
  v_request_status  text;
  v_mission_id      uuid;
  v_mission_status  text;
  v_rows_sr         integer;
  v_rows_mission    integer;
BEGIN

  /* Authentication required */
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'unauthenticated'
    );
  END IF;

  v_client_id := auth.uid();

  /*
   * Ownership + current request state.
   * client_profile_id is the canonical client ownership field.
   */
  SELECT sr.status
  INTO v_request_status
  FROM public.service_requests sr
  WHERE sr.id = p_request_id
    AND sr.client_profile_id = v_client_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'request_not_found_or_not_owned'
    );
  END IF;

  /*
   * Idempotent success:
   * request already validated.
   * Verify corresponding mission is also validated.
   */
  IF v_request_status = 'validated' THEN

    SELECT m.id, m.status
    INTO v_mission_id, v_mission_status
    FROM public.missions m
    WHERE m.request_id = p_request_id::text
      AND m.status IN ('done', 'validated')
    ORDER BY
      CASE WHEN m.status = 'validated' THEN 0 ELSE 1 END,
      m.created_at DESC
    LIMIT 1;

    IF v_mission_id IS NULL THEN
      RETURN jsonb_build_object(
        'ok', false,
        'reason', 'mission_not_found'
      );
    END IF;

    IF v_mission_status = 'validated' THEN
      RETURN jsonb_build_object(
        'ok', true,
        'request_id', p_request_id,
        'mission_id', v_mission_id,
        'already_validated', true
      );
    END IF;

    /*
     * Repair safe partial state:
     * SR validated but mission still done.
     */
    UPDATE public.missions m
    SET status = 'validated'
    WHERE m.id = v_mission_id
      AND m.status = 'done';

    GET DIAGNOSTICS v_rows_mission = ROW_COUNT;

    IF v_rows_mission = 0 THEN
      RAISE EXCEPTION
        'confirm_completed_mission: failed to repair mission state for request %',
        p_request_id
        USING ERRCODE = 'P0001';
    END IF;

    RETURN jsonb_build_object(
      'ok', true,
      'request_id', p_request_id,
      'mission_id', v_mission_id,
      'repaired', true
    );
  END IF;

  /* Only completed requests may be client-validated */
  IF v_request_status <> 'completed' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'request_not_completed',
      'status', v_request_status
    );
  END IF;

  /*
   * Find the accepted/completed mission only.
   * Expired/declined competing offers are intentionally ignored.
   */
  SELECT m.id, m.status
  INTO v_mission_id, v_mission_status
  FROM public.missions m
  WHERE m.request_id = p_request_id::text
    AND m.status IN ('done', 'validated')
  ORDER BY
    CASE WHEN m.status = 'done' THEN 0 ELSE 1 END,
    m.created_at DESC
  LIMIT 1;

  IF v_mission_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'completed_mission_not_found'
    );
  END IF;

  /*
   * Step 1 — request:
   * completed → validated
   */
  UPDATE public.service_requests sr
  SET status = 'validated'
  WHERE sr.id = p_request_id
    AND sr.client_profile_id = v_client_id
    AND sr.status = 'completed';

  GET DIAGNOSTICS v_rows_sr = ROW_COUNT;

  IF v_rows_sr = 0 THEN
    RAISE EXCEPTION
      'confirm_completed_mission: service_request transition affected 0 rows for request %',
      p_request_id
      USING ERRCODE = 'P0001';
  END IF;

  /*
   * Step 2 — mission:
   * done → validated
   */
  UPDATE public.missions m
  SET status = 'validated'
  WHERE m.id = v_mission_id
    AND m.status = 'done';

  GET DIAGNOSTICS v_rows_mission = ROW_COUNT;

  IF v_rows_mission = 0 THEN
    RAISE EXCEPTION
      'confirm_completed_mission: mission transition affected 0 rows for mission %',
      v_mission_id
      USING ERRCODE = 'P0001';
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'request_id', p_request_id,
    'mission_id', v_mission_id
  );

EXCEPTION
  WHEN SQLSTATE 'P0001' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'atomicity_error'
    );

  WHEN OTHERS THEN
    RAISE WARNING
      '[confirm_completed_mission] unexpected error: %',
      SQLERRM;

    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'internal_error'
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.confirm_estimator_request_v1(p_context_id text, p_outcome_type text, p_service_code text, p_session_id text, p_amount_mad integer, p_city_slug text, p_client_phone text, p_description text, p_tracking_ref text, p_guest_token_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_context_id       text;
  v_outcome_type     text;
  v_service_code     text;
  v_session_id       text;
  v_city_slug        text;
  v_city              text;
  v_service_category text;
  v_phone             text;
  v_description       text;
  v_tracking_ref      text;
  v_guest_token_hash  text;
  v_idempotency_key   text;

  v_existing_outcome_type text;
  v_existing_service_code text;
  v_existing_session_id   text;
  v_existing_amount_mad   integer;
  v_existing_state        text;
  v_existing_request_id   uuid;

  v_request_id              uuid;
  v_existing_tracking_ref   text;
  v_existing_request_status text;
  v_existing_guest_hash     text;
BEGIN
  v_context_id := pg_catalog.btrim(COALESCE(p_context_id, ''));

  IF v_context_id !~ '^fxctx-[0-9a-f]{32}$' THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'invalid_context_id');
  END IF;

  v_outcome_type := pg_catalog.upper(pg_catalog.btrim(COALESCE(p_outcome_type, '')));

  IF NOT (
    v_outcome_type = ANY (
      ARRAY[
        'PRICE_READY',
        'DIAGNOSTIC_READY',
        'LABOUR_PLUS_PART_READY',
        'ADD_ON_READY'
      ]::text[]
    )
  ) THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'non_payable_outcome');
  END IF;

  v_service_code := pg_catalog.lower(pg_catalog.btrim(COALESCE(p_service_code, '')));

  IF
    v_service_code = ''
    OR pg_catalog.char_length(v_service_code) > 200
    OR v_service_code !~ '^[a-z0-9_]+([.][a-z0-9_]+)+$'
  THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'invalid_service_code');
  END IF;

  v_service_category := pg_catalog.split_part(v_service_code, '.', 1);

  IF NOT (
    v_service_category = ANY (
      ARRAY[
        'plomberie',
        'electricite',
        'serrurerie',
        'climatisation',
        'bricolage',
        'nettoyage',
        'peinture',
        'menuiserie'
      ]::text[]
    )
  ) THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'unsupported_service_category');
  END IF;

  v_session_id := pg_catalog.btrim(COALESCE(p_session_id, ''));

  IF v_session_id = '' OR pg_catalog.char_length(v_session_id) > 200 THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'invalid_session_id');
  END IF;

  IF p_amount_mad IS NULL OR p_amount_mad <= 0 THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'invalid_canonical_amount');
  END IF;

  v_city_slug := pg_catalog.lower(pg_catalog.btrim(COALESCE(p_city_slug, '')));

  v_city :=
    CASE v_city_slug
      WHEN 'casablanca'  THEN 'Casablanca'
      WHEN 'rabat'       THEN 'Rabat'
      WHEN 'marrakech'   THEN 'Marrakech'
      WHEN 'fes'         THEN 'Fès'
      WHEN 'tanger'      THEN 'Tanger'
      WHEN 'agadir'      THEN 'Agadir'
      WHEN 'meknes'      THEN 'Meknès'
      WHEN 'oujda'       THEN 'Oujda'
      WHEN 'kenitra'     THEN 'Kénitra'
      WHEN 'tetouan'     THEN 'Tétouan'
      WHEN 'sale'        THEN 'Salé'
      WHEN 'temara'      THEN 'Temara'
      WHEN 'el-jadida'   THEN 'El Jadida'
      WHEN 'beni-mellal' THEN 'Béni Mellal'
      WHEN 'nador'       THEN 'Nador'
      WHEN 'khouribga'   THEN 'Khouribga'
      WHEN 'safi'        THEN 'Safi'
      WHEN 'taza'        THEN 'Taza'
      WHEN 'ouarzazate'  THEN 'Ouarzazate'
      WHEN 'mohammedia'  THEN 'Mohammedia'
      ELSE NULL
    END;

  IF v_city IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'invalid_city');
  END IF;

  v_phone := pg_catalog.regexp_replace(
    pg_catalog.btrim(COALESCE(p_client_phone, '')),
    '[[:space:]().-]+',
    '',
    'g'
  );

  IF v_phone !~ '^(\+212|0)[5-7][0-9]{8}$' THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'invalid_client_phone');
  END IF;

  v_description := pg_catalog.btrim(COALESCE(p_description, ''));

  IF v_description = '' OR pg_catalog.char_length(v_description) > 1000 THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'invalid_description');
  END IF;

  v_tracking_ref := pg_catalog.upper(pg_catalog.btrim(COALESCE(p_tracking_ref, '')));

  IF
    pg_catalog.char_length(v_tracking_ref) > 32
    OR v_tracking_ref !~ '^FX-[A-Z0-9-]{1,29}$'
  THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'invalid_tracking_ref');
  END IF;

  v_guest_token_hash := pg_catalog.lower(pg_catalog.btrim(COALESCE(p_guest_token_hash, '')));

  IF v_guest_token_hash !~ '^[0-9a-f]{64}$' THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'invalid_guest_token_hash');
  END IF;

  v_idempotency_key := 'estimator:' || v_context_id;

  INSERT INTO public.estimator_context_redemptions (
    context_id,
    outcome_type,
    service_code,
    session_id,
    amount_mad,
    state,
    acquired_at
  )
  VALUES (
    v_context_id,
    v_outcome_type,
    v_service_code,
    v_session_id,
    p_amount_mad,
    'acquired',
    pg_catalog.now()
  )
  ON CONFLICT (context_id)
  DO NOTHING;

  SELECT
    ecr.outcome_type,
    ecr.service_code,
    ecr.session_id,
    ecr.amount_mad,
    ecr.state,
    ecr.service_request_id
  INTO
    v_existing_outcome_type,
    v_existing_service_code,
    v_existing_session_id,
    v_existing_amount_mad,
    v_existing_state,
    v_existing_request_id
  FROM public.estimator_context_redemptions ecr
  WHERE ecr.context_id = v_context_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      '7C.9M.2 invariant failure: redemption row not found after acquisition';
  END IF;

  IF
    v_existing_outcome_type IS DISTINCT FROM v_outcome_type
    OR v_existing_service_code IS DISTINCT FROM v_service_code
    OR v_existing_session_id IS DISTINCT FROM v_session_id
    OR v_existing_amount_mad IS DISTINCT FROM p_amount_mad
  THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'context_identity_mismatch');
  END IF;

  IF v_existing_state = 'committed' THEN
    IF v_existing_request_id IS NULL THEN
      RETURN pg_catalog.jsonb_build_object(
        'ok', false,
        'reason', 'context_already_consumed_without_request'
      );
    END IF;

    SELECT
      sr.tracking_ref,
      sr.status,
      sr.guest_token_hash
    INTO
      v_existing_tracking_ref,
      v_existing_request_status,
      v_existing_guest_hash
    FROM public.service_requests sr
    WHERE sr.id = v_existing_request_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION
        '7C.9M.2 invariant failure: committed redemption references missing request %',
        v_existing_request_id;
    END IF;

    IF
      v_existing_guest_hash IS NULL
      OR v_existing_guest_hash IS DISTINCT FROM v_guest_token_hash
    THEN
      RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'guest_token_mismatch');
    END IF;

    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'replayed', true,
      'request_id', v_existing_request_id,
      'tracking_ref', v_existing_tracking_ref,
      'service_category', v_service_category,
      'service_code', v_service_code,
      'city', v_city,
      'status', v_existing_request_status,
      'outcome_type', v_outcome_type,
      'amount_mad', p_amount_mad
    );
  END IF;

  IF v_existing_request_id IS NOT NULL THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'inconsistent_existing_request_binding'
    );
  END IF;

  IF v_existing_state = 'failed' THEN
    UPDATE public.estimator_context_redemptions
    SET
      state = 'acquired',
      acquired_at = pg_catalog.now(),
      failed_at = NULL,
      failure_reason = NULL,
      booking_ref = NULL,
      order_id = NULL
    WHERE context_id = v_context_id;
  ELSIF v_existing_state <> 'acquired' THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'invalid_redemption_state',
      'state', v_existing_state
    );
  END IF;

  INSERT INTO public.service_requests (
    service_category,
    city,
    description,
    client_phone,
    urgency,
    status,
    idempotency_key,
    tracking_ref,
    guest_token_hash
  )
  VALUES (
    v_service_category,
    v_city,
    v_description,
    v_phone,
    'normale',
    'new',
    v_idempotency_key,
    v_tracking_ref,
    v_guest_token_hash
  )
  RETURNING id
  INTO v_request_id;

  UPDATE public.estimator_context_redemptions
  SET
    state = 'committed',
    service_request_id = v_request_id,
    committed_at = pg_catalog.now(),
    failed_at = NULL,
    failure_reason = NULL
  WHERE context_id = v_context_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      '7C.9M.2 invariant failure: redemption disappeared before commit';
  END IF;

  RETURN pg_catalog.jsonb_build_object(
    'ok', true,
    'replayed', false,
    'request_id', v_request_id,
    'tracking_ref', v_tracking_ref,
    'service_category', v_service_category,
    'service_code', v_service_code,
    'city', v_city,
    'status', 'new',
    'outcome_type', v_outcome_type,
    'amount_mad', p_amount_mad
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.confirm_estimator_request_vap_v1(p_context_id text, p_outcome_type text, p_service_code text, p_session_id text, p_amount_mad numeric, p_city_slug text, p_client_phone text, p_description text, p_tracking_ref text, p_guest_token_hash text, p_offer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_offer public.fixeo_pricing_offers_v1%ROWTYPE;
  v_context_id       text;
  v_outcome_type     text;
  v_service_code     text;
  v_session_id       text;
  v_city_slug        text;
  v_city              text;
  v_service_category text;
  v_phone             text;
  v_description       text;
  v_tracking_ref      text;
  v_guest_token_hash  text;
  v_idempotency_key   text;

  v_existing_outcome_type text;
  v_existing_service_code text;
  v_existing_session_id   text;
  v_existing_amount_mad   numeric;
  v_existing_state        text;
  v_existing_request_id   uuid;

  v_request_id              uuid;
  v_existing_tracking_ref   text;
  v_existing_request_status text;
  v_existing_guest_hash     text;
BEGIN
  SELECT * INTO v_offer FROM public.fixeo_pricing_offers_v1 WHERE id=p_offer_id;
  IF NOT FOUND OR v_offer.pricing_version <> 'vap-bp33-v1'
    OR v_offer.scope->>'context_id' IS DISTINCT FROM p_context_id
    OR v_offer.scope->>'session_id' IS DISTINCT FROM p_session_id
    OR v_offer.scope->>'outcome_type' IS DISTINCT FROM p_outcome_type
    OR v_offer.service_code IS DISTINCT FROM p_service_code
    OR v_offer.city IS DISTINCT FROM p_city_slug
    OR v_offer.client_total_minor::numeric/100 IS DISTINCT FROM p_amount_mad
  THEN RETURN jsonb_build_object('ok',false,'reason','offer_mismatch'); END IF;
  IF v_offer.expires_at <= now() AND NOT EXISTS (
    SELECT 1 FROM public.estimator_context_redemptions WHERE context_id=p_context_id AND state='committed'
  ) THEN RETURN jsonb_build_object('ok',false,'reason','offer_expired'); END IF;
  v_context_id := pg_catalog.btrim(COALESCE(p_context_id, ''));

  IF v_context_id !~ '^fxctx-[0-9a-f]{32}$' THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'invalid_context_id');
  END IF;

  v_outcome_type := pg_catalog.upper(pg_catalog.btrim(COALESCE(p_outcome_type, '')));

  IF NOT (
    v_outcome_type = ANY (
      ARRAY[
        'PRICE_READY',
        'DIAGNOSTIC_READY',
        'LABOUR_PLUS_PART_READY',
        'ADD_ON_READY'
      ]::text[]
    )
  ) THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'non_payable_outcome');
  END IF;

  v_service_code := pg_catalog.lower(pg_catalog.btrim(COALESCE(p_service_code, '')));

  IF
    v_service_code = ''
    OR pg_catalog.char_length(v_service_code) > 200
    OR v_service_code !~ '^[a-z0-9_]+([.][a-z0-9_]+)+$'
  THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'invalid_service_code');
  END IF;

  v_service_category := pg_catalog.split_part(v_service_code, '.', 1);

  IF NOT (
    v_service_category = ANY (
      ARRAY[
        'plomberie',
        'electricite',
        'serrurerie',
        'climatisation',
        'bricolage',
        'nettoyage',
        'peinture',
        'menuiserie', 'jardinage', 'carrelage', 'maconnerie', 'demenagement'
      ]::text[]
    )
  ) THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'unsupported_service_category');
  END IF;

  v_session_id := pg_catalog.btrim(COALESCE(p_session_id, ''));

  IF v_session_id = '' OR pg_catalog.char_length(v_session_id) > 200 THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'invalid_session_id');
  END IF;

  IF p_amount_mad IS NULL OR p_amount_mad <= 0 THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'invalid_canonical_amount');
  END IF;

  v_city_slug := pg_catalog.lower(pg_catalog.btrim(COALESCE(p_city_slug, '')));

  v_city :=
    CASE v_city_slug
      WHEN 'casablanca'  THEN 'Casablanca'
      WHEN 'rabat'       THEN 'Rabat'
      WHEN 'marrakech'   THEN 'Marrakech'
      WHEN 'fes'         THEN 'Fès'
      WHEN 'tanger'      THEN 'Tanger'
      WHEN 'agadir'      THEN 'Agadir'
      WHEN 'meknes'      THEN 'Meknès'
      WHEN 'oujda'       THEN 'Oujda'
      WHEN 'kenitra'     THEN 'Kénitra'
      WHEN 'tetouan'     THEN 'Tétouan'
      WHEN 'sale'        THEN 'Salé'
      WHEN 'temara'      THEN 'Temara'
      WHEN 'el-jadida'   THEN 'El Jadida'
      WHEN 'beni-mellal' THEN 'Béni Mellal'
      WHEN 'nador'       THEN 'Nador'
      WHEN 'khouribga'   THEN 'Khouribga'
      WHEN 'safi'        THEN 'Safi'
      WHEN 'taza'        THEN 'Taza'
      WHEN 'ouarzazate'  THEN 'Ouarzazate'
      WHEN 'mohammedia'  THEN 'Mohammedia'
      ELSE NULL
    END;

  IF v_city IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'invalid_city');
  END IF;

  v_phone := pg_catalog.regexp_replace(
    pg_catalog.btrim(COALESCE(p_client_phone, '')),
    '[[:space:]().-]+',
    '',
    'g'
  );

  IF v_phone !~ '^(\+212|0)[5-7][0-9]{8}$' THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'invalid_client_phone');
  END IF;

  v_description := pg_catalog.btrim(COALESCE(p_description, ''));

  IF v_description = '' OR pg_catalog.char_length(v_description) > 1000 THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'invalid_description');
  END IF;

  IF v_service_code = 'demenagement.manutention_2h' THEN
    v_description := 'Forfait FIXEO : équipe de 2 intervenants pendant 2 heures sur un même site, sans camion ni transport. 690 MAD client ; 600 MAD pour toute l’équipe ; 90 MAD FIXEO. Affaires préparées, accès dégagé sans portage en escalier. Pas de démontage ni objet exceptionnel. Pas de prolongation automatique. ' || pg_catalog.left(v_description, 650);
  END IF;

  v_tracking_ref := pg_catalog.upper(pg_catalog.btrim(COALESCE(p_tracking_ref, '')));

  IF
    pg_catalog.char_length(v_tracking_ref) > 32
    OR v_tracking_ref !~ '^FX-[A-Z0-9-]{1,29}$'
  THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'invalid_tracking_ref');
  END IF;

  v_guest_token_hash := pg_catalog.lower(pg_catalog.btrim(COALESCE(p_guest_token_hash, '')));

  IF v_guest_token_hash !~ '^[0-9a-f]{64}$' THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'invalid_guest_token_hash');
  END IF;

  v_idempotency_key := 'estimator:' || v_context_id;

  INSERT INTO public.estimator_context_redemptions (
    context_id,
    outcome_type,
    service_code,
    session_id,
    amount_mad,
    state,
    acquired_at
  )
  VALUES (
    v_context_id,
    v_outcome_type,
    v_service_code,
    v_session_id,
    p_amount_mad,
    'acquired',
    pg_catalog.now()
  )
  ON CONFLICT (context_id)
  DO NOTHING;

  SELECT
    ecr.outcome_type,
    ecr.service_code,
    ecr.session_id,
    ecr.amount_mad,
    ecr.state,
    ecr.service_request_id
  INTO
    v_existing_outcome_type,
    v_existing_service_code,
    v_existing_session_id,
    v_existing_amount_mad,
    v_existing_state,
    v_existing_request_id
  FROM public.estimator_context_redemptions ecr
  WHERE ecr.context_id = v_context_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      '7C.9M.2 invariant failure: redemption row not found after acquisition';
  END IF;

  IF
    v_existing_outcome_type IS DISTINCT FROM v_outcome_type
    OR v_existing_service_code IS DISTINCT FROM v_service_code
    OR v_existing_session_id IS DISTINCT FROM v_session_id
    OR v_existing_amount_mad IS DISTINCT FROM p_amount_mad
  THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'context_identity_mismatch');
  END IF;

  IF v_existing_state = 'committed' THEN
    IF v_existing_request_id IS NULL THEN
      RETURN pg_catalog.jsonb_build_object(
        'ok', false,
        'reason', 'context_already_consumed_without_request'
      );
    END IF;

    SELECT
      sr.tracking_ref,
      sr.status,
      sr.guest_token_hash
    INTO
      v_existing_tracking_ref,
      v_existing_request_status,
      v_existing_guest_hash
    FROM public.service_requests sr
    WHERE sr.id = v_existing_request_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION
        '7C.9M.2 invariant failure: committed redemption references missing request %',
        v_existing_request_id;
    END IF;

    IF
      v_existing_guest_hash IS NULL
      OR v_existing_guest_hash IS DISTINCT FROM v_guest_token_hash
    THEN
      RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'guest_token_mismatch');
    END IF;

    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'replayed', true,
      'request_id', v_existing_request_id,
      'tracking_ref', v_existing_tracking_ref,
      'service_category', v_service_category,
      'service_code', v_service_code,
      'city', v_city,
      'status', v_existing_request_status,
      'outcome_type', v_outcome_type,
      'amount_mad', p_amount_mad
    );
  END IF;

  IF v_existing_request_id IS NOT NULL THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'inconsistent_existing_request_binding'
    );
  END IF;

  IF v_existing_state = 'failed' THEN
    UPDATE public.estimator_context_redemptions
    SET
      state = 'acquired',
      acquired_at = pg_catalog.now(),
      failed_at = NULL,
      failure_reason = NULL,
      booking_ref = NULL,
      order_id = NULL
    WHERE context_id = v_context_id;
  ELSIF v_existing_state <> 'acquired' THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'invalid_redemption_state',
      'state', v_existing_state
    );
  END IF;

  INSERT INTO public.service_requests (
    service_category,
    city,
    description,
    client_phone,
    urgency,
    status,
    idempotency_key,
    tracking_ref,
    guest_token_hash, pricing_offer_id
  )
  VALUES (
    v_service_category,
    v_city,
    v_description,
    v_phone,
    'normale',
    'new',
    v_idempotency_key,
    v_tracking_ref,
    v_guest_token_hash, p_offer_id
  )
  RETURNING id
  INTO v_request_id;

  UPDATE public.estimator_context_redemptions
  SET
    state = 'committed',
    service_request_id = v_request_id,
    committed_at = pg_catalog.now(),
    failed_at = NULL,
    failure_reason = NULL
  WHERE context_id = v_context_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      '7C.9M.2 invariant failure: redemption disappeared before commit';
  END IF;

  RETURN pg_catalog.jsonb_build_object(
    'ok', true,
    'replayed', false,
    'request_id', v_request_id,
    'tracking_ref', v_tracking_ref,
    'service_category', v_service_category,
    'service_code', v_service_code,
    'city', v_city,
    'status', 'new',
    'outcome_type', v_outcome_type,
    'amount_mad', p_amount_mad
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_client_mission_from_accepted_quote(p_quote_id uuid)
 RETURNS missions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_quote public.quotes%rowtype;
  v_request public.service_requests%rowtype;
  v_mission public.missions%rowtype;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;

  select * into v_quote from public.quotes where id=p_quote_id and status='accepted' for update;
  if not found then raise exception 'ACCEPTED_QUOTE_NOT_FOUND'; end if;

  select * into v_request from public.service_requests where id=v_quote.request_id for update;
  if not found or v_request.client_profile_id is distinct from v_uid then raise exception 'FORBIDDEN'; end if;

  select * into v_mission from public.missions where request_id=v_request.id::text order by created_at desc limit 1;
  if found then return v_mission; end if;

  insert into public.missions(request_id,client_profile_id,artisan_profile_id,agreed_price,commission_amount,status,accepted_at)
  values(v_request.id::text,v_request.client_profile_id,v_quote.artisan_profile_id,v_quote.proposed_price,round(v_quote.proposed_price*0.15,2),'validated',now())
  returning * into v_mission;

  return v_mission;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_diagnostic_critical_request_v1(p_diagnostic jsonb, p_client_phone text, p_tracking_ref text, p_guest_token_hash text, p_ack_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  s fixeo_private.diagnostic_sessions_v1%ROWTYPE;
  r fixeo_private.diagnostic_runs_v1%ROWTYPE;
  sr public.service_requests%ROWTYPE;
  request_id uuid; profile_id uuid; city_label text; trade text; detail text;
BEGIN
  IF p_diagnostic IS NULL OR jsonb_typeof(p_diagnostic) <> 'object'
    OR octet_length(p_diagnostic::text) > 4096
    OR p_diagnostic->'acknowledged' IS DISTINCT FROM 'true'::jsonb
    OR p_ack_version IS DISTINCT FROM 'fixeo-critical-ack-v1'
    THEN RAISE EXCEPTION 'DIAGNOSTIC_ACKNOWLEDGEMENT_REQUIRED'; END IF;
  s := fixeo_private.diagnostic_lock_v1((p_diagnostic->>'session_id')::uuid, p_diagnostic->>'actor');
  IF s.revision IS DISTINCT FROM (p_diagnostic->>'revision')::integer
    OR s.selected_run_id IS DISTINCT FROM (p_diagnostic->>'run_id')::uuid
    OR s.state NOT IN ('ready', 'bound')
    THEN RAISE EXCEPTION 'DIAGNOSTIC_REVISION_CONFLICT'; END IF;
  SELECT * INTO r FROM fixeo_private.diagnostic_runs_v1
    WHERE id=s.selected_run_id AND session_id=s.id;
  IF NOT FOUND OR r.state <> 'complete' OR r.revision <> s.revision
    OR r.result->'safety'->>'version' IS DISTINCT FROM 'fixeo-risk-routing-v2'
    OR r.result->'safety'->>'level' IS DISTINCT FROM 'CRITICAL'
    OR r.result->'safety'->>'stop' IS DISTINCT FROM 'true'
    OR r.result->'safety'->>'urgency' IS DISTINCT FROM 'now'
    OR jsonb_typeof(r.result->'questions') IS DISTINCT FROM 'array'
    OR jsonb_array_length(r.result->'questions') <> 0
    THEN RAISE EXCEPTION 'DIAGNOSTIC_NOT_QUALIFIED'; END IF;
  IF p_client_phone IS NULL OR p_client_phone !~ '^([+]212|0)[5-7][0-9]{8}$'
    OR p_tracking_ref IS NULL OR p_tracking_ref !~ '^FX-[A-Z0-9-]{1,29}$'
    OR p_guest_token_hash IS NULL OR p_guest_token_hash !~ '^[0-9a-f]{64}$'
    THEN RAISE EXCEPTION 'DIAGNOSTIC_INVALID_INPUT'; END IF;
  -- Replay is bound to the same owner, immutable analysis and contact. A retry
  -- cannot create another request or alter an already acknowledged request.
  IF s.service_request_id IS NOT NULL THEN
    SELECT * INTO sr FROM public.service_requests WHERE id=s.service_request_id;
    IF NOT FOUND OR s.booking_context->>'kind' IS DISTINCT FROM 'critical'
      OR s.booking_context->>'risk_level' IS DISTINCT FROM 'CRITICAL'
      OR sr.guest_token_hash IS DISTINCT FROM p_guest_token_hash
      OR sr.client_phone IS DISTINCT FROM p_client_phone
      THEN RAISE EXCEPTION 'DIAGNOSTIC_REQUEST_MISMATCH'; END IF;
    RETURN jsonb_build_object('ok',true,'request_id',sr.id,'tracking_ref',sr.tracking_ref,'replayed',true,'risk_level','CRITICAL','urgency','now');
  END IF;
  IF s.owner_user_id IS NOT NULL THEN
    SELECT id INTO profile_id FROM public.profiles WHERE id=s.owner_user_id;
    IF profile_id IS NULL THEN RAISE EXCEPTION 'DIAGNOSTIC_PROFILE_REQUIRED'; END IF;
  END IF;
  trade := r.result->'trade'->>'value';
  IF trade IS NULL OR trade NOT IN ('plomberie','electricite','serrurerie','climatisation','bricolage',
    'menuiserie','peinture','maconnerie','nettoyage','jardinage','demenagement','carrelage','autre')
    THEN RAISE EXCEPTION 'DIAGNOSTIC_INVALID_TRADE'; END IF;
  city_label := CASE s.city_slug
    WHEN 'casablanca' THEN 'Casablanca' WHEN 'rabat' THEN 'Rabat'
    WHEN 'marrakech' THEN 'Marrakech' WHEN 'fes' THEN 'Fès'
    WHEN 'tanger' THEN 'Tanger' WHEN 'agadir' THEN 'Agadir'
    WHEN 'meknes' THEN 'Meknès' WHEN 'oujda' THEN 'Oujda'
    WHEN 'kenitra' THEN 'Kénitra' WHEN 'tetouan' THEN 'Tétouan'
    WHEN 'sale' THEN 'Salé' WHEN 'temara' THEN 'Temara'
    WHEN 'el-jadida' THEN 'El Jadida' WHEN 'beni-mellal' THEN 'Béni Mellal'
    WHEN 'khouribga' THEN 'Khouribga' WHEN 'safi' THEN 'Safi'
    WHEN 'nador' THEN 'Nador' WHEN 'taza' THEN 'Taza'
    WHEN 'ouarzazate' THEN 'Ouarzazate' WHEN 'mohammedia' THEN 'Mohammedia' ELSE NULL END;
  IF city_label IS NULL THEN RAISE EXCEPTION 'DIAGNOSTIC_INVALID_CITY'; END IF;
  detail := left('DIAGNOSTIC CRITICAL — consignes de sécurité reconnues. FIXEO ne remplace jamais les secours. '
    || coalesce(nullif(btrim(s.input->>'description'),''),r.result->'problem'->>'value','Danger immédiat signalé.'),1000);
  -- Use the existing immediate urgency (now); preserve explicit CRITICAL and
  -- acknowledgement in the Diagnostic booking context. No new global enum.
  INSERT INTO public.service_requests(service_category,city,description,client_phone,urgency,status,
    idempotency_key,tracking_ref,guest_token_hash,client_profile_id)
  VALUES(trade,city_label,detail,p_client_phone,'now','new','diagnostic-critical:'||s.id::text,
    p_tracking_ref,p_guest_token_hash,profile_id) RETURNING id INTO request_id;
  -- Existing binding and retention rules, in this same atomic transaction.
  PERFORM fixeo_private.diagnostic_bind_v1(p_diagnostic,request_id,NULL,jsonb_build_object(
    'kind','critical','service_category',trade,'urgency','now','risk_level','CRITICAL',
    'tracking_ref',p_tracking_ref,'safety_version','fixeo-risk-routing-v2',
    'acknowledgement',jsonb_build_object('accepted',true,'version',p_ack_version,'run_id',r.id,'at',now())));
  RETURN jsonb_build_object('ok',true,'request_id',request_id,'tracking_ref',p_tracking_ref,
    'replayed',false,'risk_level','CRITICAL','urgency','now');
END $function$

CREATE OR REPLACE FUNCTION public.create_enterprise_account(p_name text, p_legal_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_caller_id      uuid;
  v_caller_exists  boolean;
  v_already_owner  boolean;
  v_enterprise_id  uuid;
  v_name           text;
  v_legal_name     text;
BEGIN

  -- Guard 1: caller must be authenticated
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'unauthenticated'
    );
  END IF;

  -- Guard 2: caller must exist in public.users
  SELECT EXISTS (
    SELECT 1
    FROM public.users u
    WHERE u.id = v_caller_id
  )
  INTO v_caller_exists;

  IF NOT v_caller_exists THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'user_not_found'
    );
  END IF;

  -- Guard 3: V1 bootstrap abuse control.
  -- One active owner membership per user in V1.
  SELECT EXISTS (
    SELECT 1
    FROM public.enterprise_members em
    WHERE em.user_id = v_caller_id
      AND em.role = 'owner'
      AND em.status = 'active'
  )
  INTO v_already_owner;

  IF v_already_owner THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'already_owner'
    );
  END IF;

  -- Guard 4: validate and normalize account name.
  IF p_name IS NULL
     OR pg_catalog.char_length(pg_catalog.btrim(p_name)) < 1
  THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'name_required'
    );
  END IF;

  v_name := pg_catalog.btrim(p_name);

  IF pg_catalog.char_length(v_name) > 200 THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'name_too_long'
    );
  END IF;

  -- Guard 5: validate and normalize legal_name if provided.
  IF p_legal_name IS NOT NULL THEN
    v_legal_name := pg_catalog.btrim(p_legal_name);

    IF pg_catalog.char_length(v_legal_name) < 1
       OR pg_catalog.char_length(v_legal_name) > 300
    THEN
      RETURN pg_catalog.jsonb_build_object(
        'ok', false,
        'reason', 'legal_name_invalid'
      );
    END IF;
  ELSE
    v_legal_name := NULL;
  END IF;

  -- Atomic account insert.
  INSERT INTO public.enterprise_accounts (
    name,
    legal_name,
    status
  )
  VALUES (
    v_name,
    v_legal_name,
    'active'
  )
  RETURNING id INTO v_enterprise_id;

  -- Atomic founding-owner membership insert.
  INSERT INTO public.enterprise_members (
    enterprise_id,
    user_id,
    role,
    status,
    invited_by
  )
  VALUES (
    v_enterprise_id,
    v_caller_id,
    'owner',
    'active',
    NULL
  );

  -- Audit only after both business rows exist.
  PERFORM fixeo_private._write_enterprise_audit_event(
    v_enterprise_id,
    'account.created',
    'enterprise_account',
    v_enterprise_id,
    NULL,
    pg_catalog.jsonb_build_object(
      'name', v_name,
      'legal_name', v_legal_name,
      'status', 'active'
    ),
    pg_catalog.jsonb_build_object(
      'founding_owner_user_id', v_caller_id
    )
  );

  RETURN pg_catalog.jsonb_build_object(
    'ok', true,
    'enterprise_id', v_enterprise_id
  );

EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING
      '[create_enterprise_account] unexpected error: %',
      SQLERRM;

    RETURN pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'internal_error'
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_enterprise_invitation(p_enterprise_id uuid, p_email text, p_role text, p_expires_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_enterprise_status text;
  v_caller_id uuid;
  v_caller_role text;
  v_caller_status text;

  v_email text;

  v_auth_match_count integer;
  v_auth_user_id uuid;
  v_public_user_exists boolean;

  v_existing_member_id uuid;
  v_existing_member_status text;

  v_old_invitation_id uuid;
  v_old_target_user_id uuid;
  v_old_member_id uuid;
  v_old_member_status text;

  v_raw_token text;
  v_token_hash text;

  v_invitation_id uuid;
  v_member_id uuid;
BEGIN
  v_caller_id := auth.uid();

  IF v_caller_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','unauthenticated');
  END IF;

  v_email := pg_catalog.lower(pg_catalog.btrim(p_email));

  IF v_email IS NULL
     OR pg_catalog.char_length(v_email) < 3
     OR pg_catalog.char_length(v_email) > 320
     OR pg_catalog.strpos(v_email,'@') <= 1
  THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invalid_email');
  END IF;

  IF p_role IS NULL
     OR p_role NOT IN (
       'admin',
       'operations_manager',
       'site_manager',
       'reporter',
       'viewer'
     )
  THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invalid_role');
  END IF;

  IF p_expires_at IS NULL
     OR p_expires_at <= pg_catalog.now()
     OR p_expires_at > pg_catalog.now() + interval '30 days'
  THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invalid_expiry');
  END IF;

  -- LOCK ORDER #1: enterprise account.
  SELECT ea.status
  INTO v_enterprise_status
  FROM public.enterprise_accounts ea
  WHERE ea.id = p_enterprise_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','enterprise_not_found');
  END IF;

  IF v_enterprise_status <> 'active' THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','enterprise_not_active',
      'enterprise_status',v_enterprise_status);
  END IF;

  SELECT em.role, em.status
  INTO v_caller_role, v_caller_status
  FROM public.enterprise_members em
  WHERE em.enterprise_id = p_enterprise_id
    AND em.user_id = v_caller_id;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','not_a_member');
  END IF;

  IF v_caller_status <> 'active' THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','caller_not_active');
  END IF;

  IF v_caller_role NOT IN ('owner','admin') THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','forbidden');
  END IF;

  -- LOCK ORDER #2: stale/current invitation for this Enterprise+email.
  SELECT ei.id, ei.target_user_id
  INTO v_old_invitation_id, v_old_target_user_id
  FROM public.enterprise_invitations ei
  WHERE ei.enterprise_id = p_enterprise_id
    AND ei.email_normalized = v_email
    AND ei.status = 'pending'
  ORDER BY ei.created_at DESC
  LIMIT 1
  FOR UPDATE;

  IF FOUND THEN
    IF (
      SELECT ei.expires_at
      FROM public.enterprise_invitations ei
      WHERE ei.id = v_old_invitation_id
    ) > pg_catalog.now()
    THEN
      RETURN pg_catalog.jsonb_build_object(
        'ok',false,
        'reason','invitation_pending'
      );
    END IF;

    -- Expire stale pending invitation.
    UPDATE public.enterprise_invitations
    SET status = 'expired',
        updated_at = pg_catalog.now()
    WHERE id = v_old_invitation_id;

    -- LOCK ORDER #3: membership. Retire only an invited membership associated
    -- with the same resolved target. No physical DELETE.
    IF v_old_target_user_id IS NOT NULL THEN
      SELECT em.id, em.status
      INTO v_old_member_id, v_old_member_status
      FROM public.enterprise_members em
      WHERE em.enterprise_id = p_enterprise_id
        AND em.user_id = v_old_target_user_id
      FOR UPDATE;

      IF FOUND AND v_old_member_status = 'invited' THEN
        UPDATE public.enterprise_members
        SET status = 'removed',
            updated_at = pg_catalog.now()
        WHERE id = v_old_member_id;
      END IF;
    END IF;

    PERFORM fixeo_private._write_enterprise_audit_event(
      p_enterprise_id,
      'member.invitation_expired',
      'enterprise_invitation',
      v_old_invitation_id,
      pg_catalog.jsonb_build_object('status','pending'),
      pg_catalog.jsonb_build_object('status','expired'),
      pg_catalog.jsonb_build_object('member_id',v_old_member_id)
    );
  END IF;

  -- Resolve normalized email against auth.users, never public.users email.
  SELECT COUNT(*)
  INTO v_auth_match_count
  FROM auth.users au
  WHERE pg_catalog.lower(pg_catalog.btrim(au.email::text)) = v_email;

  IF v_auth_match_count > 1 THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',false,
      'reason','ambiguous_email_identity'
    );
  END IF;

  IF v_auth_match_count = 0 THEN
    v_auth_user_id := NULL;
  ELSE
    -- Exactly one normalized auth.users identity exists.
    SELECT au.id
    INTO STRICT v_auth_user_id
    FROM auth.users au
    WHERE pg_catalog.lower(pg_catalog.btrim(au.email::text)) = v_email;

    SELECT EXISTS (
      SELECT 1
      FROM public.users u
      WHERE u.id = v_auth_user_id
    )
    INTO v_public_user_exists;

    IF NOT v_public_user_exists THEN
      RETURN pg_catalog.jsonb_build_object(
        'ok',false,
        'reason','identity_not_ready'
      );
    END IF;
  END IF;

  -- Existing membership handling.
  IF v_auth_user_id IS NOT NULL THEN
    SELECT em.id, em.status
    INTO v_existing_member_id, v_existing_member_status
    FROM public.enterprise_members em
    WHERE em.enterprise_id = p_enterprise_id
      AND em.user_id = v_auth_user_id
    FOR UPDATE;

    IF FOUND THEN
      IF v_existing_member_status IN ('active','suspended') THEN
        RETURN pg_catalog.jsonb_build_object(
          'ok',false,
          'reason','already_member',
          'member_id',v_existing_member_id,
          'member_status',v_existing_member_status
        );
      END IF;

      IF v_existing_member_status = 'invited' THEN
        -- No current pending invitation exists at this point. An invited row
        -- without a live pending invitation is stale and is safely re-used.
        UPDATE public.enterprise_members
        SET role = p_role,
            invited_by = v_caller_id,
            updated_at = pg_catalog.now()
        WHERE id = v_existing_member_id;

        v_member_id := v_existing_member_id;

      ELSIF v_existing_member_status = 'removed' THEN
        UPDATE public.enterprise_members
        SET role = p_role,
            status = 'invited',
            invited_by = v_caller_id,
            updated_at = pg_catalog.now()
        WHERE id = v_existing_member_id;

        v_member_id := v_existing_member_id;

      ELSE
        RETURN pg_catalog.jsonb_build_object(
          'ok',false,
          'reason','membership_state_unsupported'
        );
      END IF;
    END IF;
  END IF;

  -- Generate token inside PostgreSQL. Raw token is never stored.
  v_raw_token :=
    pg_catalog.encode(
      extensions.gen_random_bytes(32),
      'hex'
    );

  v_token_hash :=
    pg_catalog.encode(
      extensions.digest(
        pg_catalog.convert_to(v_raw_token,'UTF8'),
        'sha256'
      ),
      'hex'
    );

  INSERT INTO public.enterprise_invitations (
    enterprise_id,
    email_normalized,
    role,
    invited_by,
    target_user_id,
    token_hash,
    status,
    expires_at
  )
  VALUES (
    p_enterprise_id,
    v_email,
    p_role,
    v_caller_id,
    v_auth_user_id,
    v_token_hash,
    'pending',
    p_expires_at
  )
  RETURNING id INTO v_invitation_id;

  IF v_auth_user_id IS NOT NULL AND v_member_id IS NULL THEN
    INSERT INTO public.enterprise_members (
      enterprise_id,
      user_id,
      role,
      status,
      invited_by
    )
    VALUES (
      p_enterprise_id,
      v_auth_user_id,
      p_role,
      'invited',
      v_caller_id
    )
    RETURNING id INTO v_member_id;
  END IF;

  PERFORM fixeo_private._write_enterprise_audit_event(
    p_enterprise_id,
    'member.invited',
    'enterprise_invitation',
    v_invitation_id,
    NULL,
    pg_catalog.jsonb_build_object(
      'role',p_role,
      'status','pending',
      'target_user_resolved',(v_auth_user_id IS NOT NULL)
    ),
    pg_catalog.jsonb_build_object('member_id',v_member_id)
  );

  RETURN pg_catalog.jsonb_build_object(
    'ok',true,
    'invitation_id',v_invitation_id,
    'invitation_token',v_raw_token,
    'member_id',v_member_id,
    'target_user_resolved',(v_auth_user_id IS NOT NULL),
    'expires_at',p_expires_at
  );

EXCEPTION
  WHEN unique_violation THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',false,
      'reason','invitation_conflict'
    );

  WHEN OTHERS THEN
    RAISE WARNING '[create_enterprise_invitation] error: % (SQLSTATE: %)',
      SQLERRM, SQLSTATE;
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','internal_error');
END;
$function$

CREATE OR REPLACE FUNCTION public.create_enterprise_request(p_enterprise_id uuid, p_site_id uuid, p_service_category text, p_description text, p_urgency text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_caller_id          uuid;
  v_caller_exists      boolean;
  v_enterprise_active  boolean;
  v_enterprise_status  text;
  v_authorized         boolean;
  v_site_enterprise    uuid;
  v_site_status        text;
  v_city               text;
  v_service_category   text;
  v_description        text;
  v_urgency            text;
  v_sla_urgency        text;
  v_sr_id              uuid;
  v_ctx_id             uuid;
  v_policy_id           uuid;
  v_policy_urgency      text;
  v_target_minutes      integer;
  v_started_at          timestamptz;
  v_at_risk_at          timestamptz;
  v_due_at              timestamptz;
  v_request_sla_id      uuid;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'unauthenticated');
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.users u WHERE u.id = v_caller_id
  ) INTO v_caller_exists;

  IF NOT COALESCE(v_caller_exists, false) THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'user_not_found');
  END IF;

  IF p_enterprise_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'enterprise_required');
  END IF;

  IF p_site_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'site_required');
  END IF;

  -- Preserve serialization against account lifecycle transitions.
  SELECT ea.status
  INTO v_enterprise_status
  FROM public.enterprise_accounts ea
  WHERE ea.id = p_enterprise_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'enterprise_not_found');
  END IF;

  v_enterprise_active := (v_enterprise_status = 'active');

  IF NOT COALESCE(v_enterprise_active, false) THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'enterprise_not_active',
      'enterprise_status', v_enterprise_status
    );
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.enterprise_members em
    WHERE em.enterprise_id = p_enterprise_id
      AND em.user_id = v_caller_id
      AND em.status = 'active'
      AND em.role IN (
        'owner',
        'admin',
        'operations_manager',
        'site_manager',
        'reporter'
      )
  ) INTO v_authorized;

  IF NOT COALESCE(v_authorized, false) THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'forbidden');
  END IF;

  SELECT es.enterprise_id, es.status, es.city
  INTO v_site_enterprise, v_site_status, v_city
  FROM public.enterprise_sites es
  WHERE es.id = p_site_id
  FOR SHARE;

  IF v_site_enterprise IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'site_not_found');
  END IF;

  IF v_site_enterprise <> p_enterprise_id THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'site_enterprise_mismatch');
  END IF;

  -- BP15 delta only: enforce effective site scope.
  IF NOT fixeo_private._fixeo_can_access_enterprise_site(p_enterprise_id,p_site_id) THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'site_forbidden');
  END IF;

  IF v_site_status <> 'active' THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'site_inactive');
  END IF;

  IF p_service_category IS NULL
     OR pg_catalog.char_length(pg_catalog.btrim(p_service_category)) < 1
  THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'service_category_required');
  END IF;

  v_service_category := pg_catalog.btrim(p_service_category);

  IF p_description IS NULL
     OR pg_catalog.char_length(pg_catalog.btrim(p_description)) < 1
  THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'description_required');
  END IF;

  v_description := pg_catalog.btrim(p_description);

  IF p_urgency IS NOT NULL THEN
    IF p_urgency NOT IN ('normale', 'urgent', 'now') THEN
      RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'urgency_invalid');
    END IF;
    v_urgency := p_urgency;
  ELSE
    v_urgency := NULL;
  END IF;

  -- Compatibility normalization used ONLY for SLA policy lookup.
  v_sla_urgency := CASE v_urgency
    WHEN 'now' THEN 'urgent'
    WHEN 'urgent' THEN 'high'
    WHEN 'normale' THEN 'normal'
    ELSE 'normal'
  END;

  -- Lock the selected policy so its contractual values cannot change between
  -- resolution and snapshot insertion.
  SELECT p.id, p.urgency, p.acceptance_target_minutes
  INTO v_policy_id, v_policy_urgency, v_target_minutes
  FROM public.enterprise_sla_policies p
  WHERE p.enterprise_id=p_enterprise_id
    AND p.status='active'
    AND (p.site_id=p_site_id OR p.site_id IS NULL)
    AND (p.urgency=v_sla_urgency OR p.urgency IS NULL)
  ORDER BY
    CASE WHEN p.site_id=p_site_id THEN 0 ELSE 1 END,
    CASE WHEN p.urgency=v_sla_urgency THEN 0 ELSE 1 END
  LIMIT 1
  FOR SHARE;

  IF v_policy_id IS NULL THEN
    -- Built-in FIXEO defaults: no manual SLA configuration is required.
    -- policy_id remains NULL to make the default source explicit in the
    -- immutable snapshot.
    v_policy_urgency := v_sla_urgency;
    v_target_minutes := CASE v_sla_urgency
      WHEN 'urgent' THEN 15
      WHEN 'high'   THEN 30
      WHEN 'normal' THEN 120
      WHEN 'low'    THEN 240
      ELSE NULL
    END;

    IF v_target_minutes IS NULL THEN
      RAISE EXCEPTION 'bp12_unmapped_sla_urgency';
    END IF;
  END IF;

  INSERT INTO public.service_requests (
    service_category,
    city,
    description,
    urgency,
    client_profile_id,
    status
  )
  VALUES (
    v_service_category,
    v_city,
    v_description,
    v_urgency,
    NULL,
    'new'
  )
  RETURNING id, created_at
  INTO v_sr_id, v_started_at;

  -- Defensive fallback only if legacy created_at were ever NULL.
  v_started_at := COALESCE(v_started_at, pg_catalog.now());

  INSERT INTO public.enterprise_request_context (
    enterprise_id,
    site_id,
    service_request_id,
    created_by
  )
  VALUES (
    p_enterprise_id,
    p_site_id,
    v_sr_id,
    v_caller_id
  )
  RETURNING id INTO v_ctx_id;

  v_at_risk_at :=
    v_started_at
    + (pg_catalog.make_interval(mins => v_target_minutes) * 0.75);

  v_due_at :=
    v_started_at
    + pg_catalog.make_interval(mins => v_target_minutes);

  INSERT INTO public.enterprise_request_sla (
    service_request_id,
    enterprise_id,
    site_id,
    policy_id,
    policy_urgency,
    request_urgency,
    acceptance_target_minutes,
    started_at,
    at_risk_at,
    due_at
  )
  VALUES (
    v_sr_id,
    p_enterprise_id,
    p_site_id,
    v_policy_id,
    v_policy_urgency,
    v_urgency,
    v_target_minutes,
    v_started_at,
    v_at_risk_at,
    v_due_at
  )
  RETURNING id INTO v_request_sla_id;

  -- Preserve existing request.created audit event.
  PERFORM fixeo_private._write_enterprise_audit_event(
    p_enterprise_id,
    'request.created',
    'service_request',
    v_sr_id,
    NULL,
    pg_catalog.jsonb_build_object(
      'service_request_id', v_sr_id,
      'enterprise_request_context_id', v_ctx_id,
      'site_id', p_site_id,
      'service_category', v_service_category,
      'urgency', v_urgency
    ),
    pg_catalog.jsonb_build_object(
      'enterprise_request_context_id', v_ctx_id
    )
  );

  -- Add immutable SLA snapshot audit.
  PERFORM fixeo_private._write_enterprise_audit_event(
    p_enterprise_id,
    'sla.snapshot_created',
    'service_request',
    v_sr_id,
    NULL,
    pg_catalog.jsonb_build_object(
      'request_sla_id', v_request_sla_id,
      'policy_id', v_policy_id,
      'policy_source',
        CASE WHEN v_policy_id IS NULL THEN 'fixeo_default' ELSE 'enterprise_policy' END,
      'policy_urgency', v_policy_urgency,
      'request_urgency', v_urgency,
      'acceptance_target_minutes', v_target_minutes,
      'started_at', v_started_at,
      'at_risk_at', v_at_risk_at,
      'due_at', v_due_at
    ),
    pg_catalog.jsonb_build_object(
      'enterprise_request_context_id', v_ctx_id,
      'site_id', p_site_id
    )
  );

  RETURN pg_catalog.jsonb_build_object(
    'ok', true,
    'service_request_id', v_sr_id,
    'enterprise_request_context_id', v_ctx_id,
    'enterprise_id', p_enterprise_id,
    'site_id', p_site_id,
    'request_sla_id', v_request_sla_id,
    'sla_policy_id', v_policy_id,
    'sla_policy_source',
      CASE WHEN v_policy_id IS NULL THEN 'fixeo_default' ELSE 'enterprise_policy' END,
    'sla_status', 'ON_TRACK',
    'sla_at_risk_at', v_at_risk_at,
    'sla_due_at', v_due_at
  );

EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING '[create_enterprise_request] unexpected error: % (SQLSTATE: %)',
      SQLERRM, SQLSTATE;

    RETURN pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'internal_error'
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_enterprise_request_hybrid(p_enterprise_id uuid, p_site_id uuid, p_service_category text, p_description text, p_urgency text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_created jsonb;
  v_request_id uuid;
  v_dispatch jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','unauthenticated');
  END IF;

  PERFORM pg_catalog.set_config('fixeo.enterprise_dispatch_deferred','on',true);

  SELECT public.create_enterprise_request(
    p_enterprise_id,
    p_site_id,
    p_service_category,
    p_description,
    p_urgency
  )
  INTO v_created;

  PERFORM pg_catalog.set_config('fixeo.enterprise_dispatch_deferred','off',true);

  IF v_created IS NULL OR COALESCE((v_created->>'ok')::boolean,false) IS NOT TRUE THEN
    RETURN COALESCE(
      v_created,
      pg_catalog.jsonb_build_object('ok',false,'reason','create_failed')
    );
  END IF;

  v_request_id := (v_created->>'service_request_id')::uuid;
  v_dispatch := public.dispatch_enterprise_hybrid_v1(v_request_id);

  RETURN v_created || pg_catalog.jsonb_build_object('dispatch',v_dispatch);

EXCEPTION WHEN OTHERS THEN
  PERFORM pg_catalog.set_config('fixeo.enterprise_dispatch_deferred','off',true);
  RAISE WARNING '[create_enterprise_request_hybrid] % %',SQLSTATE,SQLERRM;
  RETURN pg_catalog.jsonb_build_object('ok',false,'reason','internal_error');
END;
$function$

CREATE OR REPLACE FUNCTION public.create_enterprise_site(p_enterprise_id uuid, p_name text, p_city text, p_site_code text DEFAULT NULL::text, p_address_line text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_caller_id      uuid;
  v_caller_exists  boolean;
  v_authorized     boolean;
  v_enterprise_status text;
  v_name           text;
  v_city           text;
  v_site_code      text;
  v_address_line   text;
  v_site_id        uuid;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'unauthenticated');
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.users u
    WHERE u.id = v_caller_id
  ) INTO v_caller_exists;

  IF NOT v_caller_exists THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'user_not_found');
  END IF;

  IF p_enterprise_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'enterprise_required');
  END IF;

  SELECT ea.status
  INTO v_enterprise_status
  FROM public.enterprise_accounts ea
  WHERE ea.id = p_enterprise_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','enterprise_not_found');
  END IF;

  IF v_enterprise_status <> 'active' THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','enterprise_not_active',
      'enterprise_status',v_enterprise_status);
  END IF;

  SELECT fixeo_private._fixeo_is_enterprise_manager(p_enterprise_id)
  INTO v_authorized;

  IF NOT COALESCE(v_authorized, false) THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'forbidden');
  END IF;

  IF p_name IS NULL OR pg_catalog.char_length(pg_catalog.btrim(p_name)) < 1 THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'name_required');
  END IF;

  v_name := pg_catalog.btrim(p_name);
  IF pg_catalog.char_length(v_name) > 200 THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'name_too_long');
  END IF;

  IF p_city IS NULL OR pg_catalog.char_length(pg_catalog.btrim(p_city)) < 1 THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'city_required');
  END IF;

  v_city := pg_catalog.btrim(p_city);
  IF pg_catalog.char_length(v_city) > 120 THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'city_too_long');
  END IF;

  IF p_site_code IS NOT NULL THEN
    v_site_code := pg_catalog.btrim(p_site_code);
    IF pg_catalog.char_length(v_site_code) < 1
       OR pg_catalog.char_length(v_site_code) > 80
    THEN
      RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'site_code_invalid');
    END IF;
  ELSE
    v_site_code := NULL;
  END IF;

  IF p_address_line IS NOT NULL THEN
    v_address_line := pg_catalog.btrim(p_address_line);
    IF pg_catalog.char_length(v_address_line) < 1
       OR pg_catalog.char_length(v_address_line) > 500
    THEN
      RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'address_invalid');
    END IF;
  ELSE
    v_address_line := NULL;
  END IF;

  INSERT INTO public.enterprise_sites (
    enterprise_id,
    name,
    site_code,
    address_line,
    city,
    status
  )
  VALUES (
    p_enterprise_id,
    v_name,
    v_site_code,
    v_address_line,
    v_city,
    'active'
  )
  RETURNING id INTO v_site_id;

  PERFORM fixeo_private._write_enterprise_audit_event(
    p_enterprise_id,
    'site.created',
    'enterprise_site',
    v_site_id,
    NULL,
    pg_catalog.jsonb_build_object(
      'name', v_name,
      'city', v_city,
      'site_code', v_site_code,
      'address_line', v_address_line,
      'status', 'active'
    ),
    '{}'::jsonb
  );

  RETURN pg_catalog.jsonb_build_object(
    'ok', true,
    'site_id', v_site_id
  );

EXCEPTION
  WHEN unique_violation THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'site_code_exists'
    );

  WHEN OTHERS THEN
    RAISE WARNING '[create_enterprise_site] unexpected error: %', SQLERRM;
    RETURN pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'internal_error'
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_enterprise_sla_policy(p_enterprise_id uuid, p_site_id uuid, p_urgency text, p_acceptance_target_minutes integer, p_status text DEFAULT 'active'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_caller_id uuid := auth.uid();
  v_enterprise_status text;
  v_site_enterprise uuid;
  v_policy_id uuid;
  v_target_type text;
  v_target_id uuid;
BEGIN
  IF v_caller_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','unauthenticated');
  END IF;

  IF p_enterprise_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','enterprise_required');
  END IF;

  IF p_acceptance_target_minutes IS NULL OR p_acceptance_target_minutes <= 0 THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invalid_target');
  END IF;

  IF p_status IS NULL OR p_status NOT IN ('active','inactive') THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invalid_status');
  END IF;

  IF p_urgency IS NOT NULL
     AND p_urgency NOT IN ('urgent','high','normal','low')
  THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invalid_urgency');
  END IF;

  SELECT ea.status
  INTO v_enterprise_status
  FROM public.enterprise_accounts ea
  WHERE ea.id = p_enterprise_id
  FOR SHARE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','enterprise_not_found');
  END IF;

  IF v_enterprise_status <> 'active' THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',false,'reason','enterprise_not_active',
      'enterprise_status',v_enterprise_status
    );
  END IF;

  IF NOT fixeo_private._fixeo_is_enterprise_manager(p_enterprise_id) THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','forbidden');
  END IF;

  IF p_site_id IS NOT NULL THEN
    SELECT es.enterprise_id
    INTO v_site_enterprise
    FROM public.enterprise_sites es
    WHERE es.id = p_site_id
    FOR SHARE;

    IF NOT FOUND THEN
      RETURN pg_catalog.jsonb_build_object('ok',false,'reason','site_not_found');
    END IF;

    IF v_site_enterprise <> p_enterprise_id THEN
      RETURN pg_catalog.jsonb_build_object('ok',false,'reason','site_enterprise_mismatch');
    END IF;
  END IF;

  INSERT INTO public.enterprise_sla_policies(
    enterprise_id,
    site_id,
    urgency,
    acceptance_target_minutes,
    status,
    created_by
  )
  VALUES(
    p_enterprise_id,
    p_site_id,
    p_urgency,
    p_acceptance_target_minutes,
    p_status,
    v_caller_id
  )
  RETURNING id INTO v_policy_id;

  v_target_type := CASE WHEN p_site_id IS NULL THEN 'enterprise_account' ELSE 'enterprise_site' END;
  v_target_id := COALESCE(p_site_id,p_enterprise_id);

  PERFORM fixeo_private._write_enterprise_audit_event(
    p_enterprise_id,
    'sla.policy_created',
    v_target_type,
    v_target_id,
    NULL,
    pg_catalog.jsonb_build_object(
      'site_id',p_site_id,
      'urgency',p_urgency,
      'acceptance_target_minutes',p_acceptance_target_minutes,
      'status',p_status
    ),
    pg_catalog.jsonb_build_object('policy_id',v_policy_id)
  );

  RETURN pg_catalog.jsonb_build_object(
    'ok',true,
    'policy_id',v_policy_id,
    'enterprise_id',p_enterprise_id,
    'site_id',p_site_id,
    'urgency',p_urgency,
    'acceptance_target_minutes',p_acceptance_target_minutes,
    'status',p_status
  );

EXCEPTION
  WHEN unique_violation THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','policy_exists');
  WHEN OTHERS THEN
    RAISE WARNING '[create_enterprise_sla_policy] error: % (SQLSTATE: %)', SQLERRM, SQLSTATE;
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','internal_error');
END;
$function$

CREATE OR REPLACE FUNCTION public.create_enterprise_workforce_worker(p_enterprise_id uuid, p_member_id uuid, p_display_label text, p_employee_code text DEFAULT NULL::text, p_all_sites boolean DEFAULT false, p_max_concurrent_jobs integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_member_enterprise uuid;
  v_member_status text;
  v_label text;
  v_code text;
  v_worker_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','unauthenticated');
  END IF;

  IF NOT fixeo_private._fixeo_is_enterprise_manager(p_enterprise_id) THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','forbidden');
  END IF;

  v_label := pg_catalog.btrim(p_display_label);
  v_code := NULLIF(pg_catalog.btrim(p_employee_code), '');

  IF v_label IS NULL OR pg_catalog.char_length(v_label) NOT BETWEEN 1 AND 160 THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invalid_label');
  END IF;

  IF v_code IS NOT NULL AND pg_catalog.char_length(v_code) NOT BETWEEN 1 AND 80 THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invalid_employee_code');
  END IF;

  IF p_max_concurrent_jobs IS NULL OR p_max_concurrent_jobs NOT BETWEEN 1 AND 20 THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invalid_capacity');
  END IF;

  SELECT em.enterprise_id, em.status
  INTO v_member_enterprise, v_member_status
  FROM public.enterprise_members em
  WHERE em.id = p_member_id
  FOR SHARE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','member_not_found');
  END IF;

  IF v_member_enterprise <> p_enterprise_id THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','member_enterprise_mismatch');
  END IF;

  IF v_member_status <> 'active' THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','member_not_active');
  END IF;

  INSERT INTO public.enterprise_workforce_workers(
    enterprise_id,member_id,display_label,employee_code,all_sites,
    max_concurrent_jobs,created_by
  )
  VALUES(
    p_enterprise_id,p_member_id,v_label,v_code,COALESCE(p_all_sites,false),
    p_max_concurrent_jobs,auth.uid()
  )
  RETURNING id INTO v_worker_id;

  PERFORM fixeo_private._write_enterprise_audit_event(
    p_enterprise_id,
    'workforce.worker_created',
    'enterprise_workforce_worker',
    v_worker_id,
    NULL,
    pg_catalog.jsonb_build_object(
      'member_id',p_member_id,
      'status','active',
      'availability','available',
      'all_sites',COALESCE(p_all_sites,false),
      'max_concurrent_jobs',p_max_concurrent_jobs
    ),
    pg_catalog.jsonb_build_object('display_label',v_label,'employee_code',v_code)
  );

  RETURN pg_catalog.jsonb_build_object(
    'ok',true,'worker_id',v_worker_id,'enterprise_id',p_enterprise_id
  );

EXCEPTION
  WHEN unique_violation THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','worker_exists');
  WHEN OTHERS THEN
    RAISE WARNING '[create_enterprise_workforce_worker] % %', SQLSTATE, SQLERRM;
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','internal_error');
END;
$function$

CREATE OR REPLACE FUNCTION public.decide_enterprise_approval_case_v1(p_enterprise_id uuid, p_case_id uuid, p_decision text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_case public.enterprise_approval_cases%ROWTYPE; v_member_id uuid; v_role text; v_required_role text;
  v_created jsonb; v_request_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN RETURN jsonb_build_object('ok',false,'reason','unauthenticated'); END IF;
  IF p_decision NOT IN ('approved','rejected') THEN RETURN jsonb_build_object('ok',false,'reason','invalid_decision'); END IF;
  IF p_note IS NOT NULL AND char_length(btrim(p_note))>1000 THEN RETURN jsonb_build_object('ok',false,'reason','note_too_long'); END IF;

  SELECT * INTO v_case FROM public.enterprise_approval_cases c
  WHERE c.id=p_case_id AND c.enterprise_id=p_enterprise_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','case_not_found'); END IF;
  IF v_case.status<>'pending' THEN RETURN jsonb_build_object('ok',false,'reason','case_not_pending'); END IF;
  IF NOT fixeo_private._fixeo_can_access_enterprise_site(p_enterprise_id,v_case.site_id) THEN RETURN jsonb_build_object('ok',false,'reason','site_forbidden'); END IF;

  SELECT em.id,em.role INTO v_member_id,v_role
  FROM public.enterprise_members em
  WHERE em.enterprise_id=p_enterprise_id AND em.user_id=auth.uid() AND em.status='active';
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','forbidden'); END IF;

  SELECT s.approver_role INTO v_required_role
  FROM public.enterprise_approval_policy_steps s
  WHERE s.policy_id=v_case.policy_id AND s.step_order=v_case.current_step;
  IF v_required_role IS NULL THEN RETURN jsonb_build_object('ok',false,'reason','step_not_found'); END IF;
  IF v_role<>v_required_role THEN RETURN jsonb_build_object('ok',false,'reason','wrong_approver_role','required_role',v_required_role); END IF;
  IF v_role='site_manager' AND NOT fixeo_private._fixeo_can_access_enterprise_site(p_enterprise_id,v_case.site_id) THEN RETURN jsonb_build_object('ok',false,'reason','site_forbidden'); END IF;

  INSERT INTO public.enterprise_approval_decisions(
    enterprise_id,case_id,step_order,approver_member_id,approver_role,decision,note
  ) VALUES(p_enterprise_id,p_case_id,v_case.current_step,v_member_id,v_role,p_decision,NULLIF(btrim(p_note),''));

  IF p_decision='rejected' THEN
    UPDATE public.enterprise_approval_cases SET status='rejected',resolved_at=now() WHERE id=p_case_id;
    PERFORM fixeo_private._write_enterprise_audit_event(
      p_enterprise_id,'governance.case_rejected','enterprise_approval_case',p_case_id,NULL,
      jsonb_build_object('step_order',v_case.current_step,'approver_role',v_role),'{}'::jsonb
    );
    RETURN jsonb_build_object('ok',true,'status','rejected','approval_case_id',p_case_id);
  END IF;

  IF v_case.current_step<v_case.total_steps THEN
    UPDATE public.enterprise_approval_cases SET current_step=current_step+1 WHERE id=p_case_id;
    RETURN jsonb_build_object('ok',true,'status','pending','approval_case_id',p_case_id,'current_step',v_case.current_step+1,'total_steps',v_case.total_steps);
  END IF;

  v_created:=public.create_enterprise_request_hybrid(
    p_enterprise_id,v_case.site_id,v_case.service_category,v_case.description,v_case.urgency
  );
  IF v_created IS NULL OR COALESCE((v_created->>'ok')::boolean,false) IS NOT TRUE THEN
    RAISE EXCEPTION 'final_approval_request_create_failed';
  END IF;
  v_request_id:=(v_created->>'service_request_id')::uuid;
  UPDATE public.enterprise_approval_cases
  SET status='approved',service_request_id=v_request_id,resolved_at=now()
  WHERE id=p_case_id;

  PERFORM fixeo_private._write_enterprise_audit_event(
    p_enterprise_id,'governance.case_approved','enterprise_approval_case',p_case_id,NULL,
    jsonb_build_object('service_request_id',v_request_id,'approver_role',v_role,'requested_amount',v_case.requested_amount),
    jsonb_build_object('policy_id',v_case.policy_id)
  );

  RETURN v_created || jsonb_build_object('governance_status','approved','approval_case_id',p_case_id);
EXCEPTION WHEN unique_violation THEN
  RETURN jsonb_build_object('ok',false,'reason','step_already_decided');
WHEN OTHERS THEN
  RAISE WARNING '[decide_enterprise_approval_case_v1] % %',SQLSTATE,SQLERRM;
  RETURN jsonb_build_object('ok',false,'reason','internal_error');
END;
$function$

CREATE OR REPLACE FUNCTION public.decline_mission(p_mission_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_artisan_id      uuid;
  v_request_id      text;
  v_mission_status  text;
  v_mission_artisan uuid;
  v_sr_status       text;
  v_rows_updated    integer;
BEGIN

  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'unauthenticated');
  END IF;

  SELECT a.id
  INTO   v_artisan_id
  FROM   public.artisans a
  WHERE  a.owner_user_id = auth.uid()
  LIMIT  1;

  IF v_artisan_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'artisan_not_found');
  END IF;

  SELECT m.request_id, m.status, m.artisan_profile_id
  INTO   v_request_id, v_mission_status, v_mission_artisan
  FROM   public.missions m
  WHERE  m.id = p_mission_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'mission_not_found');
  END IF;

  IF v_mission_artisan != v_artisan_id THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_your_mission');
  END IF;

  IF v_mission_status != 'offered' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_offered');
  END IF;

  SELECT sr.status INTO v_sr_status
  FROM   public.service_requests sr
  WHERE  sr.id::text = v_request_id;

  IF NOT FOUND OR v_sr_status != 'new' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'request_not_dispatchable');
  END IF;

  UPDATE public.missions
  SET    status = 'declined'
  WHERE  id     = p_mission_id
    AND  status = 'offered';

  GET DIAGNOSTICS v_rows_updated = ROW_COUNT;

  IF v_rows_updated = 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_offered');
  END IF;

  RETURN jsonb_build_object(
    'ok',         true,
    'mission_id', p_mission_id
  );

EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING '[decline_mission] unexpected error: %', SQLERRM;
    RETURN jsonb_build_object('ok', false, 'reason', 'internal_error');
END;

$function$

CREATE OR REPLACE FUNCTION public.decline_my_enterprise_workforce_offer_v1(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_worker_id uuid;
  v_enterprise_id uuid;
  v_offer_id uuid;
  v_request_status text;
  v_mode text;
  v_policy_id uuid;
  v_remaining integer;
  v_external jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','unauthenticated');
  END IF;

  SELECT w.id,w.enterprise_id
  INTO v_worker_id,v_enterprise_id
  FROM public.enterprise_workforce_workers w
  JOIN public.enterprise_members em
    ON em.id=w.member_id
   AND em.enterprise_id=w.enterprise_id
  WHERE em.user_id=auth.uid()
    AND em.status='active'
    AND w.status='active'
  LIMIT 1;

  IF v_worker_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','worker_not_found');
  END IF;

  SELECT sr.status
  INTO v_request_status
  FROM public.service_requests sr
  WHERE sr.id=p_request_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','request_not_found');
  END IF;

  SELECT o.id
  INTO v_offer_id
  FROM public.enterprise_internal_dispatch_offers o
  WHERE o.service_request_id=p_request_id
    AND o.worker_id=v_worker_id
    AND o.status='offered'
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','offer_not_active');
  END IF;

  UPDATE public.enterprise_internal_dispatch_offers
  SET status='declined',responded_at=now()
  WHERE id=v_offer_id;

  SELECT count(*)::integer
  INTO v_remaining
  FROM public.enterprise_internal_dispatch_offers
  WHERE service_request_id=p_request_id
    AND status='offered'
    AND expires_at>now();

  SELECT s.mode,s.policy_id
  INTO v_mode,v_policy_id
  FROM public.enterprise_hybrid_dispatch_state s
  WHERE s.service_request_id=p_request_id
  FOR UPDATE;

  IF v_request_status='new' AND v_remaining=0 THEN
    IF v_mode='internal_first' THEN
      v_external := fixeo_private._fixeo_start_external_dispatch_v1(
        p_request_id,v_enterprise_id,v_policy_id,v_mode,'dispatch.external_fallback'
      );
    ELSIF v_mode='internal_only' THEN
      UPDATE public.enterprise_hybrid_dispatch_state
      SET status='no_internal_candidate',fallback_due_at=NULL,updated_at=now()
      WHERE service_request_id=p_request_id;
    END IF;
  END IF;

  PERFORM fixeo_private._write_enterprise_audit_event(
    v_enterprise_id,
    'dispatch.internal_declined',
    'service_request',
    p_request_id,
    NULL,
    pg_catalog.jsonb_build_object(
      'worker_id',v_worker_id,
      'remaining_offers',v_remaining,
      'mode',v_mode
    ),
    '{}'::jsonb
  );

  RETURN pg_catalog.jsonb_build_object(
    'ok',true,'reason','declined','remaining_offers',v_remaining
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.diagnostic_cleanup_v1(p_action text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m fixeo_private.diagnostic_media_v1%ROWTYPE; items jsonb := '[]';
  delete_clean boolean; complete_raw boolean;
BEGIN
  IF p_action='claim' THEN
    -- Interrupted requests do not hold a dossier indefinitely.
    UPDATE fixeo_private.diagnostic_runs_v1 SET state='failed',error_code='LEASE_EXPIRED',finished_at=now()
      WHERE state='running' AND lease_until<now();
    UPDATE fixeo_private.diagnostic_sessions_v1 s SET state='draft',updated_at=now()
      WHERE s.state='analyzing' AND NOT EXISTS(SELECT 1 FROM fixeo_private.diagnostic_runs_v1 r WHERE r.session_id=s.id AND r.state='running');
    -- First observed closure starts the 30-day media retention window.
    UPDATE fixeo_private.diagnostic_sessions_v1 s SET closed_seen_at=now()
      WHERE s.state='bound' AND s.closed_seen_at IS NULL AND EXISTS(
        SELECT 1 FROM public.service_requests sr WHERE sr.id=s.service_request_id
          AND sr.status IN ('completed','validated','cancelled'));
    UPDATE fixeo_private.diagnostic_media_v1 x SET expires_at=least(x.expires_at,s.closed_seen_at+interval '30 days')
      FROM fixeo_private.diagnostic_sessions_v1 s WHERE s.id=x.session_id AND s.closed_seen_at IS NOT NULL
        AND x.expires_at>s.closed_seen_at+interval '30 days';
    FOR m IN SELECT x.* FROM fixeo_private.diagnostic_media_v1 x
      WHERE x.state<>'deleted' AND x.purge_after<=now()
        AND (x.purge_lease_until IS NULL OR x.purge_lease_until<now())
        AND (x.expires_at<=now() OR x.state IN ('rejected','removed')
          OR (NOT x.raw_finalized AND (x.state='ready' OR x.upload_expires_at+interval '5 minutes'<now())))
      ORDER BY x.purge_after,x.id LIMIT 8 FOR UPDATE SKIP LOCKED LOOP
      delete_clean := m.expires_at<=now() OR m.state IN ('removed','rejected');
      UPDATE fixeo_private.diagnostic_media_v1 SET purge_lease=gen_random_uuid(),purge_lease_until=now()+interval '5 minutes',purge_clean=delete_clean
        WHERE id=m.id RETURNING * INTO m;
      items:=items || jsonb_build_array(jsonb_build_object('id',m.id,'lease',m.purge_lease,
        'paths',CASE WHEN delete_clean THEN jsonb_build_array(m.raw_path,m.clean_path) ELSE jsonb_build_array(m.raw_path) END));
    END LOOP;
    -- Expired dossiers are removed only after their object tombstones are final.
    DELETE FROM fixeo_private.diagnostic_sessions_v1 s WHERE s.expires_at<now()
      AND NOT EXISTS(SELECT 1 FROM fixeo_private.diagnostic_media_v1 x WHERE x.session_id=s.id AND x.state<>'deleted');
    DELETE FROM fixeo_private.diagnostic_usage_windows_v1 WHERE window_start<now()-interval '31 days';
    RETURN jsonb_build_object('items',items);
  ELSIF p_action='finish' THEN
    SELECT * INTO m FROM fixeo_private.diagnostic_media_v1 WHERE id=(p_payload->>'id')::uuid
      AND purge_lease=(p_payload->>'lease')::uuid FOR UPDATE;
    IF NOT FOUND OR m.purge_lease_until<now() THEN RAISE EXCEPTION 'DIAGNOSTIC_LEASE_EXPIRED'; END IF;
    IF p_payload->>'ok'='true' THEN
      complete_raw := m.upload_expires_at+interval '5 minutes'<now();
      -- Only acknowledge paths actually present in the claimed deletion batch.
      delete_clean := m.purge_clean;
      UPDATE fixeo_private.diagnostic_media_v1 SET raw_deleted_at=now(),raw_finalized=complete_raw,
        state=CASE WHEN delete_clean AND complete_raw THEN 'deleted' ELSE state END,
        purge_after=CASE WHEN NOT complete_raw THEN upload_expires_at+interval '5 minutes' ELSE expires_at END,
        purge_lease=NULL,purge_lease_until=NULL,last_purge_error=NULL WHERE id=m.id;
    ELSE
      UPDATE fixeo_private.diagnostic_media_v1 SET purge_attempts=purge_attempts+1,
        purge_after=now()+interval '5 minutes' * least(288,power(2,least(purge_attempts,8)))::integer,
        last_purge_error='STORAGE_DELETE_FAILED',purge_lease=NULL,purge_lease_until=NULL WHERE id=m.id;
    END IF;
    RETURN jsonb_build_object('ok',true);
  END IF;
  RAISE EXCEPTION 'DIAGNOSTIC_INVALID_ACTION';
END $function$

CREATE OR REPLACE FUNCTION public.diagnostic_mission_context_v1(p_user_id uuid, p_mission_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE s fixeo_private.diagnostic_sessions_v1%ROWTYPE; r fixeo_private.diagnostic_runs_v1%ROWTYPE; media jsonb; pricing jsonb;
BEGIN
  -- API supplies an Auth-verified subject. A phone, supplied role or mission UUID is insufficient.
  IF p_user_id IS NULL OR NOT EXISTS(
    SELECT 1 FROM public.missions m JOIN public.artisans a ON a.id=m.artisan_profile_id
    WHERE m.id=p_mission_id AND a.owner_user_id=p_user_id
      AND m.accepted_at IS NOT NULL AND m.status IN ('pending','done','validated')
  ) THEN RAISE EXCEPTION 'DIAGNOSTIC_NOT_FOUND'; END IF;
  SELECT d.* INTO s FROM fixeo_private.diagnostic_sessions_v1 d
    JOIN public.missions m ON m.request_id=d.service_request_id::text
    WHERE m.id=p_mission_id AND d.state='bound' AND d.expires_at>now();
  IF NOT FOUND THEN RETURN jsonb_build_object('result',NULL,'input',NULL,'media','[]'::jsonb); END IF;
  SELECT * INTO r FROM fixeo_private.diagnostic_runs_v1 WHERE id=s.selected_run_id AND session_id=s.id AND state='complete';
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',m.id,'clean_path',m.clean_path)),'[]') INTO media
    FROM fixeo_private.diagnostic_media_v1 m WHERE m.session_id=s.id AND m.state='ready' AND m.expires_at>now()
      AND EXISTS(SELECT 1 FROM jsonb_array_elements(r.input_snapshot->'media') used WHERE used->>'id'=m.id::text AND used->>'sha256'=m.sha256);
  SELECT jsonb_build_object('service_code',o.service_code,'amount_mad',o.client_total_minor::numeric/100,'currency',o.currency) INTO pricing
    FROM public.service_requests sr JOIN public.fixeo_pricing_offers_v1 o ON o.id=sr.pricing_offer_id WHERE sr.id=s.service_request_id;
  RETURN jsonb_build_object('pricing',pricing,'result',r.result,'input',r.input_snapshot->'input','media',media,'booking',to_jsonb(s)->'booking_context');
END $function$

CREATE OR REPLACE FUNCTION public.diagnostic_state_v1(p_action text, p_actor text, p_session_id uuid, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE s fixeo_private.diagnostic_sessions_v1%ROWTYPE;
  m fixeo_private.diagnostic_media_v1%ROWTYPE;
  r fixeo_private.diagnostic_runs_v1%ROWTYPE;
  media jsonb; mid uuid; rid uuid; snapshot jsonb;
BEGIN
  IF p_actor IS NULL OR p_actor !~ '^(u:[0-9a-f-]{36}|g:[0-9a-f]{64})$'
    OR p_payload IS NULL OR jsonb_typeof(p_payload)<>'object'
    OR octet_length(p_payload::text)>65536 THEN RAISE EXCEPTION 'DIAGNOSTIC_INVALID_INPUT'; END IF;
  IF p_action='create' THEN
    IF NOT EXISTS(SELECT 1 FROM fixeo_private.diagnostic_sessions_v1 WHERE id=p_session_id) THEN
      PERFORM fixeo_private.diagnostic_quota_v1(p_payload->'limits','{"sessions":1}');
      INSERT INTO fixeo_private.diagnostic_sessions_v1(id,owner_key,owner_user_id,guest_secret_hash,source,city_slug,input,consent_version)
        VALUES(p_session_id,p_actor,CASE WHEN left(p_actor,2)='u:' THEN substring(p_actor from 3)::uuid END,
          CASE WHEN left(p_actor,2)='g:' THEN substring(p_actor from 3) END,
          p_payload->>'source',p_payload->>'city_slug',p_payload->'input',p_payload->>'consent_version');
    END IF;
  END IF;
  s := fixeo_private.diagnostic_lock_v1(p_session_id,p_actor);
  IF p_action NOT IN ('create','get') THEN
    IF s.state='bound' THEN RAISE EXCEPTION 'DIAGNOSTIC_IMMUTABLE'; END IF;
    IF (p_payload->>'revision')::integer IS DISTINCT FROM s.revision
      THEN RAISE EXCEPTION 'DIAGNOSTIC_REVISION_CONFLICT'; END IF;
  END IF;
  IF p_action='update' THEN
    IF s.state='analyzing' THEN RAISE EXCEPTION 'DIAGNOSTIC_BUSY'; END IF;
    UPDATE fixeo_private.diagnostic_sessions_v1 SET input=p_payload->'input',city_slug=p_payload->>'city_slug',
      revision=revision+1,state='draft',selected_run_id=NULL,updated_at=now() WHERE id=s.id;
  ELSIF p_action='media_reserve' THEN
    IF s.state='analyzing' THEN RAISE EXCEPTION 'DIAGNOSTIC_BUSY'; END IF;
    IF p_payload->>'kind' IS DISTINCT FROM 'photo' THEN RAISE EXCEPTION 'DIAGNOSTIC_VIDEO_DISABLED'; END IF;
    IF (SELECT count(*) FROM fixeo_private.diagnostic_media_v1 WHERE session_id=s.id AND state IN ('reserved','validating','ready'))>=3
      THEN RAISE EXCEPTION 'DIAGNOSTIC_MEDIA_LIMIT'; END IF;
    IF p_payload->>'mime' NOT IN ('image/jpeg','image/png','image/webp') THEN RAISE EXCEPTION 'DIAGNOSTIC_MEDIA_TYPE'; END IF;
    -- Reserve the maximum raw + sanitized bytes, not the untrusted declaration.
    PERFORM fixeo_private.diagnostic_quota_v1(p_payload->'limits','{"bytes":16777216}');
    mid:=gen_random_uuid();
    INSERT INTO fixeo_private.diagnostic_media_v1(id,session_id,kind,raw_path,clean_path,declared_mime,declared_bytes)
      VALUES(mid,s.id,'photo','raw/'||s.id::text||'/'||mid::text,
        'safe/'||s.id::text||'/'||mid::text||'.webp',p_payload->>'mime',(p_payload->>'bytes')::integer) RETURNING * INTO m;
    UPDATE fixeo_private.diagnostic_sessions_v1 SET revision=revision+1,state='draft',selected_run_id=NULL,updated_at=now() WHERE id=s.id;
  ELSIF p_action IN ('media_claim','media_finish','media_reject','media_remove') THEN
    IF s.state='analyzing' THEN RAISE EXCEPTION 'DIAGNOSTIC_BUSY'; END IF;
    SELECT * INTO m FROM fixeo_private.diagnostic_media_v1 WHERE session_id=s.id AND id=(p_payload->>'media_id')::uuid FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'DIAGNOSTIC_NOT_FOUND'; END IF;
    IF p_action='media_claim' THEN
      IF m.state='ready' THEN NULL;
      ELSIF m.state='reserved' OR (m.state='validating' AND m.lease_until<now()) THEN
        PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('diagnostic-media-validation-v1',0));
        IF (SELECT count(*) FROM fixeo_private.diagnostic_media_v1 x WHERE x.state='validating' AND x.lease_until>now())>=4
          THEN RAISE EXCEPTION 'DIAGNOSTIC_CONCURRENCY_LIMIT'; END IF;
        UPDATE fixeo_private.diagnostic_media_v1 SET state='validating',validation_lease=gen_random_uuid(),lease_until=now()+interval '2 minutes'
          WHERE id=m.id RETURNING * INTO m;
      ELSE RAISE EXCEPTION 'DIAGNOSTIC_BUSY'; END IF;
    ELSIF p_action IN ('media_finish','media_reject') THEN
      IF m.state<>'validating' OR m.validation_lease IS DISTINCT FROM (p_payload->>'lease')::uuid OR m.lease_until<now()
        THEN RAISE EXCEPTION 'DIAGNOSTIC_LEASE_EXPIRED'; END IF;
      UPDATE fixeo_private.diagnostic_media_v1 SET state=CASE WHEN p_action='media_finish' THEN 'ready' ELSE 'rejected' END,
        actual_mime=p_payload->>'mime',actual_bytes=(p_payload->>'bytes')::integer,
        width=(p_payload->>'width')::integer,height=(p_payload->>'height')::integer,sha256=p_payload->>'sha256',
        validation_lease=NULL,lease_until=NULL WHERE id=m.id RETURNING * INTO m;
    ELSE
      IF m.state='validating' AND m.lease_until>now() THEN RAISE EXCEPTION 'DIAGNOSTIC_BUSY'; END IF;
      UPDATE fixeo_private.diagnostic_media_v1 SET state='removed',expires_at=now() WHERE id=m.id RETURNING * INTO m;
      UPDATE fixeo_private.diagnostic_sessions_v1 SET revision=revision+1,state='draft',selected_run_id=NULL,updated_at=now() WHERE id=s.id;
    END IF;
  ELSIF p_action='run_start' THEN
    rid:=(p_payload->>'run_id')::uuid;
    SELECT * INTO r FROM fixeo_private.diagnostic_runs_v1 WHERE id=rid AND session_id=s.id;
    IF FOUND THEN
      IF r.revision<>s.revision THEN RAISE EXCEPTION 'DIAGNOSTIC_REVISION_CONFLICT'; END IF;
      RETURN jsonb_build_object('session',to_jsonb(s),'run',to_jsonb(r),'replayed',true);
    END IF;
    UPDATE fixeo_private.diagnostic_runs_v1 SET state='failed',error_code='LEASE_EXPIRED',finished_at=now()
      WHERE session_id=s.id AND state='running' AND lease_until<now();
    IF EXISTS(SELECT 1 FROM fixeo_private.diagnostic_runs_v1 WHERE session_id=s.id AND state='running')
      THEN RAISE EXCEPTION 'DIAGNOSTIC_BUSY'; END IF;
    IF EXISTS(SELECT 1 FROM fixeo_private.diagnostic_media_v1 WHERE session_id=s.id AND state IN ('reserved','validating'))
      THEN RAISE EXCEPTION 'DIAGNOSTIC_MEDIA_PENDING'; END IF;
    PERFORM fixeo_private.diagnostic_quota_v1(p_payload->'limits',jsonb_build_object('analyses',1,'reserved_micro_usd',(p_payload->>'reserved_micro_usd')::bigint));
    -- The global quota row stays locked through commit, serializing this admission check.
    IF (SELECT count(*) FROM fixeo_private.diagnostic_runs_v1 WHERE state='running' AND lease_until>now())>=4
      THEN RAISE EXCEPTION 'DIAGNOSTIC_CONCURRENCY_LIMIT'; END IF;
    SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'sha256',sha256,'path',clean_path,'mime',actual_mime,'bytes',actual_bytes) ORDER BY id),'[]')
      INTO media FROM fixeo_private.diagnostic_media_v1 WHERE session_id=s.id AND state='ready';
    snapshot:=jsonb_build_object('input',s.input,'city_slug',s.city_slug,'media',media,'previous_safety_signals',s.safety_signals);
    INSERT INTO fixeo_private.diagnostic_runs_v1(id,session_id,revision,state,input_snapshot,provider,model,contract_version,reserved_micro_usd)
      VALUES(rid,s.id,s.revision,'running',snapshot,p_payload->>'provider',p_payload->>'model','fixeo-diagnostic-v1',(p_payload->>'reserved_micro_usd')::bigint) RETURNING * INTO r;
    UPDATE fixeo_private.diagnostic_sessions_v1 SET state='analyzing',selected_run_id=NULL,updated_at=now() WHERE id=s.id;
  ELSIF p_action IN ('run_finish','run_fail') THEN
    SELECT * INTO r FROM fixeo_private.diagnostic_runs_v1 WHERE id=(p_payload->>'run_id')::uuid AND session_id=s.id FOR UPDATE;
    IF NOT FOUND OR r.state<>'running' OR r.revision<>s.revision OR r.lease_until<now()
      THEN RAISE EXCEPTION 'DIAGNOSTIC_LEASE_EXPIRED'; END IF;
    UPDATE fixeo_private.diagnostic_runs_v1 SET state=CASE WHEN p_action='run_finish' THEN 'complete' ELSE 'failed' END,
      result=CASE WHEN p_action='run_finish' THEN p_payload->'result' END,usage=coalesce(p_payload->'usage','{}'),
      error_code=p_payload->>'error_code',latency_ms=(p_payload->>'latency_ms')::integer,finished_at=now()
      WHERE id=r.id RETURNING * INTO r;
    UPDATE fixeo_private.diagnostic_sessions_v1 SET state=CASE WHEN p_action='run_fail' THEN 'draft'
        WHEN jsonb_array_length(coalesce(r.result->'questions','[]'))>0 THEN 'questions' ELSE 'ready' END,
      selected_run_id=CASE WHEN p_action='run_finish' THEN r.id END,
      safety_signals=CASE WHEN p_action='run_finish' THEN
        (SELECT coalesce(jsonb_agg(DISTINCT x),'[]') FROM jsonb_array_elements(s.safety_signals || coalesce(r.result->'safety'->'signals','[]')) x)
        ELSE s.safety_signals END,updated_at=now() WHERE id=s.id;
  ELSIF p_action NOT IN ('create','get') THEN RAISE EXCEPTION 'DIAGNOSTIC_INVALID_ACTION'; END IF;

  SELECT * INTO s FROM fixeo_private.diagnostic_sessions_v1 WHERE id=s.id;
  IF s.selected_run_id IS NOT NULL THEN SELECT * INTO r FROM fixeo_private.diagnostic_runs_v1 WHERE id=s.selected_run_id;
  ELSIF s.state='analyzing' THEN SELECT * INTO r FROM fixeo_private.diagnostic_runs_v1 WHERE session_id=s.id AND state='running' ORDER BY created_at DESC LIMIT 1; END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.created_at),'[]') INTO media
    FROM fixeo_private.diagnostic_media_v1 x WHERE session_id=s.id AND state NOT IN ('removed','deleted');
  RETURN jsonb_build_object('session',to_jsonb(s),'media',media,'item',CASE WHEN m.id IS NOT NULL THEN to_jsonb(m) END,
    'run',CASE WHEN r.id IS NOT NULL THEN to_jsonb(r) END,'replayed',false);
END $function$

CREATE OR REPLACE FUNCTION public.dispatch_accept_winner_v1(p_request_id uuid, p_artisan_id uuid)
 RETURNS TABLE(request_id uuid, winner_artisan_id uuid, winner_status text, cancelled_others integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_current_status text;
  v_existing_winner uuid;
  v_cancelled_count integer := 0;
BEGIN

  IF p_request_id IS NULL THEN
    RAISE EXCEPTION 'request_id is required';
  END IF;

  IF p_artisan_id IS NULL THEN
    RAISE EXCEPTION 'artisan_id is required';
  END IF;

  /*
   * Lock all queue rows for this request so two artisans
   * cannot be accepted concurrently.
   */
  PERFORM 1
  FROM public.dispatch_execution_queue q
  WHERE q.request_id = p_request_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'no dispatch queue entries found for request %', p_request_id;
  END IF;

  SELECT q.artisan_id
  INTO v_existing_winner
  FROM public.dispatch_execution_queue q
  WHERE q.request_id = p_request_id
    AND q.execution_status = 'ACCEPTED'
  LIMIT 1;

  IF v_existing_winner IS NOT NULL THEN
    IF v_existing_winner = p_artisan_id THEN
      RETURN QUERY
      SELECT
        p_request_id,
        p_artisan_id,
        'ACCEPTED'::text,
        0;

      RETURN;
    END IF;

    RAISE EXCEPTION
      'request % already has accepted artisan %',
      p_request_id,
      v_existing_winner;
  END IF;

  SELECT q.execution_status
  INTO v_current_status
  FROM public.dispatch_execution_queue q
  WHERE q.request_id = p_request_id
    AND q.artisan_id = p_artisan_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION
      'artisan % is not queued for request %',
      p_artisan_id,
      p_request_id;
  END IF;

  IF v_current_status <> 'CONTACTED' THEN
    RAISE EXCEPTION
      'artisan must be CONTACTED before acceptance; current status: %',
      v_current_status;
  END IF;

  UPDATE public.dispatch_execution_queue q
  SET
    execution_status = 'ACCEPTED',
    updated_at = now()
  WHERE q.request_id = p_request_id
    AND q.artisan_id = p_artisan_id;

  UPDATE public.dispatch_execution_queue q
  SET
    execution_status = 'CANCELLED',
    updated_at = now()
  WHERE q.request_id = p_request_id
    AND q.artisan_id <> p_artisan_id
    AND q.execution_status IN ('QUEUED', 'CONTACTED');

  GET DIAGNOSTICS v_cancelled_count = ROW_COUNT;

  RETURN QUERY
  SELECT
    p_request_id,
    p_artisan_id,
    'ACCEPTED'::text,
    v_cancelled_count;

END;
$function$

CREATE OR REPLACE FUNCTION public.dispatch_request_v1(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  -- Request state
  v_request_id_text   text;
  v_sr_status         text;
  v_sr_category       text;
  v_sr_city           text;
  v_sr_urgency        text;
  v_sr_target_artisan_id uuid;

  -- Existing offer/winner check
  v_existing_mission  uuid;

  -- Candidate loop variables
  v_artisan_id        uuid;
  v_artisan_city      text;
  v_artisan_cat       text;
  v_artisan_zone      text;
  v_artisan_rc        integer;
  v_artisan_rat       numeric;
  v_artisan_updated   timestamptz;

  -- Scoring
  v_svc_score         integer;
  v_city_score        integer;
  v_trust_score       integer;
  v_act_score         integer;
  v_score             integer;
  v_best_score        integer := -1;
  v_best_artisan_id   uuid;

  -- Normalized strings for comparison
  -- Normalization: translate(lower(COALESCE(value,'')), 'éèêëàâäôöùûüïîç', 'eeeeaaaoouuuiic')
  -- lower() runs first — no uppercase remains for translate().
  -- 15-char verified one-to-one mapping (7C.11F.1C).
  -- translate() and lower() are pg_catalog — safe with SET search_path=''.
  v_req_cat_norm      text;
  v_req_city_norm     text;
  v_art_cat_norm      text;
  v_art_city_norm     text;
  v_art_zone_norm     text;

  -- City proximity groups (lowercase, comma-delimited per group)
  -- Mirrors CITY_GROUPS from fixeo-dispatch-engine.js
  v_city_groups       text[] := ARRAY[
    'casablanca,mohammedia,mohammeddia,benslimane,el jadida',
    'rabat,sale,temara,kenitra,khemisset',
    'marrakech,safi,el kelaa des sraghna',
    'fes,fez,meknes,ifrane,taza',
    'agadir,tiznit,inezgane',
    'tanger,tanger-assilah,tetouan,chefchaouen',
    'oujda,berkane,nador',
    'laayoune,dakhla'
  ];
  v_group             text;
  v_req_in_group      boolean;
  v_art_in_group      boolean;
  v_days_since        integer;

  -- Mission creation
  v_new_mission_id    uuid;

BEGIN

  -- ── TYPE CONTRACT: cast request UUID to text once ─────────
  v_request_id_text := p_request_id::text;

  -- ── STEP 1: Lock the service_request row ──────────────────
  -- FOR UPDATE acquires a row-level exclusive lock.
  -- v_sr_status is read UNDER the lock — this is the authoritative
  -- post-lock state. Any concurrent transaction that modified the row
  -- before us will have committed; we see the final state.
  SELECT
  sr.status,
  sr.service_category,
  sr.city,
  sr.urgency,
  sr.target_artisan_id
INTO
  v_sr_status,
  v_sr_category,
  v_sr_city,
  v_sr_urgency,
  v_sr_target_artisan_id
FROM public.service_requests sr
WHERE sr.id = p_request_id
FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'request_not_found');
  END IF;

  -- ── STEP 2: Request must be 'new' (evaluated AFTER lock) ──
  IF v_sr_status != 'new' THEN
    RETURN jsonb_build_object(
      'ok',     false,
      'reason', 'request_not_dispatchable',
      'status', v_sr_status
    );
  END IF;

  -- ── STEP 3: Pending winner guard ──────────────────────────
  -- If someone already claimed this request, do not re-dispatch.
  SELECT m.id INTO v_existing_mission
  FROM   public.missions m
  WHERE  m.request_id = v_request_id_text
    AND  m.status     = 'pending'
  LIMIT  1;

  IF v_existing_mission IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok',         false,
      'reason',     'already_claimed',
      'mission_id', v_existing_mission
    );
  END IF;

  -- ── STEP 4: Active offer idempotency ──────────────────────
  -- If an offered mission already exists, return it without creating another.
  SELECT m.id INTO v_existing_mission
  FROM   public.missions m
  WHERE  m.request_id = v_request_id_text
    AND  m.status     = 'offered'
  LIMIT  1;

  IF v_existing_mission IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok',         true,
      'reason',     'existing_offer',
      'mission_id', v_existing_mission
    );
  END IF;

  -- ── STEP 5: Normalize request category and city ───────────
  -- Canonical normalization: translate(lower(COALESCE(value,'')), src15, dst15)
  -- lower() first → uppercase eliminated before translate() runs.
  -- 15-char verified one-to-one French accent map.
  v_req_cat_norm  := translate(lower(COALESCE(v_sr_category, '')),
                               'éèêëàâäôöùûüïîç',
                               'eeeeaaaoouuuiic');
  v_req_city_norm := translate(lower(COALESCE(v_sr_city, '')),
                               'éèêëàâäôöùûüïîç',
                               'eeeeaaaoouuuiic');

  -- ── STEP 6: Candidate selection and scoring ───────────────
  -- Eligibility gates enforced in WHERE clause.
  -- Prior-offer exclusion via NOT EXISTS subquery.
  -- Score computed per candidate; highest wins.
  -- Tie-breaker: artisan.id ASC (deterministic — no invented metric).
  --
  -- ELIMINATION GATES (11F.1A + 11F.1C):
  --   Blank artisan service against categorized request → CONTINUE
  --   Explicit service mismatch → CONTINUE
  --   Blank artisan city without zone/national coverage → CONTINUE
  --   Empty-string substring trap: guards placed BEFORE position() calls.

  FOR v_artisan_id, v_artisan_city, v_artisan_cat, v_artisan_zone,
      v_artisan_rc, v_artisan_rat, v_artisan_updated IN

    SELECT
      a.id,
      a.city,
      a.service_category,
      COALESCE(a.work_zone, ''),
      COALESCE(a.review_count, 0),
      COALESCE(a.rating, 0.0),
      a.updated_at
    FROM   public.artisans a
    WHERE a.availability = 'available'
    -- Approved small masonry packages require a declared masonry speciality.
    AND (
      NOT EXISTS (
        SELECT 1 FROM public.service_requests msr
        WHERE msr.id=p_request_id AND msr.pricing_offer_id IS NOT NULL
          AND msr.service_category='maconnerie'
      )
      OR translate(lower(COALESCE(a.service_category,'')),
        'éèêëàâäôöùûüïîç','eeeeaaaoouuuiic') LIKE '%maconn%'
    )

    AND (
    v_sr_target_artisan_id IS NULL
    OR a.id = v_sr_target_artisan_id
  )
      AND  NOT EXISTS (                           -- no prior mission for this request
        SELECT 1
        FROM   public.missions m
        WHERE  m.request_id         = v_request_id_text
          AND  m.artisan_profile_id = a.id
      )
    ORDER BY a.id ASC   -- stable base order; fine-grained by score below

  LOOP

    -- ── NORMALIZE ARTISAN STRINGS ────────────────────────────
    v_art_cat_norm  := translate(lower(COALESCE(v_artisan_cat, '')),
                                 'éèêëàâäôöùûüïîç',
                                 'eeeeaaaoouuuiic');
    v_art_city_norm := translate(lower(COALESCE(v_artisan_city, '')),
                                 'éèêëàâäôöùûüïîç',
                                 'eeeeaaaoouuuiic');
    v_art_zone_norm := translate(lower(COALESCE(v_artisan_zone, '')),
                                 'éèêëàâäôöùûüïîç',
                                 'eeeeaaaoouuuiic');

    -- ── SERVICE MATCH (weight 35) ────────────────────────────
    -- Empty-string safety: position('' IN 'anything') = 1 in PostgreSQL.
    -- Guard artisan blank before substring check.
    --
    -- Policy:
    --   req blank   → neutral 18 (request has no category — all eligible)
    --   art blank   → CONTINUE (artisan has no category for a categorized request)
    --   exact       → 35
    --   substring   → 25 (both sides proven non-empty by this point)
    --   mismatch    → CONTINUE (elimination)

    IF v_req_cat_norm = '' THEN
  v_svc_score := 18;

ELSIF v_art_cat_norm = '' THEN
  CONTINUE;

ELSIF v_art_cat_norm = v_req_cat_norm THEN
  v_svc_score := 35;

ELSIF position(v_req_cat_norm IN v_art_cat_norm) > 0
   OR position(v_art_cat_norm IN v_req_cat_norm) > 0 THEN
  v_svc_score := 25;

-- ── FAMILY MATCHES ─────────────────────────────────────────────
-- Allows real artisan specialities to match their canonical family.

ELSIF v_req_cat_norm = 'plomberie'
  AND (
    v_art_cat_norm LIKE '%plomberie%'
    OR v_art_cat_norm LIKE '%chauffage%'
    OR v_art_cat_norm LIKE '%sanitaire%'
  ) THEN
  v_svc_score := 24;

ELSIF v_req_cat_norm = 'electricite'
  AND (
    v_art_cat_norm LIKE '%electric%'
    OR v_art_cat_norm LIKE '%technique%'
  ) THEN
  v_svc_score := 24;

ELSIF v_req_cat_norm = 'serrurerie'
  AND (
    v_art_cat_norm LIKE '%serrur%'
    OR v_art_cat_norm LIKE '%ferronner%'
    OR v_art_cat_norm LIKE '%fer forge%'
  ) THEN
  v_svc_score := 24;

ELSIF v_req_cat_norm = 'climatisation'
  AND (
    v_art_cat_norm LIKE '%clim%'
    OR v_art_cat_norm LIKE '%froid%'
  ) THEN
  v_svc_score := 24;

ELSIF v_req_cat_norm = 'menuiserie'
  AND (
    v_art_cat_norm LIKE '%menuiser%'
    OR v_art_cat_norm LIKE '%bois%'
    OR v_art_cat_norm LIKE '%mdf%'
    OR v_art_cat_norm LIKE '%mobilier%'
    OR v_art_cat_norm LIKE '%inox%'
    OR v_art_cat_norm LIKE '%aluminium%'
    OR v_art_cat_norm LIKE '%agencement%'
    OR v_art_cat_norm LIKE '%amenagement%'
  ) THEN
  v_svc_score := 24;

ELSIF v_req_cat_norm = 'peinture'
  AND (
    v_art_cat_norm LIKE '%peint%'
    OR v_art_cat_norm LIKE '%decoration%'
    OR v_art_cat_norm LIKE '%tadelakt%'
    OR v_art_cat_norm LIKE '%vernis%'
    OR v_art_cat_norm LIKE '%finition%'
    OR v_art_cat_norm LIKE '%facade%'
  ) THEN
  v_svc_score := 24;

ELSIF v_req_cat_norm = 'maconnerie'
  AND (
    v_art_cat_norm LIKE '%maconner%'
    OR v_art_cat_norm LIKE '%construction%'
    OR v_art_cat_norm LIKE '%carrelage%'
    OR v_art_cat_norm LIKE '%marbre%'
    OR v_art_cat_norm LIKE '%platre%'
    OR v_art_cat_norm LIKE '%placo%'
    OR v_art_cat_norm LIKE '%zellige%'
    OR v_art_cat_norm LIKE '%etancheite%'
    OR v_art_cat_norm LIKE '%renovation%'
    OR v_art_cat_norm LIKE '%facade%'
  ) THEN
  v_svc_score := 24;

ELSIF v_req_cat_norm = 'nettoyage'
  AND v_art_cat_norm LIKE '%nettoy%' THEN
  v_svc_score := 24;

ELSIF v_req_cat_norm = 'jardinage'
  AND v_art_cat_norm LIKE '%jardin%' THEN
  v_svc_score := 24;

ELSIF v_req_cat_norm = 'demenagement'
  AND (
    v_art_cat_norm LIKE '%demenag%'
    OR v_art_cat_norm LIKE '%transport%'
  ) THEN
  v_svc_score := 24;

ELSIF v_req_cat_norm = 'autre'
  AND (
    v_art_cat_norm LIKE '%bricolage%'
    OR v_art_cat_norm LIKE '%maintenance%'
    OR v_art_cat_norm LIKE '%multi service%'
    OR v_art_cat_norm LIKE '%multiservice%'
    OR v_art_cat_norm LIKE '%piscine%'
    OR v_art_cat_norm LIKE '%amenagement%'
    OR v_art_cat_norm LIKE '%renovation%'
  ) THEN
  v_svc_score := 20;

ELSE
  CONTINUE;
END IF;

    -- ── CITY MATCH (weight 30) ──────────────────────────────
    -- Empty-string safety: artisan city blank must never produce a false
    -- substring hit. Non-empty guard applied before position() calls.
    -- work_zone and national fallbacks remain valid even when city is blank.
    --
    -- Policy:
    --   req blank       → neutral 15 (any artisan may serve uncitied request)
    --   art exact       → 30 (non-empty guard in place)
    --   art substring   → 28 (non-empty guard in place)
    --   work_zone match → 24 (zone may legitimately cover request city)
    --   proximity group → 18
    --   national        → 6
    --   none            → CONTINUE (when request city is known)

    IF v_req_city_norm = '' THEN
      v_city_score := 15;                         -- request has no city — neutral

    ELSIF v_art_city_norm <> ''
      AND v_art_city_norm = v_req_city_norm THEN
      v_city_score := 30;                         -- exact city match

    ELSIF v_art_city_norm <> ''
      AND (position(v_req_city_norm IN v_art_city_norm) > 0
        OR position(v_art_city_norm IN v_req_city_norm) > 0) THEN
      v_city_score := 28;                         -- substring (Tanger / Tanger-Assilah)

    ELSIF v_art_zone_norm <> ''
      AND position(v_req_city_norm IN v_art_zone_norm) > 0 THEN
      v_city_score := 24;                         -- work_zone declares coverage

    ELSE
      -- Proximity group check — same Moroccan geographic cluster
      v_city_score   := 0;
      v_req_in_group := false;
      v_art_in_group := false;

      -- Proximity group: artisan city must also be non-empty.
      -- position('' IN group) = 1 in PostgreSQL — empty artisan city would
      -- always match any group, producing a false proximity claim.
      IF v_art_city_norm <> '' THEN
        FOREACH v_group IN ARRAY v_city_groups LOOP
          v_req_in_group := position(v_req_city_norm IN v_group) > 0;
          v_art_in_group := position(v_art_city_norm IN v_group) > 0;
          IF v_req_in_group AND v_art_in_group THEN
            v_city_score := 18;
            EXIT;
          END IF;
        END LOOP;
      END IF;

      -- National/all-Morocco coverage declared in work_zone
      IF v_city_score = 0 AND v_art_zone_norm <> '' AND (
           position('national' IN v_art_zone_norm) > 0 OR
           position('maroc'    IN v_art_zone_norm) > 0 OR
           position('tout'     IN v_art_zone_norm) > 0
         ) THEN
        v_city_score := 6;
      END IF;

      -- ELIMINATION: request city known, artisan has no geographic relation.
      IF v_city_score = 0 THEN
        CONTINUE;
      END IF;

    END IF;

    -- ── TRUST SCORE (weight 20) ─────────────────────────────
    -- review_count and rating are proven live schema columns.
    -- completed_missions is NOT in public.artisans — not used.
    v_trust_score := 0;

    -- Review volume tiers
    IF    v_artisan_rc >= 100 THEN v_trust_score := v_trust_score + 12;
    ELSIF v_artisan_rc >= 50  THEN v_trust_score := v_trust_score + 9;
    ELSIF v_artisan_rc >= 20  THEN v_trust_score := v_trust_score + 6;
    ELSIF v_artisan_rc >= 5   THEN v_trust_score := v_trust_score + 3;
    ELSIF v_artisan_rc  = 0   THEN v_trust_score := v_trust_score - 2;
    END IF;

    -- Rating quality tiers
    IF    v_artisan_rat >= 4.8 THEN v_trust_score := v_trust_score + 8;
    ELSIF v_artisan_rat >= 4.5 THEN v_trust_score := v_trust_score + 6;
    ELSIF v_artisan_rat >= 4.0 THEN v_trust_score := v_trust_score + 4;
    ELSIF v_artisan_rat >  0.0 AND v_artisan_rat < 3.5 THEN
          v_trust_score := v_trust_score - 3;
    END IF;

    -- Clamp to weight [0, 20]
    IF v_trust_score > 20 THEN v_trust_score := 20; END IF;
    IF v_trust_score < 0  THEN v_trust_score := 0;  END IF;

    -- ── ACTIVITY SCORE (weight 15) ──────────────────────────
    -- updated_at recency (live schema column).
    IF v_artisan_updated IS NULL THEN
      v_days_since := 999;
    ELSE
      v_days_since := EXTRACT(EPOCH FROM (now() - v_artisan_updated))::integer / 86400;
    END IF;

    IF    v_days_since <= 1  THEN v_act_score := 15;
    ELSIF v_days_since <= 7  THEN v_act_score := 12;
    ELSIF v_days_since <= 30 THEN v_act_score := 8;
    ELSIF v_days_since <= 90 THEN v_act_score := 4;
    ELSE                          v_act_score := 0;
    END IF;

    -- ── COMPOSITE SCORE ─────────────────────────────────────
    v_score := v_svc_score + v_city_score + v_trust_score + v_act_score;

    -- Best score wins; tie is broken by artisan.id ASC (loop order)
    IF v_score > v_best_score THEN
      v_best_score      := v_score;
      v_best_artisan_id := v_artisan_id;
    END IF;

  END LOOP;

  -- ── STEP 7: No candidate found ────────────────────────────
  IF v_best_artisan_id IS NULL THEN
    -- Return stable result. Do NOT set service_requests.status='no_match' in V1.
    -- The request remains 'new' for ops/manual handling.
    RETURN jsonb_build_object('ok', false, 'reason', 'no_candidate');
  END IF;

  -- ── STEP 8: Create exactly ONE offered mission ────────────
  --
  -- TYPE CONTRACT:
  --   request_id         = v_request_id_text  (TEXT = p_request_id::text)
  --   artisan_profile_id = v_best_artisan_id  (UUID from artisans.id)
  --
  -- agreed_price: NULL — no price invented at dispatch time.
  -- client_profile_id: not populated (no auth context in service_role dispatch).
  -- accepted_at: NULL — set by claim_mission() at acceptance.
  --
  -- The unique partial index missions_one_offer_per_request (WHERE status='offered')
  -- is defense-in-depth against a concurrent winner in a concurrent transaction.

  BEGIN
    INSERT INTO public.missions (
      request_id,
      artisan_profile_id,
      status,
      agreed_price
    )
    VALUES (
      v_request_id_text,    -- TEXT: missions.request_id type contract
      v_best_artisan_id,    -- UUID: artisans.id
      'offered',
      NULL                  -- agreed_price: NULL — no price invented
    )
    RETURNING id INTO v_new_mission_id;

  EXCEPTION
    WHEN unique_violation THEN
      -- 23505: a concurrent dispatch_request_v1 won the race.
      -- Verify: read the actually-persisted offered mission row.
      -- We do NOT return ok:true based solely on SQLSTATE 23505 —
      -- the row must exist and be in status='offered'.
      SELECT m.id INTO v_new_mission_id
      FROM   public.missions m
      WHERE  m.request_id = v_request_id_text
        AND  m.status     = 'offered'
      LIMIT  1;

      IF v_new_mission_id IS NOT NULL THEN
        -- Verified: concurrent dispatch created the offer — return it.
        RETURN jsonb_build_object(
          'ok',         true,
          'reason',     'existing_offer',
          'mission_id', v_new_mission_id
        );
      ELSE
        -- 23505 but no offered row visible — either:
        --   (a) the unique violation was on a different constraint, OR
        --   (b) the offered row was immediately claimed by another transaction.
        -- Both cases: return a stable conflict result, not ok:true.
        RETURN jsonb_build_object('ok', false, 'reason', 'conflict');
      END IF;

    WHEN OTHERS THEN
      RAISE WARNING '[dispatch_request_v1] insert error: %', SQLERRM;
      RETURN jsonb_build_object('ok', false, 'reason', 'internal_error');
  END;

  -- ── Success: mission created, service_request.status remains 'new' ──
  -- The service_request row is NOT updated here.
  -- Only claim_mission() may transition service_requests.status to 'assigned'.
  RETURN jsonb_build_object(
    'ok',         true,
    'reason',     'dispatched',
    'mission_id', v_new_mission_id,
    'artisan_id', v_best_artisan_id,
    'score',      v_best_score
  );

EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING '[dispatch_request_v1] unexpected error: %', SQLERRM;
    RETURN jsonb_build_object('ok', false, 'reason', 'internal_error');
END;
$function$

CREATE OR REPLACE FUNCTION public.dispatch_request_v1_backup_20260821(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE

  -- Request state
  v_request_id_text   text;
  v_sr_status         text;
  v_sr_category       text;
  v_sr_city           text;
  v_sr_urgency        text;

  -- Existing offer/winner
  v_existing_mission  uuid;

  -- Candidate
  v_artisan_id        uuid;
  v_artisan_city      text;
  v_artisan_cat       text;
  v_artisan_zone      text;
  v_artisan_rc        integer;
  v_artisan_rat       numeric;
  v_artisan_updated   timestamptz;

  -- Scores
  v_svc_score         integer;
  v_city_score        integer;
  v_trust_score       integer;
  v_act_score         integer;
  v_score             integer;
  v_best_score        integer := -1;
  v_best_artisan_id   uuid;

  -- Normalized values
  v_req_cat_norm      text;
  v_req_city_norm     text;
  v_art_cat_norm      text;
  v_art_city_norm     text;
  v_art_zone_norm     text;

  -- Geographic proximity groups
  v_city_groups text[] := ARRAY[
    'casablanca,mohammedia,mohammeddia,benslimane,el jadida',
    'rabat,sale,temara,kenitra,khemisset',
    'marrakech,safi,el kelaa des sraghna',
    'fes,fez,meknes,ifrane,taza',
    'agadir,tiznit,inezgane',
    'tanger,tanger-assilah,tetouan,chefchaouen',
    'oujda,berkane,nador',
    'laayoune,dakhla'
  ];

  v_group             text;
  v_req_in_group      boolean;
  v_art_in_group      boolean;
  v_days_since        integer;

  -- Mission creation
  v_new_mission_id    uuid;

BEGIN

  -- ──────────────────────────────────────────────────────────
  -- STEP 1 — canonical request id
  -- ──────────────────────────────────────────────────────────

  v_request_id_text := p_request_id::text;


  -- ──────────────────────────────────────────────────────────
  -- STEP 2 — lock canonical request
  -- ──────────────────────────────────────────────────────────

  SELECT
    sr.status,
    sr.service_category,
    sr.city,
    sr.urgency
  INTO
    v_sr_status,
    v_sr_category,
    v_sr_city,
    v_sr_urgency
  FROM public.service_requests sr
  WHERE sr.id = p_request_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'request_not_found'
    );
  END IF;


  -- Request state is authoritative UNDER lock
  IF v_sr_status != 'new' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'request_not_dispatchable',
      'status', v_sr_status
    );
  END IF;


  -- ──────────────────────────────────────────────────────────
  -- STEP 3 — pending winner guard
  -- ──────────────────────────────────────────────────────────

  SELECT m.id
  INTO v_existing_mission
  FROM public.missions m
  WHERE m.request_id = v_request_id_text
    AND m.status = 'pending'
  LIMIT 1;

  IF v_existing_mission IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'already_claimed',
      'mission_id', v_existing_mission
    );
  END IF;


  -- ──────────────────────────────────────────────────────────
  -- STEP 4 — active offer idempotency
  -- ──────────────────────────────────────────────────────────

  SELECT m.id
  INTO v_existing_mission
  FROM public.missions m
  WHERE m.request_id = v_request_id_text
    AND m.status = 'offered'
  LIMIT 1;

  IF v_existing_mission IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'reason', 'existing_offer',
      'mission_id', v_existing_mission
    );
  END IF;


  -- ──────────────────────────────────────────────────────────
  -- STEP 5 — normalize request
  -- ──────────────────────────────────────────────────────────

  v_req_cat_norm :=
    translate(
      lower(COALESCE(v_sr_category, '')),
      'éèêëàâäôöùûüïîç',
      'eeeeaaaoouuuiic'
    );

  v_req_city_norm :=
    translate(
      lower(COALESCE(v_sr_city, '')),
      'éèêëàâäôöùûüïîç',
      'eeeeaaaoouuuiic'
    );


  -- ──────────────────────────────────────────────────────────
  -- STEP 6 — candidate selection + scoring
  -- ──────────────────────────────────────────────────────────

  FOR
    v_artisan_id,
    v_artisan_city,
    v_artisan_cat,
    v_artisan_zone,
    v_artisan_rc,
    v_artisan_rat,
    v_artisan_updated
  IN

    SELECT
      a.id,
      a.city,
      a.service_category,
      COALESCE(a.work_zone, ''),
      COALESCE(a.review_count, 0),
      COALESCE(a.rating, 0.0),
      a.updated_at
    FROM public.artisans a
    WHERE a.owner_user_id IS NOT NULL
      AND a.claimed = true
      AND a.claim_status = 'approved'
      AND a.onboarding_completed = true
      AND a.availability = 'available'

      AND NOT EXISTS (
        SELECT 1
        FROM public.missions m
        WHERE m.request_id = v_request_id_text
          AND m.artisan_profile_id = a.id
      )

    ORDER BY a.id ASC

  LOOP

    -- ── Normalize artisan values ─────────────────────────────

    v_art_cat_norm :=
      translate(
        lower(COALESCE(v_artisan_cat, '')),
        'éèêëàâäôöùûüïîç',
        'eeeeaaaoouuuiic'
      );

    v_art_city_norm :=
      translate(
        lower(COALESCE(v_artisan_city, '')),
        'éèêëàâäôöùûüïîç',
        'eeeeaaaoouuuiic'
      );

    v_art_zone_norm :=
      translate(
        lower(COALESCE(v_artisan_zone, '')),
        'éèêëàâäôöùûüïîç',
        'eeeeaaaoouuuiic'
      );


    -- ════════════════════════════════════════════════════════
    -- SERVICE MATCH — weight 35
    -- ════════════════════════════════════════════════════════

    IF v_req_cat_norm = '' THEN

      v_svc_score := 18;

    ELSIF v_art_cat_norm = '' THEN

      CONTINUE;

    ELSIF v_art_cat_norm = v_req_cat_norm THEN

      v_svc_score := 35;

    ELSIF
      position(v_req_cat_norm IN v_art_cat_norm) > 0
      OR
      position(v_art_cat_norm IN v_req_cat_norm) > 0
    THEN

      v_svc_score := 25;

    ELSE

      CONTINUE;

    END IF;


    -- ════════════════════════════════════════════════════════
    -- CITY MATCH — weight 30
    -- ════════════════════════════════════════════════════════

    IF v_req_city_norm = '' THEN

      v_city_score := 15;


    ELSIF
      v_art_city_norm <> ''
      AND v_art_city_norm = v_req_city_norm
    THEN

      v_city_score := 30;


    ELSIF
      v_art_city_norm <> ''
      AND (
        position(v_req_city_norm IN v_art_city_norm) > 0
        OR
        position(v_art_city_norm IN v_req_city_norm) > 0
      )
    THEN

      v_city_score := 28;


    ELSIF
      v_art_zone_norm <> ''
      AND position(v_req_city_norm IN v_art_zone_norm) > 0
    THEN

      v_city_score := 24;


    ELSE

      v_city_score   := 0;
      v_req_in_group := false;
      v_art_in_group := false;


      -- Geographic proximity group
      IF v_art_city_norm <> '' THEN

        FOREACH v_group IN ARRAY v_city_groups
        LOOP

          v_req_in_group :=
            position(v_req_city_norm IN v_group) > 0;

          v_art_in_group :=
            position(v_art_city_norm IN v_group) > 0;

          IF v_req_in_group AND v_art_in_group THEN
            v_city_score := 18;
            EXIT;
          END IF;

        END LOOP;

      END IF;


      -- National / all-Morocco coverage
      IF
        v_city_score = 0
        AND v_art_zone_norm <> ''
        AND (
          position('national' IN v_art_zone_norm) > 0
          OR position('maroc' IN v_art_zone_norm) > 0
          OR position('tout' IN v_art_zone_norm) > 0
        )
      THEN

        v_city_score := 6;

      END IF;


      -- No legitimate geographic relationship
      IF v_city_score = 0 THEN
        CONTINUE;
      END IF;

    END IF;


    -- ════════════════════════════════════════════════════════
    -- TRUST SCORE — weight 20
    -- ════════════════════════════════════════════════════════

    v_trust_score := 0;


    IF v_artisan_rc >= 100 THEN
      v_trust_score := v_trust_score + 12;

    ELSIF v_artisan_rc >= 50 THEN
      v_trust_score := v_trust_score + 9;

    ELSIF v_artisan_rc >= 20 THEN
      v_trust_score := v_trust_score + 6;

    ELSIF v_artisan_rc >= 5 THEN
      v_trust_score := v_trust_score + 3;

    ELSIF v_artisan_rc = 0 THEN
      v_trust_score := v_trust_score - 2;

    END IF;


    IF v_artisan_rat >= 4.8 THEN
      v_trust_score := v_trust_score + 8;

    ELSIF v_artisan_rat >= 4.5 THEN
      v_trust_score := v_trust_score + 6;

    ELSIF v_artisan_rat >= 4.0 THEN
      v_trust_score := v_trust_score + 4;

    ELSIF
      v_artisan_rat > 0.0
      AND v_artisan_rat < 3.5
    THEN
      v_trust_score := v_trust_score - 3;

    END IF;


    IF v_trust_score > 20 THEN
      v_trust_score := 20;
    END IF;

    IF v_trust_score < 0 THEN
      v_trust_score := 0;
    END IF;


    -- ════════════════════════════════════════════════════════
    -- ACTIVITY SCORE — weight 15
    -- ════════════════════════════════════════════════════════

    IF v_artisan_updated IS NULL THEN

      v_days_since := 999;

    ELSE

      v_days_since :=
        EXTRACT(
          EPOCH FROM (now() - v_artisan_updated)
        )::integer / 86400;

    END IF;


    IF v_days_since <= 1 THEN
      v_act_score := 15;

    ELSIF v_days_since <= 7 THEN
      v_act_score := 12;

    ELSIF v_days_since <= 30 THEN
      v_act_score := 8;

    ELSIF v_days_since <= 90 THEN
      v_act_score := 4;

    ELSE
      v_act_score := 0;

    END IF;


    -- ════════════════════════════════════════════════════════
    -- COMPOSITE SCORE
    -- ════════════════════════════════════════════════════════

    v_score :=
      v_svc_score
      + v_city_score
      + v_trust_score
      + v_act_score;


    -- Higher score wins.
    -- Equal score preserves artisan.id ASC loop order.
    IF v_score > v_best_score THEN

      v_best_score      := v_score;
      v_best_artisan_id := v_artisan_id;

    END IF;

  END LOOP;


  -- ──────────────────────────────────────────────────────────
  -- STEP 7 — no candidate
  -- ──────────────────────────────────────────────────────────

  IF v_best_artisan_id IS NULL THEN

    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'no_candidate'
    );

  END IF;


  -- ──────────────────────────────────────────────────────────
  -- STEP 8 — create exactly one OFFERED mission
  -- ──────────────────────────────────────────────────────────

  BEGIN

    INSERT INTO public.missions (
      request_id,
      artisan_profile_id,
      status,
      agreed_price
    )
    VALUES (
      v_request_id_text,
      v_best_artisan_id,
      'offered',
      NULL
    )
    RETURNING id
    INTO v_new_mission_id;


  EXCEPTION

    WHEN unique_violation THEN

      -- Never assume every 23505 is the expected concurrent offer.
      -- Verify an actual persisted offered mission exists.
      SELECT m.id
      INTO v_new_mission_id
      FROM public.missions m
      WHERE m.request_id = v_request_id_text
        AND m.status = 'offered'
      LIMIT 1;


      IF v_new_mission_id IS NOT NULL THEN

        RETURN jsonb_build_object(
          'ok', true,
          'reason', 'existing_offer',
          'mission_id', v_new_mission_id
        );

      ELSE

        RETURN jsonb_build_object(
          'ok', false,
          'reason', 'conflict'
        );

      END IF;


    WHEN OTHERS THEN

      RAISE WARNING
        '[dispatch_request_v1] insert error: %',
        SQLERRM;

      RETURN jsonb_build_object(
        'ok', false,
        'reason', 'internal_error'
      );

  END;


  -- Parent service_request deliberately remains status='new'.
  -- claim_mission() is the authority that transitions it to assigned.

  RETURN jsonb_build_object(
    'ok', true,
    'reason', 'dispatched',
    'mission_id', v_new_mission_id,
    'artisan_id', v_best_artisan_id,
    'score', v_best_score
  );


EXCEPTION

  WHEN OTHERS THEN

    RAISE WARNING
      '[dispatch_request_v1] unexpected error: %',
      SQLERRM;

    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'internal_error'
    );

END;

$function$

CREATE OR REPLACE FUNCTION public.electricity_prework_artisan_v1(p_mission_id uuid, p_professional_checks jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m public.missions%ROWTYPE; r public.service_requests%ROWTYPE; o public.fixeo_pricing_offers_v1%ROWTYPE; tariff jsonb; previous fixeo_private.electricity_prework_v1%ROWTYPE;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
 SELECT * INTO m FROM public.missions WHERE id=p_mission_id FOR UPDATE;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.artisans WHERE id=m.artisan_profile_id AND owner_user_id=auth.uid()) THEN
  RAISE EXCEPTION 'Mission not available' USING ERRCODE='42501';
 END IF;
 SELECT * INTO r FROM public.service_requests WHERE id::text=m.request_id FOR UPDATE;
 SELECT * INTO o FROM public.fixeo_pricing_offers_v1 WHERE id=m.pricing_offer_id;
 tariff:=fixeo_private.electricity_tariff_v1(o.service_code);
 IF tariff IS NULL OR o.service_code='electricite.diagnostic' OR o.catalogue_version IS DISTINCT FROM 'electricity-pilot-v1'
  OR r.pricing_offer_id IS DISTINCT FROM o.id OR p_professional_checks IS DISTINCT FROM tariff->'professional_checks' THEN
  RAISE EXCEPTION 'Professional checks and repair scope must be confirmed' USING ERRCODE='22023';
 END IF;
 SELECT * INTO previous FROM fixeo_private.electricity_prework_v1 WHERE mission_id=m.id;
 IF FOUND THEN
  IF previous.artisan_id IS DISTINCT FROM m.artisan_profile_id OR previous.offer_id IS DISTINCT FROM o.id OR previous.professional_checks IS DISTINCT FROM p_professional_checks THEN
   RAISE EXCEPTION 'Idempotency conflict' USING ERRCODE='22023';
  END IF;
  RETURN fixeo_private.electricity_state_v1(m.id);
 END IF;
 IF m.status IS DISTINCT FROM 'pending' OR r.status IS DISTINCT FROM 'in_progress' OR m.final_price IS NOT NULL
  OR coalesce(r.commission_paid,false) OR r.commission_paid_at IS NOT NULL OR coalesce(r.commission_status,'') IN ('payée','paid') THEN
  RAISE EXCEPTION 'Pre-work checks unavailable for this mission state' USING ERRCODE='22023';
 END IF;
 INSERT INTO fixeo_private.electricity_prework_v1(mission_id,offer_id,artisan_id,professional_checks) VALUES(m.id,o.id,m.artisan_profile_id,p_professional_checks);
 RETURN fixeo_private.electricity_state_v1(m.id);
END $function$

CREATE OR REPLACE FUNCTION public.electricity_repair_artisan_v1(p_mission_id uuid, p_service_code text DEFAULT NULL::text, p_inputs jsonb DEFAULT '{}'::jsonb, p_paid_minor bigint DEFAULT 0, p_proposal_id uuid DEFAULT NULL::uuid, p_same_visit boolean DEFAULT false, p_professional_checks jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m public.missions%ROWTYPE; r public.service_requests%ROWTYPE; original public.fixeo_pricing_offers_v1%ROWTYPE;
 tariff jsonb; previous fixeo_private.electricity_proposals_v1%ROWTYPE; repair_id uuid;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
 SELECT * INTO m FROM public.missions WHERE id=p_mission_id FOR UPDATE;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.artisans WHERE id=m.artisan_profile_id AND owner_user_id=auth.uid()) THEN
  RAISE EXCEPTION 'Mission not available' USING ERRCODE='42501';
 END IF;
 IF p_service_code IS NULL THEN RETURN fixeo_private.electricity_state_v1(m.id); END IF;
 SELECT * INTO r FROM public.service_requests WHERE id::text=m.request_id FOR UPDATE;
 SELECT * INTO original FROM public.fixeo_pricing_offers_v1 WHERE id=m.pricing_offer_id;
 tariff:=fixeo_private.electricity_tariff_v1(p_service_code);
 IF tariff IS NULL OR p_service_code='electricite.diagnostic' OR p_inputs IS DISTINCT FROM tariff->'inputs'
  OR p_professional_checks IS DISTINCT FROM tariff->'professional_checks' OR p_same_visit IS DISTINCT FROM true OR p_paid_minor IS NULL OR p_paid_minor NOT IN (0,24000) OR p_proposal_id IS NULL THEN
  RAISE EXCEPTION 'Repair scope, cash credit and same visit must be confirmed' USING ERRCODE='22023';
 END IF;
 SELECT * INTO previous FROM fixeo_private.electricity_proposals_v1 WHERE id=p_proposal_id;
 IF FOUND THEN
  IF previous.mission_id IS DISTINCT FROM m.id OR previous.artisan_id IS DISTINCT FROM m.artisan_profile_id
   OR previous.diagnostic_paid_minor IS DISTINCT FROM p_paid_minor OR NOT EXISTS(
    SELECT 1 FROM public.fixeo_pricing_offers_v1 WHERE id=previous.repair_offer_id AND service_code=p_service_code AND scope->'inputs'=p_inputs AND scope->'professional_checks'=p_professional_checks
   ) THEN RAISE EXCEPTION 'Idempotency conflict' USING ERRCODE='22023'; END IF;
  RETURN fixeo_private.electricity_state_v1(m.id);
 END IF;
 IF original.service_code IS DISTINCT FROM 'electricite.diagnostic' OR original.catalogue_version IS DISTINCT FROM 'electricity-pilot-v1'
  OR original.client_total_minor IS DISTINCT FROM 24000 OR original.commission_minor IS DISTINCT FROM 6000
  OR r.pricing_offer_id IS DISTINCT FROM original.id OR m.status IS DISTINCT FROM 'pending' OR r.status IS DISTINCT FROM 'in_progress'
  OR m.final_price IS NOT NULL OR coalesce(r.commission_paid,false) OR r.commission_paid_at IS NOT NULL OR coalesce(r.commission_status,'') IN ('payée','paid')
  OR EXISTS(SELECT 1 FROM public.missions WHERE request_id=r.id::text AND id<>m.id AND status IN ('pending','done','validated'))
  OR EXISTS(SELECT 1 FROM fixeo_private.electricity_decisions_v1 WHERE request_id=r.id AND accepted) THEN
  RAISE EXCEPTION 'Same visit repair is not available' USING ERRCODE='22023';
 END IF;
 INSERT INTO public.fixeo_pricing_offers_v1(offer_key,pricing_version,currency,service_code,catalogue_version,city,scope,vap_minor,materials_minor,commission_minor,client_total_minor,expires_at)
 VALUES(gen_random_uuid(),'vap-bp33-v1','MAD',p_service_code,'electricity-pilot-v1',original.city,
  jsonb_build_object('kind','SAME_VISIT_REPAIR','mission_id',m.id,'original_offer_id',original.id,'inputs',p_inputs,'professional_checks',p_professional_checks,'label',tariff->>'label','description',tariff->>'scope'),
  (tariff->>'vap_minor')::bigint,0,6000,(tariff->>'total_minor')::bigint,clock_timestamp()+interval '45 minutes') RETURNING id INTO repair_id;
 INSERT INTO fixeo_private.electricity_proposals_v1(id,mission_id,request_id,artisan_id,original_offer_id,repair_offer_id,diagnostic_paid_minor,same_visit)
 VALUES(p_proposal_id,m.id,r.id,m.artisan_profile_id,original.id,repair_id,p_paid_minor,true);
 RETURN fixeo_private.electricity_state_v1(m.id);
END $function$

CREATE OR REPLACE FUNCTION public.electricity_repair_guest_v1(p_tracking_ref text, p_guest_hash text, p_action text DEFAULT 'read'::text, p_proposal_id uuid DEFAULT NULL::uuid, p_expected_paid_minor bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.service_requests%ROWTYPE; m public.missions%ROWTYPE; p fixeo_private.electricity_proposals_v1%ROWTYPE;
 repair public.fixeo_pricing_offers_v1%ROWTYPE; decision boolean;
BEGIN
 SELECT * INTO r FROM public.service_requests WHERE tracking_ref=p_tracking_ref;
 IF NOT FOUND OR r.guest_token_hash IS NULL OR p_guest_hash IS NULL OR p_guest_hash<>r.guest_token_hash THEN
  RAISE EXCEPTION 'Request not found' USING ERRCODE='42501';
 END IF;
 IF p_action='read' THEN
  SELECT * INTO m FROM public.missions WHERE request_id=r.id::text AND status IN ('pending','done','validated') ORDER BY id LIMIT 1;
  RETURN fixeo_private.electricity_state_v1(m.id);
 END IF;
 IF p_action IS NULL OR p_action NOT IN ('accept','decline') THEN RAISE EXCEPTION 'Invalid decision' USING ERRCODE='22023'; END IF;
 SELECT * INTO p FROM fixeo_private.electricity_proposals_v1 WHERE id=p_proposal_id AND request_id=r.id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Proposal not found' USING ERRCODE='22023'; END IF;
 -- Same locking order as proposal, lifecycle and financial mission updates.
 SELECT * INTO m FROM public.missions WHERE id=p.mission_id FOR UPDATE;
 SELECT * INTO r FROM public.service_requests WHERE id=p.request_id FOR UPDATE;
 IF p_guest_hash IS DISTINCT FROM r.guest_token_hash THEN RAISE EXCEPTION 'Request not found' USING ERRCODE='42501'; END IF;
 IF p_expected_paid_minor IS DISTINCT FROM p.diagnostic_paid_minor THEN RAISE EXCEPTION 'Cash credit must match the displayed proposal' USING ERRCODE='22023'; END IF;
 SELECT accepted INTO decision FROM fixeo_private.electricity_decisions_v1 WHERE proposal_id=p.id;
 IF FOUND THEN
  IF decision IS DISTINCT FROM (p_action='accept') THEN RAISE EXCEPTION 'Decision already recorded' USING ERRCODE='22023'; END IF;
  RETURN fixeo_private.electricity_state_v1(m.id);
 END IF;
 SELECT * INTO STRICT repair FROM public.fixeo_pricing_offers_v1 WHERE id=p.repair_offer_id;
 IF m.status IS DISTINCT FROM 'pending' OR r.status IS DISTINCT FROM 'in_progress' OR m.final_price IS NOT NULL
  OR coalesce(r.commission_paid,false) OR r.commission_paid_at IS NOT NULL OR coalesce(r.commission_status,'') IN ('payée','paid') OR repair.expires_at<=now()
  OR m.artisan_profile_id IS DISTINCT FROM p.artisan_id OR m.pricing_offer_id IS DISTINCT FROM p.original_offer_id
  OR r.pricing_offer_id IS DISTINCT FROM p.original_offer_id
  OR EXISTS(SELECT 1 FROM fixeo_private.electricity_proposals_v1 WHERE mission_id=m.id AND sequence_id>p.sequence_id)
  OR EXISTS(SELECT 1 FROM public.missions WHERE request_id=r.id::text AND id<>m.id AND status IN ('pending','done','validated'))
  OR EXISTS(SELECT 1 FROM fixeo_private.electricity_decisions_v1 WHERE request_id=r.id AND accepted) THEN
  RAISE EXCEPTION 'Proposal no longer available' USING ERRCODE='22023';
 END IF;
 INSERT INTO fixeo_private.electricity_decisions_v1(proposal_id,mission_id,request_id,accepted) VALUES(p.id,m.id,r.id,p_action='accept');
 IF p_action='accept' THEN UPDATE public.missions SET agreed_price=agreed_price WHERE id=m.id; END IF;
 RETURN fixeo_private.electricity_state_v1(m.id);
END $function$

CREATE OR REPLACE FUNCTION public.finalize_artisan_signup_v1(p_full_name text, p_phone text, p_services text[], p_cities text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_artisan_id uuid;
  v_name text := trim(coalesce(p_full_name,''));
  v_phone text := trim(coalesce(p_phone,''));
  v_services text[];
  v_cities text[];
  v_primary_service text;
  v_primary_city text;
begin
  if v_uid is null then return jsonb_build_object('ok',false,'reason','unauthenticated'); end if;
  if not exists(select 1 from public.users u where u.id=v_uid and u.role='artisan') then
    return jsonb_build_object('ok',false,'reason','artisan_role_required');
  end if;
  if length(v_name)<3 then return jsonb_build_object('ok',false,'reason','name_required'); end if;

  select coalesce(array_agg(distinct trim(x)) filter(where trim(x)<>''),'{}'::text[])
    into v_services from unnest(coalesce(p_services,'{}'::text[])) x;
  select coalesce(array_agg(distinct trim(x)) filter(where trim(x)<>''),'{}'::text[])
    into v_cities from unnest(coalesce(p_cities,'{}'::text[])) x;

  if cardinality(v_services)=0 then return jsonb_build_object('ok',false,'reason','service_required'); end if;
  if cardinality(v_cities)=0 then return jsonb_build_object('ok',false,'reason','city_required'); end if;
  if cardinality(v_services)>12 or cardinality(v_cities)>20 then
    return jsonb_build_object('ok',false,'reason','too_many_values');
  end if;

  v_primary_service := v_services[1];
  v_primary_city := v_cities[1];

  select a.id into v_artisan_id from public.artisans a where a.owner_user_id=v_uid limit 1 for update;
  if v_artisan_id is null then
    insert into public.artisans(
      owner_user_id,full_name,name,service_category,category,services,city,work_zone,
      phone,phone_public,claimed,claim_status,onboarding_completed,availability,verified,is_verified,is_public,source,created_at,updated_at
    ) values (
      v_uid,v_name,v_name,v_primary_service,v_primary_service,to_jsonb(v_services),v_primary_city,
      array_to_string(v_cities, ', '),nullif(v_phone,''),nullif(v_phone,''),true,'approved',false,
      'unavailable',false,false,false,'self_signup',now(),now()
    ) returning id into v_artisan_id;
  else
    update public.artisans set
      full_name=v_name,name=v_name,service_category=v_primary_service,category=v_primary_service,
      services=to_jsonb(v_services),city=v_primary_city,work_zone=array_to_string(v_cities, ', '),
      phone=coalesce(nullif(v_phone,''),phone),phone_public=coalesce(nullif(v_phone,''),phone_public),
      updated_at=now()
    where id=v_artisan_id;
  end if;

  delete from public.artisan_service_categories where artisan_id=v_artisan_id;
  insert into public.artisan_service_categories(artisan_id,service_category)
    select v_artisan_id,x from unnest(v_services) x;
  delete from public.artisan_service_cities where artisan_id=v_artisan_id;
  insert into public.artisan_service_cities(artisan_id,city)
    select v_artisan_id,x from unnest(v_cities) x;

  update public.profiles set city=v_primary_city where id=v_uid;
  update public.users set city=v_primary_city where id=v_uid;

  return jsonb_build_object('ok',true,'artisan_id',v_artisan_id,'services',to_jsonb(v_services),'cities',to_jsonb(v_cities));
end $function$

CREATE OR REPLACE FUNCTION public.fixeo_vap_commission_minor_v1(v bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE weighted bigint;
BEGIN
  IF v IS NULL OR v <= 0 OR v > 50000000 THEN
    RAISE EXCEPTION 'Invalid VAP centimes' USING ERRCODE='22023';
  END IF;
  weighted := 15 * least(v,200000)
    + 10 * least(greatest(v-200000,0),300000)
    + 7 * least(greatest(v-500000,0),500000)
    + 5 * greatest(v-1000000,0);
  RETURN least(150000,greatest(6000,(weighted+50)/100));
END;
$function$

CREATE OR REPLACE FUNCTION public.get_accepted_mission_detail(p_mission_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_artisan_id     uuid;
  v_mission_status text;
  v_artisan_match  uuid;
  v_result         jsonb;
BEGIN

  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'unauthenticated');
  END IF;

  SELECT a.id
  INTO   v_artisan_id
  FROM   public.artisans a
  WHERE  a.owner_user_id = auth.uid()
  LIMIT  1;

  IF v_artisan_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'artisan_not_found');
  END IF;

  SELECT m.status, m.artisan_profile_id
  INTO   v_mission_status, v_artisan_match
  FROM   public.missions m
  WHERE  m.id = p_mission_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'mission_not_found');
  END IF;

  IF v_artisan_match != v_artisan_id THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_your_mission');
  END IF;

  IF v_mission_status NOT IN ('pending', 'done', 'validated') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_accepted_yet');
  END IF;

  SELECT jsonb_build_object(
    'ok',               true,
    'mission_id',       m.id,
    'mission_status',   m.status,
    'request_status',   sr.status,
    'accepted_at',      m.accepted_at,
    'agreed_price',     m.agreed_price,
    'service_category', sr.service_category,
    'city',             sr.city,
    'urgency',          sr.urgency,
    'description',      sr.description,
    'client_phone',     sr.client_phone
  )
  INTO v_result
  FROM   public.missions m
  JOIN   public.service_requests sr
    ON   m.request_id = sr.id::text
  WHERE  m.id = p_mission_id;

  IF v_result IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'request_not_found');
  END IF;

  RETURN v_result;

END;

$function$

CREATE OR REPLACE FUNCTION public.get_enterprise_equipment_detail_v1(p_enterprise_id uuid, p_equipment_id uuid, p_history_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_equipment jsonb; v_requests jsonb; v_plans jsonb; v_assets jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'unauthenticated'; END IF;
  IF p_history_limit<1 OR p_history_limit>500 THEN RAISE EXCEPTION 'invalid_limit'; END IF;
  IF NOT fixeo_private._fixeo_can_access_enterprise_equipment(p_enterprise_id,p_equipment_id) THEN RAISE EXCEPTION 'forbidden'; END IF;

  SELECT to_jsonb(x) INTO v_equipment FROM (
    SELECT e.id,e.enterprise_id,e.site_id,s.name site_name,s.city,e.name,e.category,e.asset_code,
      e.manufacturer,e.model,e.serial_number,e.installed_at,e.criticality,e.status,e.notes,e.created_at,e.updated_at
    FROM public.enterprise_equipment e JOIN public.enterprise_sites s ON s.id=e.site_id
    WHERE e.id=p_equipment_id AND e.enterprise_id=p_enterprise_id
  ) x;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'request_id',sr.id,'service_category',sr.service_category,'urgency',sr.urgency,
    'status',sr.status,'created_at',sr.created_at
  ) ORDER BY sr.created_at DESC),'[]'::jsonb)
  INTO v_requests
  FROM (
    SELECT sr.*
    FROM public.enterprise_equipment_request_links l
    JOIN public.service_requests sr ON sr.id=l.service_request_id
    WHERE l.equipment_id=p_equipment_id
    ORDER BY sr.created_at DESC
    LIMIT p_history_limit
  ) sr;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'plan_id',p.id,'name',p.name,'service_category',p.service_category,
    'frequency',p.frequency,'interval_count',p.interval_count,'next_due_at',p.next_due_at,'status',p.status
  ) ORDER BY p.next_due_at),'[]'::jsonb)
  INTO v_plans
  FROM public.enterprise_equipment_maintenance_links l
  JOIN public.enterprise_maintenance_plans p ON p.id=l.plan_id
  WHERE l.equipment_id=p_equipment_id;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id',a.id,'asset_type',a.asset_type,'title',a.title,'storage_path',a.storage_path,
    'mime_type',a.mime_type,'size_bytes',a.size_bytes,'created_at',a.created_at
  ) ORDER BY a.created_at DESC),'[]'::jsonb)
  INTO v_assets
  FROM public.enterprise_equipment_assets a
  WHERE a.equipment_id=p_equipment_id;

  RETURN jsonb_build_object('ok',true,'equipment',v_equipment,'interventions',v_requests,'maintenance_plans',v_plans,'assets',v_assets);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_enterprise_request_breakdown(p_enterprise_id uuid, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_site_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_from timestamptz := COALESCE(p_from, '-infinity'::timestamptz);
  v_to   timestamptz := COALESCE(p_to, 'infinity'::timestamptz);
  v_result jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','unauthenticated');
  END IF;

  IF p_enterprise_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','enterprise_required');
  END IF;

  IF NOT (
    fixeo_private._fixeo_is_enterprise_member(p_enterprise_id)
    OR fixeo_private._fixeo_is_admin()
  ) THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','forbidden');
  END IF;

  IF v_from > v_to THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invalid_period');
  END IF;

  IF p_site_id IS NOT NULL AND NOT fixeo_private._fixeo_can_access_enterprise_site(
    p_enterprise_id,p_site_id
  ) THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invalid_site');
  END IF;

  WITH rb AS MATERIALIZED (
    SELECT
      sr.service_category,
      sr.urgency,
      sr.status
    FROM public.enterprise_request_context erc
    JOIN public.service_requests sr
      ON sr.id=erc.service_request_id
    WHERE erc.enterprise_id=p_enterprise_id
      AND (p_site_id IS NULL OR erc.site_id=p_site_id)
      AND fixeo_private._fixeo_can_access_enterprise_site(p_enterprise_id,erc.site_id)
      AND sr.created_at >= v_from
      AND sr.created_at < v_to
  ),
  category_rows AS (
    SELECT service_category AS key,pg_catalog.count(*) AS count
    FROM rb GROUP BY service_category
  ),
  urgency_rows AS (
    SELECT COALESCE(urgency,'unspecified') AS key,pg_catalog.count(*) AS count
    FROM rb GROUP BY COALESCE(urgency,'unspecified')
  ),
  status_rows AS (
    SELECT status AS key,pg_catalog.count(*) AS count
    FROM rb GROUP BY status
  )
  SELECT pg_catalog.jsonb_build_object(
    'ok',true,
    'enterprise_id',p_enterprise_id,
    'site_id',p_site_id,
    'from',p_from,
    'to',p_to,
    'by_service_category',COALESCE((
      SELECT pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object('key',key,'count',count)
        ORDER BY count DESC,key
      ) FROM category_rows
    ),'[]'::jsonb),
    'by_urgency',COALESCE((
      SELECT pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object('key',key,'count',count)
        ORDER BY count DESC,key
      ) FROM urgency_rows
    ),'[]'::jsonb),
    'by_request_status',COALESCE((
      SELECT pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object('key',key,'count',count)
        ORDER BY count DESC,key
      ) FROM status_rows
    ),'[]'::jsonb)
  )
  INTO v_result;

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.plumbing_repair_artisan_v1(p_mission_id uuid, p_service_code text DEFAULT NULL::text, p_inputs jsonb DEFAULT '{}'::jsonb, p_paid_minor bigint DEFAULT 0, p_proposal_id uuid DEFAULT NULL::uuid, p_same_visit boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m public.missions%ROWTYPE; r public.service_requests%ROWTYPE; original public.fixeo_pricing_offers_v1%ROWTYPE;
 tariff jsonb; previous fixeo_private.plumbing_proposals_v1%ROWTYPE; repair_id uuid;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
 SELECT * INTO m FROM public.missions WHERE id=p_mission_id FOR UPDATE;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.artisans WHERE id=m.artisan_profile_id AND owner_user_id=auth.uid()) THEN
  RAISE EXCEPTION 'Mission not available' USING ERRCODE='42501';
 END IF;
 IF p_service_code IS NULL THEN RETURN fixeo_private.plumbing_state_v1(m.id); END IF;
 SELECT * INTO r FROM public.service_requests WHERE id::text=m.request_id FOR UPDATE;
 SELECT * INTO original FROM public.fixeo_pricing_offers_v1 WHERE id=m.pricing_offer_id;
 tariff:=fixeo_private.plumbing_tariff_v1(p_service_code);
 IF tariff IS NULL OR p_service_code='plomberie.diagnostic' OR p_inputs IS DISTINCT FROM tariff->'inputs'
  OR p_same_visit IS DISTINCT FROM true OR p_paid_minor IS NULL OR p_paid_minor NOT IN (0,22000) OR p_proposal_id IS NULL THEN
  RAISE EXCEPTION 'Repair scope, cash credit and same visit must be confirmed' USING ERRCODE='22023';
 END IF;
 SELECT * INTO previous FROM fixeo_private.plumbing_proposals_v1 WHERE id=p_proposal_id;
 IF FOUND THEN
  IF previous.mission_id IS DISTINCT FROM m.id OR previous.artisan_id IS DISTINCT FROM m.artisan_profile_id
   OR previous.diagnostic_paid_minor IS DISTINCT FROM p_paid_minor OR NOT EXISTS(
    SELECT 1 FROM public.fixeo_pricing_offers_v1 WHERE id=previous.repair_offer_id AND service_code=p_service_code AND scope->'inputs'=p_inputs
   ) THEN RAISE EXCEPTION 'Idempotency conflict' USING ERRCODE='22023'; END IF;
  RETURN fixeo_private.plumbing_state_v1(m.id);
 END IF;
 IF original.service_code IS DISTINCT FROM 'plomberie.diagnostic' OR original.catalogue_version IS DISTINCT FROM 'plumbing-pilot-v1'
  OR original.client_total_minor IS DISTINCT FROM 22000 OR original.commission_minor IS DISTINCT FROM 6000
  OR r.pricing_offer_id IS DISTINCT FROM original.id OR m.status IS DISTINCT FROM 'pending' OR r.status IS DISTINCT FROM 'in_progress'
  OR m.final_price IS NOT NULL OR coalesce(r.commission_paid,false) OR r.commission_paid_at IS NOT NULL OR coalesce(r.commission_status,'') IN ('payée','paid')
  OR EXISTS(SELECT 1 FROM public.missions WHERE request_id=r.id::text AND id<>m.id AND status IN ('pending','done','validated'))
  OR EXISTS(SELECT 1 FROM fixeo_private.plumbing_decisions_v1 WHERE request_id=r.id AND accepted) THEN
  RAISE EXCEPTION 'Same visit repair is not available' USING ERRCODE='22023';
 END IF;
 INSERT INTO public.fixeo_pricing_offers_v1(offer_key,pricing_version,currency,service_code,catalogue_version,city,scope,vap_minor,materials_minor,commission_minor,client_total_minor,expires_at)
 VALUES(gen_random_uuid(),'vap-bp33-v1','MAD',p_service_code,'plumbing-pilot-v1',original.city,
  jsonb_build_object('kind','SAME_VISIT_REPAIR','mission_id',m.id,'original_offer_id',original.id,'inputs',p_inputs,'label',tariff->>'label','description',tariff->>'scope'),
  (tariff->>'vap_minor')::bigint,0,6000,(tariff->>'total_minor')::bigint,clock_timestamp()+interval '45 minutes') RETURNING id INTO repair_id;
 INSERT INTO fixeo_private.plumbing_proposals_v1(id,mission_id,request_id,artisan_id,original_offer_id,repair_offer_id,diagnostic_paid_minor,same_visit)
 VALUES(p_proposal_id,m.id,r.id,m.artisan_profile_id,original.id,repair_id,p_paid_minor,true);
 RETURN fixeo_private.plumbing_state_v1(m.id);
END $function$

CREATE OR REPLACE FUNCTION public.plumbing_repair_guest_v1(p_tracking_ref text, p_guest_hash text, p_action text DEFAULT 'read'::text, p_proposal_id uuid DEFAULT NULL::uuid, p_expected_paid_minor bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.service_requests%ROWTYPE; m public.missions%ROWTYPE; p fixeo_private.plumbing_proposals_v1%ROWTYPE;
 repair public.fixeo_pricing_offers_v1%ROWTYPE; decision boolean;
BEGIN
 SELECT * INTO r FROM public.service_requests WHERE tracking_ref=p_tracking_ref;
 IF NOT FOUND OR r.guest_token_hash IS NULL OR p_guest_hash IS NULL OR p_guest_hash<>r.guest_token_hash THEN
  RAISE EXCEPTION 'Request not found' USING ERRCODE='42501';
 END IF;
 IF p_action='read' THEN
  SELECT * INTO m FROM public.missions WHERE request_id=r.id::text AND status IN ('pending','done','validated') ORDER BY id LIMIT 1;
  RETURN fixeo_private.plumbing_state_v1(m.id);
 END IF;
 IF p_action IS NULL OR p_action NOT IN ('accept','decline') THEN RAISE EXCEPTION 'Invalid decision' USING ERRCODE='22023'; END IF;
 SELECT * INTO p FROM fixeo_private.plumbing_proposals_v1 WHERE id=p_proposal_id AND request_id=r.id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Proposal not found' USING ERRCODE='22023'; END IF;
 -- Same locking order as proposal, lifecycle and financial mission updates.
 SELECT * INTO m FROM public.missions WHERE id=p.mission_id FOR UPDATE;
 SELECT * INTO r FROM public.service_requests WHERE id=p.request_id FOR UPDATE;
 IF p_guest_hash IS DISTINCT FROM r.guest_token_hash THEN RAISE EXCEPTION 'Request not found' USING ERRCODE='42501'; END IF;
 IF p_expected_paid_minor IS DISTINCT FROM p.diagnostic_paid_minor THEN RAISE EXCEPTION 'Cash credit must match the displayed proposal' USING ERRCODE='22023'; END IF;
 SELECT accepted INTO decision FROM fixeo_private.plumbing_decisions_v1 WHERE proposal_id=p.id;
 IF FOUND THEN
  IF decision IS DISTINCT FROM (p_action='accept') THEN RAISE EXCEPTION 'Decision already recorded' USING ERRCODE='22023'; END IF;
  RETURN fixeo_private.plumbing_state_v1(m.id);
 END IF;
 SELECT * INTO STRICT repair FROM public.fixeo_pricing_offers_v1 WHERE id=p.repair_offer_id;
 IF m.status IS DISTINCT FROM 'pending' OR r.status IS DISTINCT FROM 'in_progress' OR m.final_price IS NOT NULL
  OR coalesce(r.commission_paid,false) OR r.commission_paid_at IS NOT NULL OR coalesce(r.commission_status,'') IN ('payée','paid') OR repair.expires_at<=now()
  OR m.artisan_profile_id IS DISTINCT FROM p.artisan_id OR m.pricing_offer_id IS DISTINCT FROM p.original_offer_id
  OR r.pricing_offer_id IS DISTINCT FROM p.original_offer_id
  OR EXISTS(SELECT 1 FROM fixeo_private.plumbing_proposals_v1 WHERE mission_id=m.id AND sequence_id>p.sequence_id)
  OR EXISTS(SELECT 1 FROM public.missions WHERE request_id=r.id::text AND id<>m.id AND status IN ('pending','done','validated'))
  OR EXISTS(SELECT 1 FROM fixeo_private.plumbing_decisions_v1 WHERE request_id=r.id AND accepted) THEN
  RAISE EXCEPTION 'Proposal no longer available' USING ERRCODE='22023';
 END IF;
 INSERT INTO fixeo_private.plumbing_decisions_v1(proposal_id,mission_id,request_id,accepted) VALUES(p.id,m.id,r.id,p_action='accept');
 IF p_action='accept' THEN UPDATE public.missions SET agreed_price=agreed_price WHERE id=m.id; END IF;
 RETURN fixeo_private.plumbing_state_v1(m.id);
END $function$

CREATE OR REPLACE FUNCTION public.publish_due_notification_alerts_s1b2()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_due record;
  v_event fixeo_private.notification_assignment_events_s1b2%ROWTYPE;
  v_request public.service_requests%ROWTYPE;
  v_mission public.missions%ROWTYPE;
  v_notification uuid;
  v_inserted integer := 0;
  v_closed integer := 0;
BEGIN
  FOR v_due IN SELECT e.mission_id,e.request_id FROM fixeo_private.notification_assignment_events_s1b2 e
    WHERE e.notified_at IS NULL AND e.closed_at IS NULL AND e.started_at <= statement_timestamp()-interval '30 minutes'
    ORDER BY e.started_at,e.mission_id LIMIT 100
  LOOP
    -- Canonical assignment/acceptance locks the request first. No business row is updated.
    SELECT * INTO v_request FROM public.service_requests WHERE id=v_due.request_id FOR UPDATE SKIP LOCKED;
    IF NOT FOUND THEN CONTINUE; END IF;
    SELECT * INTO v_event FROM fixeo_private.notification_assignment_events_s1b2
      WHERE mission_id=v_due.mission_id AND notified_at IS NULL AND closed_at IS NULL
      FOR UPDATE SKIP LOCKED;
    IF NOT FOUND THEN CONTINUE; END IF;
    SELECT * INTO v_mission FROM public.missions WHERE id=v_event.mission_id FOR UPDATE SKIP LOCKED;
    IF NOT FOUND THEN CONTINUE; END IF;
    IF v_request.status IS DISTINCT FROM 'new'
      OR v_request.target_artisan_id IS DISTINCT FROM v_event.artisan_id
      OR v_mission.request_id IS DISTINCT FROM v_event.request_id::text
      OR v_mission.artisan_profile_id IS DISTINCT FROM v_event.artisan_id
      OR v_mission.status IS DISTINCT FROM 'offered' OR v_mission.accepted_at IS NOT NULL
      OR EXISTS(SELECT 1 FROM public.missions m WHERE m.request_id=v_event.request_id::text
        AND (m.accepted_at IS NOT NULL OR m.status IN('pending','done','validated'))) THEN
      UPDATE fixeo_private.notification_assignment_events_s1b2 SET closed_at=statement_timestamp() WHERE mission_id=v_event.mission_id;
      v_closed := v_closed+1;
      CONTINUE;
    END IF;
    INSERT INTO public.notifications(recipient_user_id,recipient_role,type,title,message,related_entity_type,related_entity_id,metadata)
      VALUES(NULL,'admin','adm_mission_blocked','Offre sans acceptation depuis 30 min',
        'Mission #'||upper(right(v_event.request_id::text,6))||' : aucune acceptation enregistrée depuis 30 minutes.',
        'mission',v_event.request_id::text,
        jsonb_build_object('source','s1b2','event','targeted_offer_timeout','mission_id',v_event.mission_id,'started_at',v_event.started_at))
      RETURNING id INTO v_notification;
    UPDATE fixeo_private.notification_assignment_events_s1b2
      SET notified_at=statement_timestamp(),notification_id=v_notification WHERE mission_id=v_event.mission_id;
    v_inserted := v_inserted+1;
  END LOOP;
  RETURN jsonb_build_object('ok',true,'inserted',v_inserted,'closed',v_closed);
END $function$

CREATE OR REPLACE FUNCTION public.publish_notification_event_s1b(p_event text, p_entity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_admin boolean := false;
  v_request public.service_requests%ROWTYPE;
  v_mission public.missions%ROWTYPE;
  v_artisan public.artisans%ROWTYPE;
  v_claim public.claim_requests%ROWTYPE;
  v_items jsonb := '[]'::jsonb;
  v_item jsonb;
  v_ref text;
  v_metadata jsonb;
  v_recipient uuid;
  v_count integer := 0;
  v_affected integer;
BEGIN
  IF v_uid IS NULL OR p_entity_id IS NULL OR p_event IS NULL OR p_event NOT IN
    ('request_created','mission_accepted','mission_started','mission_completed','mission_validated','claim_submitted') THEN
    RAISE EXCEPTION 'Notification event not authorized' USING ERRCODE='42501';
  END IF;
  SELECT EXISTS(SELECT 1 FROM public.users WHERE id=v_uid AND role='admin') INTO v_admin;
  -- Serialize retries for the same business event. No business row is modified.
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('fixeo:s1b:'||p_event||':'||p_entity_id::text,0));
  v_ref := pg_catalog.upper(pg_catalog.right(p_entity_id::text,6));
  v_metadata := pg_catalog.jsonb_build_object('source','s1b','event',p_event);

  IF p_event='claim_submitted' THEN
    SELECT * INTO v_claim FROM public.claim_requests WHERE id=p_entity_id;
    IF NOT FOUND OR v_claim.status <> 'pending' OR (NOT v_admin AND v_claim.requester_user_id IS DISTINCT FROM v_uid) THEN
      RAISE EXCEPTION 'Notification event not authorized' USING ERRCODE='42501';
    END IF;
    v_items := pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('role','admin','type','adm_claim_request',
      'title','Nouvelle revendication','message','Revendication artisan soumise — ID claim: '||p_entity_id::text));
  ELSE
    SELECT * INTO v_request FROM public.service_requests WHERE id=p_entity_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Notification event not authorized' USING ERRCODE='42501'; END IF;
    IF p_event='request_created' THEN
      IF NOT v_admin AND v_request.client_profile_id IS DISTINCT FROM v_uid THEN
        RAISE EXCEPTION 'Notification event not authorized' USING ERRCODE='42501';
      END IF;
      IF v_request.client_profile_id IS NOT NULL THEN
        v_items := v_items || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('uid',v_request.client_profile_id,'role','client',
          'type','c_request_created','title','Demande publiée','message','Votre demande pour « '||coalesce(v_request.service_category,'')||' » a été envoyée.'));
      END IF;
      v_items := v_items || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('role','admin','type','adm_new_request',
        'title','Nouvelle demande','message','Nouvelle demande : '||coalesce(v_request.service_category,'')||' — #'||v_ref));
    ELSE
      -- One unambiguous active/completed mission, never a phone/metadata identity fallback.
      IF (SELECT count(*) FROM public.missions m WHERE m.request_id=p_entity_id::text AND m.status IN('pending','done','validated')) <> 1 THEN
        RAISE EXCEPTION 'Notification event not authorized' USING ERRCODE='42501';
      END IF;
      SELECT * INTO v_mission FROM public.missions WHERE request_id=p_entity_id::text AND status IN('pending','done','validated');
      SELECT * INTO v_artisan FROM public.artisans WHERE id=v_mission.artisan_profile_id;
      IF NOT FOUND OR v_artisan.owner_user_id IS NULL
        OR (v_mission.client_profile_id IS NOT NULL AND v_mission.client_profile_id IS DISTINCT FROM v_request.client_profile_id) THEN
        RAISE EXCEPTION 'Notification event not authorized' USING ERRCODE='42501';
      END IF;
      IF p_event='mission_validated' THEN
        IF (NOT v_admin AND v_request.client_profile_id IS DISTINCT FROM v_uid)
          OR v_request.status <> 'validated' OR v_mission.status NOT IN('done','validated') THEN
          RAISE EXCEPTION 'Notification event not authorized' USING ERRCODE='42501';
        END IF;
      ELSE
        IF NOT v_admin AND v_artisan.owner_user_id IS DISTINCT FROM v_uid THEN
          RAISE EXCEPTION 'Notification event not authorized' USING ERRCODE='42501';
        END IF;
        IF (p_event='mission_accepted' AND (v_request.status <> 'assigned' OR v_mission.status <> 'pending'))
          OR (p_event='mission_started' AND (v_request.status <> 'in_progress' OR v_mission.status <> 'pending'))
          OR (p_event='mission_completed' AND (v_request.status <> 'completed' OR v_mission.status <> 'done')) THEN
          RAISE EXCEPTION 'Notification event not authorized' USING ERRCODE='42501';
        END IF;
      END IF;
      CASE p_event
      WHEN 'mission_accepted' THEN
        v_items := pg_catalog.jsonb_build_array(
          pg_catalog.jsonb_build_object('uid',v_artisan.owner_user_id,'role','artisan','type','a_mission_accepted','title','Mission acceptée','message','Mission #'||v_ref||' acceptée.'),
          pg_catalog.jsonb_build_object('uid',v_request.client_profile_id,'role','client','type','c_artisan_assigned','title','Artisan assigné','message','Un artisan a accepté votre mission #'||v_ref||'.'));
      WHEN 'mission_started' THEN
        v_items := pg_catalog.jsonb_build_array(
          pg_catalog.jsonb_build_object('uid',v_artisan.owner_user_id,'role','artisan','type','a_mission_started','title','Intervention démarrée','message','Mission #'||v_ref||' démarrée.'),
          pg_catalog.jsonb_build_object('uid',v_request.client_profile_id,'role','client','type','c_mission_started','title','Intervention démarrée','message','Votre artisan a démarré l''intervention.'),
          pg_catalog.jsonb_build_object('role','admin','type','adm_new_request','title','Intervention démarrée','message','Mission #'||v_ref||' en cours.'));
      WHEN 'mission_completed' THEN
        v_items := pg_catalog.jsonb_build_array(
          pg_catalog.jsonb_build_object('uid',v_artisan.owner_user_id,'role','artisan','type','a_mission_completed','title','Mission terminée','message','Mission #'||v_ref||' en attente confirmation.'),
          pg_catalog.jsonb_build_object('uid',v_request.client_profile_id,'role','client','type','c_mission_completed','title','Intervention terminée','message','Votre artisan a terminé. Confirmez pour valider la mission.'),
          pg_catalog.jsonb_build_object('uid',v_request.client_profile_id,'role','client','type','c_confirm_pending','title','Confirmation requise','message','Confirmez la mission #'||v_ref||' pour clôturer.'),
          pg_catalog.jsonb_build_object('role','admin','type','adm_mission_validated','title','Intervention terminée','message','Mission #'||v_ref||' — À valider.'));
      WHEN 'mission_validated' THEN
        -- Amount is deliberately not inferred from client-editable financial fields.
        v_items := pg_catalog.jsonb_build_array(
          pg_catalog.jsonb_build_object('uid',v_request.client_profile_id,'role','client','type','c_mission_validated','title','Mission validée','message','Mission #'||v_ref||' validée.'),
          pg_catalog.jsonb_build_object('uid',v_artisan.owner_user_id,'role','artisan','type','a_mission_validated','title','Mission validée par le client','message','Le client a validé la mission #'||v_ref||'.'),
          pg_catalog.jsonb_build_object('role','admin','type','adm_commission_due','title','Commission à vérifier','message','Mission #'||v_ref||' validée — commission à vérifier.'));
      END CASE;
    END IF;
  END IF;

  FOR v_item IN SELECT value FROM pg_catalog.jsonb_array_elements(v_items) LOOP
    v_recipient := (v_item->>'uid')::uuid;
    -- Guest requests have no authenticated Client recipient; never create a NULL client broadcast.
    IF v_recipient IS NULL AND v_item->>'role' <> 'admin' THEN CONTINUE; END IF;
    INSERT INTO public.notifications(recipient_user_id,recipient_role,type,title,message,related_entity_type,related_entity_id,metadata)
      SELECT v_recipient,v_item->>'role',v_item->>'type',v_item->>'title',v_item->>'message',
        CASE WHEN p_event='claim_submitted' THEN 'claim_request' WHEN p_event='request_created' THEN 'service_request' ELSE 'mission' END,
        p_entity_id::text,v_metadata
      WHERE NOT EXISTS (SELECT 1 FROM public.notifications n WHERE n.related_entity_id=p_entity_id::text
        AND n.type=v_item->>'type' AND n.recipient_user_id IS NOT DISTINCT FROM v_recipient AND n.metadata @> v_metadata);
    GET DIAGNOSTICS v_affected = ROW_COUNT;
    v_count := v_count + v_affected;
  END LOOP;
  RETURN pg_catalog.jsonb_build_object('ok',true,'inserted',v_count);
END $function$

CREATE OR REPLACE FUNCTION public.reconcile_enterprise_rafi_followups_v1(p_enterprise_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_actor uuid:=auth.uid();v_role text;v_resolved int:=0;v_open int:=0;
BEGIN
 IF v_actor IS NULL THEN RETURN jsonb_build_object('ok',false,'reason','unauthenticated');END IF;
 SELECT role INTO v_role FROM public.enterprise_members WHERE enterprise_id=p_enterprise_id AND user_id=v_actor AND status='active' LIMIT 1;
 IF v_role IS NULL THEN RETURN jsonb_build_object('ok',false,'reason','forbidden');END IF;

 -- Governance cases close when the canonical case is no longer pending.
 UPDATE public.enterprise_rafi_followups f SET status='resolved',updated_by=v_actor,updated_at=now()
 WHERE f.enterprise_id=p_enterprise_id AND f.status='open' AND f.target_type='enterprise_approval_case'
 AND EXISTS(SELECT 1 FROM public.enterprise_approval_cases c WHERE c.id=f.target_id AND c.enterprise_id=p_enterprise_id AND c.status IN('approved','rejected'));
 GET DIAGNOSTICS v_resolved=ROW_COUNT;

 -- Maintenance followups close only when the canonical plan is inactive.
 UPDATE public.enterprise_rafi_followups f SET status='resolved',updated_by=v_actor,updated_at=now()
 WHERE f.enterprise_id=p_enterprise_id AND f.status='open' AND f.target_type='enterprise_maintenance_plan'
 AND EXISTS(SELECT 1 FROM public.enterprise_maintenance_plans p WHERE p.id=f.target_id AND p.enterprise_id=p_enterprise_id AND p.status='inactive');
 GET DIAGNOSTICS v_open=ROW_COUNT; v_resolved:=v_resolved+v_open;

 -- Request followups close only on canonical terminal request states.
 UPDATE public.enterprise_rafi_followups f SET status='resolved',updated_by=v_actor,updated_at=now()
 WHERE f.enterprise_id=p_enterprise_id AND f.status='open' AND f.target_type='service_request'
 AND EXISTS(SELECT 1 FROM public.enterprise_request_context erc JOIN public.service_requests sr ON sr.id=erc.service_request_id
   WHERE erc.enterprise_id=p_enterprise_id AND erc.service_request_id=f.target_id AND sr.status IN('completed','cancelled','canceled','closed'));
 GET DIAGNOSTICS v_open=ROW_COUNT; v_resolved:=v_resolved+v_open;

 SELECT count(*) INTO v_open FROM public.enterprise_rafi_followups WHERE enterprise_id=p_enterprise_id AND status='open';
 RETURN jsonb_build_object('ok',true,'resolved_now',v_resolved,'open_remaining',v_open);
EXCEPTION WHEN OTHERS THEN RAISE WARNING '[reconcile_enterprise_rafi_followups_v1] % %',SQLSTATE,SQLERRM;RETURN jsonb_build_object('ok',false,'reason','internal_error');END $function$

CREATE OR REPLACE FUNCTION public.register_enterprise_equipment_asset_v1(p_enterprise_id uuid, p_equipment_id uuid, p_asset_type text, p_title text, p_storage_path text, p_mime_type text, p_size_bytes bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_id uuid; v_prefix text;
BEGIN
  IF auth.uid() IS NULL THEN RETURN jsonb_build_object('ok',false,'reason','unauthenticated'); END IF;
  IF NOT fixeo_private._fixeo_can_manage_enterprise_equipment_id(p_enterprise_id,p_equipment_id) THEN RETURN jsonb_build_object('ok',false,'reason','forbidden'); END IF;
  IF p_asset_type NOT IN ('photo','document','manual','warranty','invoice','other') THEN RETURN jsonb_build_object('ok',false,'reason','invalid_asset_type'); END IF;
  IF p_mime_type NOT IN ('image/jpeg','image/png','image/webp','application/pdf') THEN RETURN jsonb_build_object('ok',false,'reason','invalid_mime_type'); END IF;
  IF p_size_bytes IS NULL OR p_size_bytes<1 OR p_size_bytes>10485760 THEN RETURN jsonb_build_object('ok',false,'reason','invalid_size'); END IF;
  v_prefix:='enterprise/'||p_enterprise_id::text||'/equipment/'||p_equipment_id::text||'/';
  IF p_storage_path IS NULL OR position(v_prefix in p_storage_path)<>1 THEN RETURN jsonb_build_object('ok',false,'reason','invalid_storage_path'); END IF;
  IF NOT EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='enterprise-equipment-private' AND o.name=p_storage_path) THEN
    RETURN jsonb_build_object('ok',false,'reason','object_not_found');
  END IF;

  INSERT INTO public.enterprise_equipment_assets(enterprise_id,equipment_id,asset_type,title,storage_path,mime_type,size_bytes,created_by)
  VALUES(p_enterprise_id,p_equipment_id,p_asset_type,btrim(p_title),p_storage_path,p_mime_type,p_size_bytes,auth.uid())
  RETURNING id INTO v_id;

  PERFORM fixeo_private._write_enterprise_audit_event(
    p_enterprise_id,'equipment.asset_registered','enterprise_equipment_asset',v_id,NULL,
    jsonb_build_object('equipment_id',p_equipment_id,'asset_type',p_asset_type,'mime_type',p_mime_type,'size_bytes',p_size_bytes),
    '{}'::jsonb
  );
  RETURN jsonb_build_object('ok',true,'asset_id',v_id);
EXCEPTION WHEN unique_violation THEN RETURN jsonb_build_object('ok',false,'reason','asset_exists');
WHEN OTHERS THEN
  RAISE WARNING '[register_enterprise_equipment_asset_v1] % %',SQLSTATE,SQLERRM;
  RETURN jsonb_build_object('ok',false,'reason','internal_error');
END;
$function$

CREATE OR REPLACE FUNCTION public.register_new_artisan(p_full_name text, p_service_category text, p_city text, p_phone text DEFAULT ''::text, p_description text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid           uuid;
  v_artisan_id    uuid;
  v_existing_id   uuid;
  v_full_name     text;
  v_service_cat   text;
  v_city          text;
  v_description   text;
  v_phone         text;
  v_users_updated integer;
  v_prof_updated  integer;
BEGIN

  v_uid := auth.uid();

  IF v_uid IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'unauthenticated'
    );
  END IF;

  v_full_name   := trim(COALESCE(p_full_name, ''));
  v_service_cat := trim(COALESCE(p_service_category, ''));
  v_city        := trim(COALESCE(p_city, ''));
  v_description := trim(COALESCE(p_description, ''));
  v_phone       := trim(COALESCE(p_phone, ''));

  IF length(v_full_name) < 3 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'name_required',
      'message', 'Nom complet requis (3 caractères minimum).'
    );
  END IF;

  IF v_service_cat = '' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'category_required',
      'message', 'Métier requis.'
    );
  END IF;

  IF v_city = '' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'city_required',
      'message', 'Ville requise.'
    );
  END IF;

  IF length(v_description) > 500 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'description_too_long',
      'message', 'Description limitée à 500 caractères.'
    );
  END IF;

  SELECT a.id
  INTO v_existing_id
  FROM public.artisans a
  WHERE a.owner_user_id = v_uid
  LIMIT 1
  FOR UPDATE;

  IF v_existing_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'reason', 'already_registered',
      'artisan_id', v_existing_id
    );
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.users
    WHERE id = v_uid
  ) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'identity_broken',
      'message', 'Votre compte n''est pas entièrement configuré. Veuillez vous reconnecter.'
    );
  END IF;

  INSERT INTO public.artisans (
    owner_user_id,
    full_name,
    service_category,
    city,
    description,
    phone,
    claimed,
    claim_status,
    onboarding_completed,
    availability,
    verified,
    created_at,
    updated_at
  )
  VALUES (
    v_uid,
    v_full_name,
    v_service_cat,
    v_city,
    v_description,
    NULLIF(v_phone, ''),
    true,
    'approved',
    false,
    'unavailable',
    false,
    now(),
    now()
  )
  RETURNING id INTO v_artisan_id;

  UPDATE public.users
  SET
    role  = 'artisan',
    phone = CASE
      WHEN v_phone != '' THEN v_phone
      ELSE phone
    END
  WHERE id = v_uid
    AND role != 'admin';

  GET DIAGNOSTICS v_users_updated = ROW_COUNT;

  UPDATE public.profiles
  SET
    role  = 'artisan',
    phone = CASE
      WHEN v_phone != '' THEN v_phone
      ELSE phone
    END
  WHERE id = v_uid
    AND (role IS NULL OR role NOT IN ('admin'));

  GET DIAGNOSTICS v_prof_updated = ROW_COUNT;

  RETURN jsonb_build_object(
    'ok', true,
    'reason', 'registered',
    'artisan_id', v_artisan_id,
    'owner_uid', v_uid,
    'profiles_updated', v_prof_updated
  );

EXCEPTION
  WHEN unique_violation THEN

    SELECT a.id
    INTO v_existing_id
    FROM public.artisans a
    WHERE a.owner_user_id = v_uid
    LIMIT 1;

    RETURN jsonb_build_object(
      'ok', true,
      'reason', 'already_registered',
      'artisan_id', COALESCE(v_existing_id, v_artisan_id)
    );

  WHEN OTHERS THEN

    RAISE WARNING
      '[register_new_artisan] unexpected error for uid %: %',
      v_uid,
      SQLERRM;

    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'internal_error'
    );

END;
$function$

CREATE OR REPLACE FUNCTION public.reject_quote_v2(p_quote_id uuid)
 RETURNS quotes
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_uid uuid:=auth.uid(); v_quote public.quotes%rowtype; v_req public.service_requests%rowtype;
begin
 if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
 select * into v_quote from public.quotes where id=p_quote_id for update;
 if not found or v_quote.status<>'pending' then raise exception 'QUOTE_NOT_PENDING'; end if;
 select * into v_req from public.service_requests where id=v_quote.request_id;
 if not found or v_req.client_profile_id is distinct from v_uid then raise exception 'FORBIDDEN'; end if;
 update public.quotes set status='rejected' where id=p_quote_id returning * into v_quote;
 return v_quote;
end $function$

CREATE OR REPLACE FUNCTION public.remove_enterprise_equipment_asset_v1(p_enterprise_id uuid, p_asset_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_equipment_id uuid; v_path text;
BEGIN
  IF auth.uid() IS NULL THEN RETURN jsonb_build_object('ok',false,'reason','unauthenticated'); END IF;
  SELECT a.equipment_id,a.storage_path INTO v_equipment_id,v_path
  FROM public.enterprise_equipment_assets a
  WHERE a.id=p_asset_id AND a.enterprise_id=p_enterprise_id FOR UPDATE;
