$function$

CREATE OR REPLACE FUNCTION public.set_enterprise_internal_assignment_status_v1(p_enterprise_id uuid, p_request_id uuid, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_assignment_id uuid;
  v_worker_id uuid;
  v_old_status text;
  v_is_self boolean;
  v_is_operator boolean;
  v_request_status text;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','unauthenticated');
  END IF;

  IF p_status NOT IN ('in_progress','completed','validated') THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invalid_status');
  END IF;

  SELECT ia.id,ia.worker_id,ia.status,sr.status
  INTO v_assignment_id,v_worker_id,v_old_status,v_request_status
  FROM public.enterprise_internal_assignments ia
  JOIN public.service_requests sr ON sr.id=ia.service_request_id
  WHERE ia.enterprise_id=p_enterprise_id
    AND ia.service_request_id=p_request_id
  FOR UPDATE OF ia,sr;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','assignment_not_found');
  END IF;

  v_is_self := fixeo_private._fixeo_is_enterprise_workforce_self(v_worker_id);
  v_is_operator := fixeo_private._fixeo_is_enterprise_dispatch_operator(p_enterprise_id);

  IF NOT v_is_self AND NOT v_is_operator THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','forbidden');
  END IF;

  IF p_status='in_progress' AND v_old_status<>'assigned' THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invalid_transition');
  END IF;

  IF p_status='completed' AND v_old_status NOT IN ('assigned','in_progress') THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invalid_transition');
  END IF;

  IF p_status='validated' THEN
    IF NOT v_is_operator OR v_old_status<>'completed' THEN
      RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invalid_transition');
    END IF;
  END IF;

  UPDATE public.enterprise_internal_assignments
  SET status=p_status,
      started_at=CASE
        WHEN p_status='in_progress' THEN COALESCE(started_at,now())
        ELSE started_at
      END,
      completed_at=CASE
        WHEN p_status IN ('completed','validated') THEN COALESCE(completed_at,now())
        ELSE completed_at
      END,
      updated_at=now()
  WHERE id=v_assignment_id;

  UPDATE public.service_requests
  SET status=CASE
    WHEN p_status='in_progress' THEN 'in_progress'
    WHEN p_status='completed' THEN 'completed'
    WHEN p_status='validated' THEN 'validated'
    ELSE status
  END
  WHERE id=p_request_id;

  IF p_status='validated' THEN
    UPDATE public.enterprise_hybrid_dispatch_state
    SET status='completed',updated_at=now()
    WHERE service_request_id=p_request_id;
  END IF;

  PERFORM fixeo_private._write_enterprise_audit_event(
    p_enterprise_id,
    'dispatch.internal_assignment_updated',
    'enterprise_internal_assignment',
    v_assignment_id,
    pg_catalog.jsonb_build_object('status',v_old_status),
    pg_catalog.jsonb_build_object('status',p_status),
    pg_catalog.jsonb_build_object(
      'worker_id',v_worker_id,
      'service_request_id',p_request_id
    )
  );

  RETURN pg_catalog.jsonb_build_object(
    'ok',true,'assignment_id',v_assignment_id,'status',p_status
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.set_enterprise_member_status(p_enterprise_id uuid, p_member_id uuid, p_new_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_enterprise_status text;
  v_caller_id   uuid;
  v_caller_role text;
  v_caller_stat text;
  v_target_role text;
  v_target_stat text;
  v_owner_count integer;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','unauthenticated');
  END IF;

  IF p_new_status IS NULL
     OR p_new_status NOT IN ('active','suspended','removed')
  THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invalid_status');
  END IF;

  SELECT ea.status
  INTO v_enterprise_status
  FROM public.enterprise_accounts ea
  WHERE ea.id = p_enterprise_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','enterprise_not_found');
  END IF;

  IF v_enterprise_status <> 'active' THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','enterprise_not_active',
      'enterprise_status',v_enterprise_status);
  END IF;

  SELECT em.role, em.status
  INTO v_caller_role, v_caller_stat
  FROM public.enterprise_members em
  WHERE em.enterprise_id = p_enterprise_id
    AND em.user_id = v_caller_id;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','not_a_member');
  END IF;

  IF v_caller_stat != 'active' THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','caller_not_active');
  END IF;

  IF v_caller_role NOT IN ('owner','admin') THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','forbidden');
  END IF;

  SELECT em.role, em.status
  INTO v_target_role, v_target_stat
  FROM public.enterprise_members em
  WHERE em.id = p_member_id
    AND em.enterprise_id = p_enterprise_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','member_not_found');
  END IF;

  IF v_target_stat = 'removed' THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','member_already_removed');
  END IF;

  IF v_caller_role = 'admin' AND v_target_role = 'owner' THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','cannot_modify_owner');
  END IF;

  IF v_target_role = 'owner'
     AND v_target_stat = 'active'
     AND p_new_status IN ('suspended','removed')
  THEN
    SELECT COUNT(*)
    INTO v_owner_count
    FROM public.enterprise_members
    WHERE enterprise_id = p_enterprise_id
      AND role = 'owner'
      AND status = 'active'
      AND id != p_member_id;

    IF v_owner_count = 0 THEN
      RETURN pg_catalog.jsonb_build_object('ok',false,'reason','owner_invariant_violation');
    END IF;
  END IF;

  IF v_target_stat = 'active' AND p_new_status = 'active' THEN
    RETURN pg_catalog.jsonb_build_object('ok',true,'reason','no_change');
  END IF;

  IF v_target_stat = 'suspended' AND p_new_status = 'suspended' THEN
    RETURN pg_catalog.jsonb_build_object('ok',true,'reason','no_change');
  END IF;

  IF v_target_stat = 'invited' THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invited_status_not_managed_here');
  END IF;

  UPDATE public.enterprise_members
  SET status = p_new_status,
      updated_at = now()
  WHERE id = p_member_id;

  PERFORM fixeo_private._write_enterprise_audit_event(
    p_enterprise_id,
    'member.status_updated',
    'enterprise_member',
    p_member_id,
    pg_catalog.jsonb_build_object('status', v_target_stat),
    pg_catalog.jsonb_build_object('status', p_new_status),
    pg_catalog.jsonb_build_object('target_role', v_target_role)
  );

  RETURN pg_catalog.jsonb_build_object(
    'ok', true,
    'member_id', p_member_id,
    'new_status', p_new_status
  );

EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING '[set_enterprise_member_status] error: % (SQLSTATE: %)', SQLERRM, SQLSTATE;
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','internal_error');
END;
$function$

CREATE OR REPLACE FUNCTION public.set_enterprise_request_finance_context_v1(p_enterprise_id uuid, p_request_id uuid, p_cost_center_id uuid, p_purchase_order_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_site_id uuid; v_before jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RETURN jsonb_build_object('ok',false,'reason','unauthenticated'); END IF;
  IF NOT fixeo_private._fixeo_is_enterprise_dispatch_operator(p_enterprise_id) THEN RETURN jsonb_build_object('ok',false,'reason','forbidden'); END IF;
  SELECT erc.site_id INTO v_site_id FROM public.enterprise_request_context erc WHERE erc.enterprise_id=p_enterprise_id AND erc.service_request_id=p_request_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','request_not_found'); END IF;
  IF NOT fixeo_private._fixeo_can_access_enterprise_site(p_enterprise_id,v_site_id) THEN RETURN jsonb_build_object('ok',false,'reason','forbidden'); END IF;
  IF p_cost_center_id IS NOT NULL AND NOT EXISTS(
    SELECT 1 FROM public.enterprise_cost_centers c WHERE c.id=p_cost_center_id AND c.enterprise_id=p_enterprise_id AND c.status='active'
      AND (c.site_id IS NULL OR c.site_id=v_site_id)
  ) THEN RETURN jsonb_build_object('ok',false,'reason','cost_center_not_available'); END IF;
  IF p_purchase_order_id IS NOT NULL AND NOT EXISTS(
    SELECT 1 FROM public.enterprise_purchase_orders po WHERE po.id=p_purchase_order_id AND po.enterprise_id=p_enterprise_id AND po.status='open'
      AND (po.site_id IS NULL OR po.site_id=v_site_id)
  ) THEN RETURN jsonb_build_object('ok',false,'reason','po_not_available'); END IF;
  SELECT to_jsonb(x) INTO v_before FROM public.enterprise_request_finance_context x WHERE x.service_request_id=p_request_id;
  INSERT INTO public.enterprise_request_finance_context(service_request_id,enterprise_id,cost_center_id,purchase_order_id,updated_by,updated_at)
  VALUES(p_request_id,p_enterprise_id,p_cost_center_id,p_purchase_order_id,auth.uid(),now())
  ON CONFLICT(service_request_id) DO UPDATE SET cost_center_id=excluded.cost_center_id,purchase_order_id=excluded.purchase_order_id,updated_by=auth.uid(),updated_at=now();
  PERFORM fixeo_private._write_enterprise_audit_event(p_enterprise_id,'finance.request_context_updated','enterprise_request_finance_context',p_request_id,
    v_before,jsonb_build_object('cost_center_id',p_cost_center_id,'purchase_order_id',p_purchase_order_id,'site_id',v_site_id),'{}'::jsonb);
  RETURN jsonb_build_object('ok',true,'request_id',p_request_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.set_enterprise_site_status(p_enterprise_id uuid, p_site_id uuid, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_enterprise_status text;
  v_caller_id uuid;
  v_caller_role text;
  v_caller_stat text;
  v_site_eid uuid;
  v_site_status text;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'unauthenticated');
  END IF;

  IF p_status IS NULL OR p_status NOT IN ('active', 'inactive') THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'invalid_status');
  END IF;

  SELECT ea.status
  INTO v_enterprise_status
  FROM public.enterprise_accounts ea
  WHERE ea.id = p_enterprise_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','enterprise_not_found');
  END IF;

  IF v_enterprise_status <> 'active' THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','enterprise_not_active',
      'enterprise_status',v_enterprise_status);
  END IF;

  SELECT em.role, em.status
  INTO v_caller_role, v_caller_stat
  FROM public.enterprise_members em
  WHERE em.enterprise_id = p_enterprise_id
    AND em.user_id = v_caller_id;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'not_a_member');
  END IF;

  IF v_caller_stat != 'active' THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'caller_not_active');
  END IF;

  IF v_caller_role NOT IN ('owner', 'admin') THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'forbidden');
  END IF;

  SELECT es.enterprise_id, es.status
  INTO v_site_eid, v_site_status
  FROM public.enterprise_sites es
  WHERE es.id = p_site_id;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'site_not_found');
  END IF;

  IF v_site_eid <> p_enterprise_id THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'site_enterprise_mismatch');
  END IF;

  IF v_site_status = p_status THEN
    RETURN pg_catalog.jsonb_build_object('ok', true, 'reason', 'no_change');
  END IF;

  UPDATE public.enterprise_sites
  SET status = p_status
  WHERE id = p_site_id;

  PERFORM fixeo_private._write_enterprise_audit_event(
    p_enterprise_id,
    'site.status_updated',
    'enterprise_site',
    p_site_id,
    pg_catalog.jsonb_build_object('status', v_site_status),
    pg_catalog.jsonb_build_object('status', p_status),
    '{}'::jsonb
  );

  RETURN pg_catalog.jsonb_build_object(
    'ok', true,
    'site_id', p_site_id,
    'new_status', p_status
  );

EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING '[set_enterprise_site_status] error: % (SQLSTATE: %)', SQLERRM, SQLSTATE;
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'internal_error');
END;
$function$

CREATE OR REPLACE FUNCTION public.set_enterprise_worker_cost_rate_v1(p_enterprise_id uuid, p_worker_id uuid, p_hourly_cost numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN RETURN jsonb_build_object('ok',false,'reason','unauthenticated'); END IF;
  IF NOT fixeo_private._fixeo_is_enterprise_finance_manager(p_enterprise_id) THEN RETURN jsonb_build_object('ok',false,'reason','forbidden'); END IF;
  IF NOT EXISTS(SELECT 1 FROM public.enterprise_workforce_workers w WHERE w.id=p_worker_id AND w.enterprise_id=p_enterprise_id) THEN RETURN jsonb_build_object('ok',false,'reason','worker_not_found'); END IF;
  IF p_hourly_cost IS NULL OR p_hourly_cost<0 THEN RETURN jsonb_build_object('ok',false,'reason','invalid_amount'); END IF;
  INSERT INTO public.enterprise_worker_cost_rates(worker_id,enterprise_id,hourly_cost,updated_by,updated_at)
  VALUES(p_worker_id,p_enterprise_id,p_hourly_cost,auth.uid(),now())
  ON CONFLICT(worker_id) DO UPDATE SET hourly_cost=excluded.hourly_cost,updated_by=auth.uid(),updated_at=now();
  PERFORM fixeo_private._write_enterprise_audit_event(p_enterprise_id,'finance.worker_rate_updated','enterprise_workforce_worker',p_worker_id,NULL,
    jsonb_build_object('hourly_cost',p_hourly_cost),'{}'::jsonb);
  RETURN jsonb_build_object('ok',true,'worker_id',p_worker_id,'hourly_cost',p_hourly_cost);
END;
$function$

CREATE OR REPLACE FUNCTION public.set_enterprise_workforce_availability(p_enterprise_id uuid, p_worker_id uuid, p_availability text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_old text;
  v_is_self boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','unauthenticated');
  END IF;

  IF p_availability NOT IN ('available','unavailable','off_duty') THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invalid_availability');
  END IF;

  v_is_self := fixeo_private._fixeo_is_enterprise_workforce_self(p_worker_id);

  IF NOT fixeo_private._fixeo_is_enterprise_manager(p_enterprise_id)
     AND NOT v_is_self
  THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','forbidden');
  END IF;

  SELECT w.availability
  INTO v_old
  FROM public.enterprise_workforce_workers w
  WHERE w.id=p_worker_id AND w.enterprise_id=p_enterprise_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','worker_not_found');
  END IF;

  IF v_old = p_availability THEN
    RETURN pg_catalog.jsonb_build_object('ok',true,'reason','no_change','worker_id',p_worker_id);
  END IF;

  UPDATE public.enterprise_workforce_workers
  SET availability=p_availability,updated_at=now()
  WHERE id=p_worker_id;

  PERFORM fixeo_private._write_enterprise_audit_event(
    p_enterprise_id,
    'workforce.availability_updated',
    'enterprise_workforce_worker',
    p_worker_id,
    pg_catalog.jsonb_build_object('availability',v_old),
    pg_catalog.jsonb_build_object('availability',p_availability),
    '{}'::jsonb
  );

  RETURN pg_catalog.jsonb_build_object(
    'ok',true,'worker_id',p_worker_id,'availability',p_availability
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.start_mission(p_mission_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_artisan_id      uuid;
  v_request_id      text;
  v_mission_status  text;
  v_mission_artisan uuid;
  v_sr_status       text;
  v_rows_updated    integer;
BEGIN

  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'unauthenticated');
  END IF;

  SELECT a.id
  INTO   v_artisan_id
  FROM   public.artisans a
  WHERE  a.owner_user_id = auth.uid()
  LIMIT  1;

  IF v_artisan_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'artisan_not_found');
  END IF;

  SELECT m.request_id, m.status, m.artisan_profile_id
  INTO   v_request_id, v_mission_status, v_mission_artisan
  FROM   public.missions m
  WHERE  m.id = p_mission_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'mission_not_found');
  END IF;

  IF v_mission_artisan != v_artisan_id THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_your_mission');
  END IF;

  IF v_mission_status != 'pending' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_accepted');
  END IF;

  SELECT sr.status INTO v_sr_status
  FROM   public.service_requests sr
  WHERE  sr.id::text = v_request_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_request_state');
  END IF;

  IF v_sr_status = 'in_progress' THEN
    RETURN jsonb_build_object(
      'ok', true,
      'mission_id', p_mission_id,
      'already_started', true
    );
  END IF;

  IF v_sr_status != 'assigned' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_request_state');
  END IF;

  UPDATE public.service_requests
  SET    status = 'in_progress'
  WHERE  id::text = v_request_id
    AND  status   = 'assigned';

  GET DIAGNOSTICS v_rows_updated = ROW_COUNT;

  IF v_rows_updated = 0 THEN

    SELECT sr.status INTO v_sr_status
    FROM   public.service_requests sr
    WHERE  sr.id::text = v_request_id;

    IF v_sr_status = 'in_progress' THEN
      RETURN jsonb_build_object(
        'ok', true,
        'mission_id', p_mission_id,
        'already_started', true
      );
    END IF;

    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_request_state');
  END IF;

  RETURN jsonb_build_object(
    'ok',         true,
    'mission_id', p_mission_id
  );

EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING '[start_mission] unexpected error: %', SQLERRM;
    RETURN jsonb_build_object('ok', false, 'reason', 'internal_error');
END;

$function$

CREATE OR REPLACE FUNCTION public.submit_artisan_quote_v2(p_request_id uuid, p_proposed_price numeric, p_service_description text DEFAULT NULL::text, p_supplies_description text DEFAULT NULL::text, p_estimated_duration text DEFAULT NULL::text, p_message text DEFAULT NULL::text)
 RETURNS quotes
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_artisan public.artisans%rowtype;
  v_req public.service_requests%rowtype;
  v_quote public.quotes%rowtype;
begin
  if v_uid is null then raise exception 'AUTH_REQUIRED'; end if;
  if p_proposed_price is null or p_proposed_price <= 0 then raise exception 'INVALID_PRICE'; end if;
  if length(coalesce(trim(p_service_description),'')) < 5 then raise exception 'SERVICE_DESCRIPTION_REQUIRED'; end if;

  select * into v_artisan from public.artisans
   where owner_user_id=v_uid order by updated_at desc nulls last limit 1;
  if not found then raise exception 'ARTISAN_NOT_FOUND'; end if;

  select * into v_req from public.service_requests where id=p_request_id for update;
  if not found then raise exception 'REQUEST_NOT_FOUND'; end if;
  if v_req.status <> 'new' then raise exception 'REQUEST_NOT_QUOTABLE'; end if;
  if lower(trim(coalesce(v_req.city,''))) <> lower(trim(coalesce(v_artisan.city,''))) then raise exception 'CITY_MISMATCH'; end if;
  if lower(trim(coalesce(v_req.service_category,''))) not in (
      lower(trim(coalesce(v_artisan.service_category,''))),
      lower(trim(coalesce(v_artisan.category,'')))
    )
    and not coalesce(v_artisan.services,'[]'::jsonb) ? v_req.service_category
  then raise exception 'TRADE_MISMATCH'; end if;

  select * into v_quote from public.quotes
   where request_id=p_request_id and artisan_profile_id=v_artisan.id and status in ('pending','accepted')
   order by created_at desc limit 1 for update;

  if found then
    if v_quote.status='accepted' then raise exception 'QUOTE_ALREADY_ACCEPTED'; end if;
    update public.quotes set
      proposed_price=p_proposed_price,
      service_description=nullif(trim(p_service_description),''),
      supplies_description=nullif(trim(p_supplies_description),''),
      estimated_duration=nullif(trim(p_estimated_duration),''),
      message=nullif(trim(p_message),''),
      submitted_at=now()
    where id=v_quote.id returning * into v_quote;
  else
    insert into public.quotes(request_id,artisan_profile_id,proposed_price,message,status,
      service_description,supplies_description,estimated_duration,submitted_at)
    values(p_request_id,v_artisan.id,p_proposed_price,nullif(trim(p_message),''),'pending',
      nullif(trim(p_service_description),''),nullif(trim(p_supplies_description),''),
      nullif(trim(p_estimated_duration),''),now())
    returning * into v_quote;
  end if;

  if v_req.client_profile_id is not null then
    insert into public.notifications(recipient_user_id,recipient_role,type,title,message,related_entity_type,related_entity_id,metadata)
    values(v_req.client_profile_id,'client','quote_received','Nouveau devis FIXEO',
      'Un artisan a transmis un devis pour votre demande.','quote',v_quote.id::text,
      jsonb_build_object('quote_id',v_quote.id,'request_id',v_req.id));
  end if;
  return v_quote;
end $function$

CREATE OR REPLACE FUNCTION public.submit_enterprise_governed_request_v1(p_enterprise_id uuid, p_site_id uuid, p_service_category text, p_description text, p_urgency text DEFAULT NULL::text, p_requested_amount numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_member_id uuid; v_role text; v_policy_id uuid; v_total_steps integer; v_case_id uuid; v_created jsonb;
  v_category text:=lower(btrim(p_service_category));
BEGIN
  IF auth.uid() IS NULL THEN RETURN jsonb_build_object('ok',false,'reason','unauthenticated'); END IF;
  SELECT em.id,em.role INTO v_member_id,v_role
  FROM public.enterprise_members em
  WHERE em.enterprise_id=p_enterprise_id AND em.user_id=auth.uid() AND em.status='active'
    AND em.role IN ('owner','admin','operations_manager','site_manager','reporter');
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','forbidden'); END IF;
  IF NOT EXISTS(SELECT 1 FROM public.enterprise_sites s WHERE s.id=p_site_id AND s.enterprise_id=p_enterprise_id AND s.status='active') THEN RETURN jsonb_build_object('ok',false,'reason','site_not_available'); END IF;
  IF NOT fixeo_private._fixeo_can_access_enterprise_site(p_enterprise_id,p_site_id) THEN RETURN jsonb_build_object('ok',false,'reason','site_forbidden'); END IF;
  IF v_category IS NULL OR char_length(v_category)<1 OR btrim(p_description) IS NULL OR char_length(btrim(p_description))<1 THEN RETURN jsonb_build_object('ok',false,'reason','invalid_input'); END IF;
  IF p_urgency IS NOT NULL AND p_urgency NOT IN ('normale','urgent','now') THEN RETURN jsonb_build_object('ok',false,'reason','urgency_invalid'); END IF;
  IF p_requested_amount IS NOT NULL AND p_requested_amount<0 THEN RETURN jsonb_build_object('ok',false,'reason','invalid_amount'); END IF;

  SELECT p.id INTO v_policy_id
  FROM public.enterprise_approval_policies p
  WHERE p.enterprise_id=p_enterprise_id AND p.status='active'
    AND (p.site_id=p_site_id OR p.site_id IS NULL)
    AND (p.service_category IS NULL OR lower(btrim(p.service_category))=v_category)
    AND (p.urgency IS NULL OR p.urgency IS NOT DISTINCT FROM p_urgency)
    AND (p.requester_role IS NULL OR p.requester_role=v_role)
    AND (p.min_amount IS NULL OR (p_requested_amount IS NOT NULL AND p_requested_amount>=p.min_amount))
    AND (p.max_amount IS NULL OR (p_requested_amount IS NOT NULL AND p_requested_amount<=p.max_amount))
  ORDER BY
    CASE WHEN p.site_id=p_site_id THEN 0 ELSE 1 END,
    CASE WHEN p.service_category IS NOT NULL THEN 0 ELSE 1 END,
    CASE WHEN p.urgency IS NOT NULL THEN 0 ELSE 1 END,
    CASE WHEN p.requester_role IS NOT NULL THEN 0 ELSE 1 END,
    CASE WHEN p.min_amount IS NOT NULL OR p.max_amount IS NOT NULL THEN 0 ELSE 1 END,
    p.priority ASC,p.created_at ASC
  LIMIT 1 FOR SHARE;

  IF v_policy_id IS NULL THEN
    v_created:=public.create_enterprise_request_hybrid(p_enterprise_id,p_site_id,v_category,btrim(p_description),p_urgency);
    RETURN v_created || jsonb_build_object('governance_status','not_required');
  END IF;

  SELECT count(*)::integer INTO v_total_steps
  FROM public.enterprise_approval_policy_steps s WHERE s.policy_id=v_policy_id;
  IF v_total_steps<1 THEN RETURN jsonb_build_object('ok',false,'reason','policy_has_no_steps'); END IF;

  INSERT INTO public.enterprise_approval_cases(
    enterprise_id,site_id,policy_id,requested_by,requester_role,service_category,description,urgency,
    requested_amount,current_step,total_steps,status
  ) VALUES(
    p_enterprise_id,p_site_id,v_policy_id,auth.uid(),v_role,v_category,btrim(p_description),p_urgency,
    p_requested_amount,1,v_total_steps,'pending'
  ) RETURNING id INTO v_case_id;

  PERFORM fixeo_private._write_enterprise_audit_event(
    p_enterprise_id,'governance.case_created','enterprise_approval_case',v_case_id,NULL,
    jsonb_build_object('site_id',p_site_id,'policy_id',v_policy_id,'requester_role',v_role,'service_category',v_category,
      'urgency',p_urgency,'requested_amount',p_requested_amount,'total_steps',v_total_steps),'{}'::jsonb
  );

  RETURN jsonb_build_object('ok',true,'governance_status','pending_approval','approval_case_id',v_case_id,'policy_id',v_policy_id,'current_step',1,'total_steps',v_total_steps);
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_my_account_email_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_email text;
begin
  if v_uid is null then
    return jsonb_build_object('ok',false,'reason','unauthenticated');
  end if;

  if not exists (
    select 1 from public.artisans a
    where a.owner_user_id = v_uid
  ) then
    return jsonb_build_object('ok',false,'reason','artisan_not_found');
  end if;

  select lower(trim(u.email))
  into v_email
  from auth.users u
  where u.id = v_uid;

  if coalesce(v_email,'') = '' then
    return jsonb_build_object('ok',false,'reason','email_missing');
  end if;

  update public.users
  set email = v_email
  where id = v_uid;

  update public.profiles
  set email = v_email
  where id = v_uid;

  return jsonb_build_object('ok',true,'email',v_email);
end
$function$

CREATE OR REPLACE FUNCTION public.transfer_enterprise_ownership(p_enterprise_id uuid, p_target_member_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_caller_id uuid;
  v_enterprise_status text;

  v_current_owner_member_id uuid;
  v_current_owner_role text;
  v_current_owner_status text;

  v_target_user_id uuid;
  v_target_role text;
  v_target_status text;
BEGIN
  -- Authentication.
  v_caller_id := auth.uid();

  IF v_caller_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',false,
      'reason','unauthenticated'
    );
  END IF;

  IF p_enterprise_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',false,
      'reason','enterprise_required'
    );
  END IF;

  IF p_target_member_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',false,
      'reason','target_member_required'
    );
  END IF;

  -- LOCK #1: enterprise account.
  SELECT ea.status
  INTO v_enterprise_status
  FROM public.enterprise_accounts ea
  WHERE ea.id=p_enterprise_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',false,
      'reason','enterprise_not_found'
    );
  END IF;

  IF v_enterprise_status <> 'active' THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',false,
      'reason','enterprise_not_active',
      'enterprise_status',v_enterprise_status
    );
  END IF;

  -- LOCK #2: caller membership.
  -- Only the active owner may initiate the ownership transfer.
  SELECT em.id, em.role, em.status
  INTO
    v_current_owner_member_id,
    v_current_owner_role,
    v_current_owner_status
  FROM public.enterprise_members em
  WHERE em.enterprise_id=p_enterprise_id
    AND em.user_id=v_caller_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',false,
      'reason','not_a_member'
    );
  END IF;

  IF v_current_owner_status <> 'active' THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',false,
      'reason','caller_not_active'
    );
  END IF;

  IF v_current_owner_role <> 'owner' THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',false,
      'reason','owner_required'
    );
  END IF;

  IF p_target_member_id=v_current_owner_member_id THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',false,
      'reason','cannot_transfer_to_self'
    );
  END IF;

  -- LOCK #3: target membership.
  SELECT em.user_id, em.role, em.status
  INTO v_target_user_id, v_target_role, v_target_status
  FROM public.enterprise_members em
  WHERE em.enterprise_id=p_enterprise_id
    AND em.id=p_target_member_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',false,
      'reason','target_member_not_found'
    );
  END IF;

  IF v_target_status <> 'active' THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',false,
      'reason','target_member_not_active',
      'target_status',v_target_status
    );
  END IF;

  -- A transfer is specifically from the current owner to a non-owner member.
  IF v_target_role='owner' THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',false,
      'reason','target_already_owner'
    );
  END IF;

  -- Promote target first. This ensures that when the existing owner is
  -- demoted, the existing BEFORE UPDATE invariant trigger can observe another
  -- active owner and permit the demotion.
  UPDATE public.enterprise_members
  SET role='owner',
      updated_at=pg_catalog.now()
  WHERE id=p_target_member_id
    AND enterprise_id=p_enterprise_id;

  -- Agreed transfer semantics: previous owner becomes admin.
  UPDATE public.enterprise_members
  SET role='admin',
      updated_at=pg_catalog.now()
  WHERE id=v_current_owner_member_id
    AND enterprise_id=p_enterprise_id;

  -- One atomic audit event describes both sides of the ownership transition.
  PERFORM fixeo_private._write_enterprise_audit_event(
    p_enterprise_id,
    'account.ownership_transferred',
    'enterprise_account',
    p_enterprise_id,
    pg_catalog.jsonb_build_object(
      'owner_member_id',v_current_owner_member_id,
      'owner_user_id',v_caller_id,
      'target_member_role',v_target_role
    ),
    pg_catalog.jsonb_build_object(
      'owner_member_id',p_target_member_id,
      'owner_user_id',v_target_user_id,
      'previous_owner_member_id',v_current_owner_member_id,
      'previous_owner_role','admin'
    ),
    pg_catalog.jsonb_build_object(
      'source','transfer_enterprise_ownership',
      'previous_owner_user_id',v_caller_id,
      'new_owner_user_id',v_target_user_id
    )
  );

  RETURN pg_catalog.jsonb_build_object(
    'ok',true,
    'enterprise_id',p_enterprise_id,
    'previous_owner_member_id',v_current_owner_member_id,
    'previous_owner_user_id',v_caller_id,
    'previous_owner_role','admin',
    'owner_member_id',p_target_member_id,
    'owner_user_id',v_target_user_id
  );

EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING
      '[transfer_enterprise_ownership] error: % (SQLSTATE: %)',
      SQLERRM,SQLSTATE;

    RETURN pg_catalog.jsonb_build_object(
      'ok',false,
      'reason','internal_error'
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.unassign_enterprise_member_site(p_enterprise_id uuid, p_member_id uuid, p_site_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_caller_id uuid := auth.uid();
  v_caller_role text;
  v_caller_status text;
  v_assignment_id uuid;
BEGIN
  IF v_caller_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','unauthenticated');
  END IF;

  IF p_enterprise_id IS NULL OR p_member_id IS NULL OR p_site_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invalid_arguments');
  END IF;

  IF NOT fixeo_private._fixeo_is_admin() THEN
    SELECT em.role,em.status
    INTO v_caller_role,v_caller_status
    FROM public.enterprise_members em
    WHERE em.enterprise_id=p_enterprise_id
      AND em.user_id=v_caller_id;

    IF NOT FOUND
       OR v_caller_status <> 'active'
       OR v_caller_role NOT IN ('owner','admin')
    THEN
      RETURN pg_catalog.jsonb_build_object('ok',false,'reason','forbidden');
    END IF;
  END IF;

  SELECT ems.id
  INTO v_assignment_id
  FROM public.enterprise_member_sites ems
  WHERE ems.enterprise_id=p_enterprise_id
    AND ems.member_id=p_member_id
    AND ems.site_id=p_site_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok',true,'reason','not_assigned');
  END IF;

  DELETE FROM public.enterprise_member_sites
  WHERE id=v_assignment_id;

  PERFORM fixeo_private._write_enterprise_audit_event(
    p_enterprise_id,
    'member.site_unassigned',
    'enterprise_member_site',
    v_assignment_id,
    pg_catalog.jsonb_build_object(
      'assignment_id',v_assignment_id,
      'member_id',p_member_id,
      'site_id',p_site_id
    ),
    NULL,
    pg_catalog.jsonb_build_object(
      'member_id',p_member_id,
      'site_id',p_site_id
    )
  );

  RETURN pg_catalog.jsonb_build_object(
    'ok',true,
    'assignment_id',v_assignment_id,
    'enterprise_id',p_enterprise_id,
    'member_id',p_member_id,
    'site_id',p_site_id
  );

EXCEPTION WHEN OTHERS THEN
  RAISE WARNING '[unassign_enterprise_member_site] error: % (SQLSTATE: %)',
    SQLERRM,SQLSTATE;
  RETURN pg_catalog.jsonb_build_object('ok',false,'reason','internal_error');
END;
$function$

CREATE OR REPLACE FUNCTION public.update_artisan_availability(p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_uid               uuid;
  v_artisan_id        uuid;
  v_current_avail     text;
  v_onboarding_done   boolean;
  v_target_status     text;
BEGIN

  -- ── Auth ──────────────────────────────────────────────────
  v_uid := auth.uid();
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'unauthenticated');
  END IF;

  -- ── Validate requested status ─────────────────────────────
  v_target_status := lower(trim(COALESCE(p_status, '')));
  IF v_target_status NOT IN ('available', 'unavailable', 'busy') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_status',
      'message', 'Statut invalide. Valeurs acceptées: available, unavailable, busy.');
  END IF;

  -- ── Fetch and lock artisan row ────────────────────────────
  SELECT a.id, a.availability, a.onboarding_completed
  INTO v_artisan_id, v_current_avail, v_onboarding_done
  FROM public.artisans a
  WHERE a.owner_user_id = v_uid
  LIMIT 1
  FOR UPDATE;

  IF v_artisan_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_owner',
      'message', 'Aucun profil artisan trouvé pour ce compte.');
  END IF;

  -- ── Onboarding gate ───────────────────────────────────────
  -- 'available' and 'busy' require onboarding_completed = true.
  -- 'unavailable' is always permitted (artisan can always go offline).
  IF v_target_status IN ('available', 'busy') AND NOT COALESCE(v_onboarding_done, false) THEN
    RETURN jsonb_build_object(
      'ok',     false,
      'reason', 'onboarding_required',
      'message', 'Complétez votre profil avant de vous rendre disponible.'
    );
  END IF;

  -- ── Idempotency ───────────────────────────────────────────
  IF v_current_avail = v_target_status THEN
    RETURN jsonb_build_object(
      'ok',         true,
      'reason',     'no_change',
      'artisan_id', v_artisan_id,
      'status',     v_target_status
    );
  END IF;

  -- ── Update availability ───────────────────────────────────
  UPDATE public.artisans
  SET availability = v_target_status,
      updated_at   = now()
  WHERE id = v_artisan_id;

  RETURN jsonb_build_object(
    'ok',         true,
    'reason',     'updated',
    'artisan_id', v_artisan_id,
    'status',     v_target_status
  );

EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING '[update_artisan_availability] unexpected error for uid %: %', v_uid, SQLERRM;
    RETURN jsonb_build_object('ok', false, 'reason', 'internal_error');
END;
$function$

CREATE OR REPLACE FUNCTION public.update_enterprise_account(p_enterprise_id uuid, p_name text, p_legal_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_caller_id       uuid;
  v_authorized      boolean;
  v_current_name    text;
  v_current_legal   text;
  v_current_status  text;
  v_name            text;
  v_legal_name      text;
BEGIN
  -- Guard 1: authenticated caller.
  v_caller_id := auth.uid();

  IF v_caller_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'unauthenticated'
    );
  END IF;

  -- Guard 2: enterprise id required.
  IF p_enterprise_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'enterprise_required'
    );
  END IF;

  -- Guard 3: lock account and capture current state.
  SELECT
    ea.name,
    ea.legal_name,
    ea.status
  INTO
    v_current_name,
    v_current_legal,
    v_current_status
  FROM public.enterprise_accounts ea
  WHERE ea.id = p_enterprise_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'enterprise_not_found'
    );
  END IF;

  IF v_current_status <> 'active' THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'enterprise_not_active',
      'enterprise_status', v_current_status
    );
  END IF;

  -- Guard 4: active owner/admin authorization.
  SELECT fixeo_private._fixeo_is_enterprise_manager(
    p_enterprise_id
  )
  INTO v_authorized;

  IF NOT COALESCE(v_authorized, false) THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'forbidden'
    );
  END IF;

  -- Guard 5: validate and normalize name.
  IF p_name IS NULL
     OR pg_catalog.char_length(pg_catalog.btrim(p_name)) < 1
  THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'name_required'
    );
  END IF;

  v_name := pg_catalog.btrim(p_name);

  IF pg_catalog.char_length(v_name) > 200 THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'name_too_long'
    );
  END IF;

  -- Guard 6: legal_name may be NULL to clear it.
  IF p_legal_name IS NOT NULL THEN
    v_legal_name := pg_catalog.btrim(p_legal_name);

    IF pg_catalog.char_length(v_legal_name) < 1
       OR pg_catalog.char_length(v_legal_name) > 300
    THEN
      RETURN pg_catalog.jsonb_build_object(
        'ok', false,
        'reason', 'legal_name_invalid'
      );
    END IF;
  ELSE
    v_legal_name := NULL;
  END IF;

  -- Guard 7: semantic no-op.
  IF v_name IS NOT DISTINCT FROM v_current_name
     AND v_legal_name IS NOT DISTINCT FROM v_current_legal
  THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', true,
      'reason', 'no_change'
    );
  END IF;

  -- Mutation. Status is intentionally untouched.
  UPDATE public.enterprise_accounts
  SET
    name = v_name,
    legal_name = v_legal_name
  WHERE id = p_enterprise_id;

  -- Transactional audit.
  PERFORM fixeo_private._write_enterprise_audit_event(
    p_enterprise_id,
    'account.updated',
    'enterprise_account',
    p_enterprise_id,
    pg_catalog.jsonb_build_object(
      'name', v_current_name,
      'legal_name', v_current_legal,
      'status', v_current_status
    ),
    pg_catalog.jsonb_build_object(
      'name', v_name,
      'legal_name', v_legal_name,
      'status', v_current_status
    ),
    '{}'::jsonb
  );

  RETURN pg_catalog.jsonb_build_object(
    'ok', true,
    'enterprise_id', p_enterprise_id
  );

EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING
      '[update_enterprise_account] unexpected error: % (SQLSTATE: %)',
      SQLERRM,
      SQLSTATE;

    RETURN pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'internal_error'
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.update_enterprise_member_role(p_enterprise_id uuid, p_member_id uuid, p_new_role text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_enterprise_status text;
  v_caller_id   uuid;
  v_caller_role text;
  v_caller_stat text;
  v_target_role text;
  v_target_stat text;
  v_target_uid  uuid;
  v_owner_count integer;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','unauthenticated');
  END IF;

  IF p_new_role IS NULL
     OR p_new_role NOT IN ('admin','operations_manager','site_manager','reporter','viewer')
  THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invalid_role');
  END IF;

  SELECT ea.status
  INTO v_enterprise_status
  FROM public.enterprise_accounts ea
  WHERE ea.id = p_enterprise_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','enterprise_not_found');
  END IF;

  IF v_enterprise_status <> 'active' THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','enterprise_not_active',
      'enterprise_status',v_enterprise_status);
  END IF;

  SELECT em.role, em.status
  INTO v_caller_role, v_caller_stat
  FROM public.enterprise_members em
  WHERE em.enterprise_id = p_enterprise_id
    AND em.user_id = v_caller_id;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','not_a_member');
  END IF;

  IF v_caller_stat != 'active' THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','caller_not_active');
  END IF;

  IF v_caller_role NOT IN ('owner','admin') THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','forbidden');
  END IF;

  SELECT em.role, em.status, em.user_id
  INTO v_target_role, v_target_stat, v_target_uid
  FROM public.enterprise_members em
  WHERE em.id = p_member_id
    AND em.enterprise_id = p_enterprise_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','member_not_found');
  END IF;

  IF v_target_stat NOT IN ('active','suspended') THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','member_not_modifiable');
  END IF;

  IF v_caller_role = 'admin' AND v_target_role = 'owner' THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','cannot_modify_owner');
  END IF;

  IF v_target_role = 'owner' AND v_target_stat = 'active' THEN
    SELECT COUNT(*)
    INTO v_owner_count
    FROM public.enterprise_members
    WHERE enterprise_id = p_enterprise_id
      AND role = 'owner'
      AND status = 'active'
      AND id != p_member_id;

    IF v_owner_count = 0 THEN
      RETURN pg_catalog.jsonb_build_object('ok',false,'reason','owner_invariant_violation');
    END IF;
  END IF;

  IF v_target_role = p_new_role THEN
    RETURN pg_catalog.jsonb_build_object('ok',true,'reason','no_change');
  END IF;

  UPDATE public.enterprise_members
  SET role = p_new_role,
      updated_at = now()
  WHERE id = p_member_id;

  PERFORM fixeo_private._write_enterprise_audit_event(
    p_enterprise_id,
    'member.role_updated',
    'enterprise_member',
    p_member_id,
    pg_catalog.jsonb_build_object('role', v_target_role),
    pg_catalog.jsonb_build_object('role', p_new_role),
    pg_catalog.jsonb_build_object(
      'target_user_id', v_target_uid,
      'target_status', v_target_stat
    )
  );

  RETURN pg_catalog.jsonb_build_object(
    'ok', true,
    'member_id', p_member_id,
    'new_role', p_new_role
  );

EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING '[update_enterprise_member_role] error: % (SQLSTATE: %)', SQLERRM, SQLSTATE;
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','internal_error');
END;
$function$

CREATE OR REPLACE FUNCTION public.update_enterprise_site(p_enterprise_id uuid, p_site_id uuid, p_name text, p_city text, p_site_code text DEFAULT NULL::text, p_address_line text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_enterprise_status text;
  v_caller_id uuid;
  v_caller_role text;
  v_caller_stat text;
  v_site_eid uuid;
  v_site_name text;
  v_site_city text;
  v_site_code_cur text;
  v_site_addr_cur text;
  v_name text;
  v_city text;
  v_site_code text;
  v_address_line text;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'unauthenticated');
  END IF;

  SELECT ea.status
  INTO v_enterprise_status
  FROM public.enterprise_accounts ea
  WHERE ea.id = p_enterprise_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','enterprise_not_found');
  END IF;

  IF v_enterprise_status <> 'active' THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','enterprise_not_active',
      'enterprise_status',v_enterprise_status);
  END IF;

  SELECT em.role, em.status
  INTO v_caller_role, v_caller_stat
  FROM public.enterprise_members em
  WHERE em.enterprise_id = p_enterprise_id
    AND em.user_id = v_caller_id;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'not_a_member');
  END IF;

  IF v_caller_stat != 'active' THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'caller_not_active');
  END IF;

  IF v_caller_role NOT IN ('owner', 'admin') THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'forbidden');
  END IF;

  SELECT es.enterprise_id, es.name, es.city, es.site_code, es.address_line
  INTO v_site_eid, v_site_name, v_site_city, v_site_code_cur, v_site_addr_cur
  FROM public.enterprise_sites es
  WHERE es.id = p_site_id;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'site_not_found');
  END IF;

  IF v_site_eid <> p_enterprise_id THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'site_enterprise_mismatch');
  END IF;

  IF p_name IS NULL OR pg_catalog.char_length(pg_catalog.btrim(p_name)) < 1 THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'name_required');
  END IF;

  v_name := pg_catalog.btrim(p_name);
  IF pg_catalog.char_length(v_name) > 200 THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'name_too_long');
  END IF;

  IF p_city IS NULL OR pg_catalog.char_length(pg_catalog.btrim(p_city)) < 1 THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'city_required');
  END IF;

  v_city := pg_catalog.btrim(p_city);
  IF pg_catalog.char_length(v_city) > 120 THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'city_too_long');
  END IF;

  IF p_site_code IS NOT NULL THEN
    v_site_code := pg_catalog.btrim(p_site_code);
    IF pg_catalog.char_length(v_site_code) > 80 THEN
      RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'site_code_invalid');
    END IF;
    IF pg_catalog.char_length(v_site_code) = 0 THEN
      v_site_code := NULL;
    END IF;
  ELSE
    v_site_code := NULL;
  END IF;

  IF p_address_line IS NOT NULL THEN
    v_address_line := pg_catalog.btrim(p_address_line);
    IF pg_catalog.char_length(v_address_line) > 500 THEN
      RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'address_invalid');
    END IF;
    IF pg_catalog.char_length(v_address_line) = 0 THEN
      v_address_line := NULL;
    END IF;
  ELSE
    v_address_line := NULL;
  END IF;

  IF v_name IS NOT DISTINCT FROM v_site_name
     AND v_city IS NOT DISTINCT FROM v_site_city
     AND v_site_code IS NOT DISTINCT FROM v_site_code_cur
     AND v_address_line IS NOT DISTINCT FROM v_site_addr_cur
  THEN
    RETURN pg_catalog.jsonb_build_object('ok', true, 'reason', 'no_change');
  END IF;

  UPDATE public.enterprise_sites
  SET name = v_name,
      city = v_city,
      site_code = v_site_code,
      address_line = v_address_line
  WHERE id = p_site_id;

  PERFORM fixeo_private._write_enterprise_audit_event(
    p_enterprise_id,
    'site.updated',
    'enterprise_site',
    p_site_id,
    pg_catalog.jsonb_build_object(
      'name', v_site_name,
      'city', v_site_city,
      'site_code', v_site_code_cur,
      'address_line', v_site_addr_cur
    ),
    pg_catalog.jsonb_build_object(
      'name', v_name,
      'city', v_city,
      'site_code', v_site_code,
      'address_line', v_address_line
    ),
    '{}'::jsonb
  );

  RETURN pg_catalog.jsonb_build_object(
    'ok', true,
    'site_id', p_site_id,
    'enterprise_id', p_enterprise_id
  );

EXCEPTION
  WHEN unique_violation THEN
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'site_code_exists');

  WHEN OTHERS THEN
    RAISE WARNING '[update_enterprise_site] error: % (SQLSTATE: %)', SQLERRM, SQLSTATE;
    RETURN pg_catalog.jsonb_build_object('ok', false, 'reason', 'internal_error');
END;
$function$

CREATE OR REPLACE FUNCTION public.update_enterprise_sla_policy(p_enterprise_id uuid, p_policy_id uuid, p_site_id uuid, p_urgency text, p_acceptance_target_minutes integer, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_caller_id uuid := auth.uid();
  v_enterprise_status text;
  v_site_enterprise uuid;
  v_old_site_id uuid;
  v_old_urgency text;
  v_old_target integer;
  v_old_status text;
  v_target_type text;
  v_target_id uuid;
BEGIN
  IF v_caller_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','unauthenticated');
  END IF;

  IF p_enterprise_id IS NULL OR p_policy_id IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invalid_arguments');
  END IF;

  IF p_acceptance_target_minutes IS NULL OR p_acceptance_target_minutes <= 0 THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invalid_target');
  END IF;

  IF p_status IS NULL OR p_status NOT IN ('active','inactive') THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invalid_status');
  END IF;

  IF p_urgency IS NOT NULL
     AND p_urgency NOT IN ('urgent','high','normal','low')
  THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invalid_urgency');
  END IF;

  SELECT ea.status
  INTO v_enterprise_status
  FROM public.enterprise_accounts ea
  WHERE ea.id = p_enterprise_id
  FOR SHARE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','enterprise_not_found');
  END IF;

  IF v_enterprise_status <> 'active' THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',false,'reason','enterprise_not_active',
      'enterprise_status',v_enterprise_status
    );
  END IF;

  IF NOT fixeo_private._fixeo_is_enterprise_manager(p_enterprise_id) THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','forbidden');
  END IF;

  SELECT
    p.site_id,
    p.urgency,
    p.acceptance_target_minutes,
    p.status
  INTO
    v_old_site_id,
    v_old_urgency,
    v_old_target,
    v_old_status
  FROM public.enterprise_sla_policies p
  WHERE p.id = p_policy_id
    AND p.enterprise_id = p_enterprise_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','policy_not_found');
  END IF;

  IF p_site_id IS NOT NULL THEN
    SELECT es.enterprise_id
    INTO v_site_enterprise
    FROM public.enterprise_sites es
    WHERE es.id = p_site_id
    FOR SHARE;

    IF NOT FOUND THEN
      RETURN pg_catalog.jsonb_build_object('ok',false,'reason','site_not_found');
    END IF;

    IF v_site_enterprise <> p_enterprise_id THEN
      RETURN pg_catalog.jsonb_build_object('ok',false,'reason','site_enterprise_mismatch');
    END IF;
  END IF;

  IF v_old_site_id IS NOT DISTINCT FROM p_site_id
     AND v_old_urgency IS NOT DISTINCT FROM p_urgency
     AND v_old_target = p_acceptance_target_minutes
     AND v_old_status = p_status
  THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok',true,'reason','no_change','policy_id',p_policy_id
    );
  END IF;

  UPDATE public.enterprise_sla_policies
  SET site_id = p_site_id,
      urgency = p_urgency,
      acceptance_target_minutes = p_acceptance_target_minutes,
      status = p_status
  WHERE id = p_policy_id
    AND enterprise_id = p_enterprise_id;

  v_target_type := CASE WHEN p_site_id IS NULL THEN 'enterprise_account' ELSE 'enterprise_site' END;
  v_target_id := COALESCE(p_site_id,p_enterprise_id);

  PERFORM fixeo_private._write_enterprise_audit_event(
    p_enterprise_id,
    'sla.policy_updated',
    v_target_type,
    v_target_id,
    pg_catalog.jsonb_build_object(
      'site_id',v_old_site_id,
      'urgency',v_old_urgency,
      'acceptance_target_minutes',v_old_target,
      'status',v_old_status
    ),
    pg_catalog.jsonb_build_object(
      'site_id',p_site_id,
      'urgency',p_urgency,
      'acceptance_target_minutes',p_acceptance_target_minutes,
      'status',p_status
    ),
    pg_catalog.jsonb_build_object('policy_id',p_policy_id)
  );

  RETURN pg_catalog.jsonb_build_object(
    'ok',true,
    'policy_id',p_policy_id,
    'enterprise_id',p_enterprise_id,
    'site_id',p_site_id,
    'urgency',p_urgency,
    'acceptance_target_minutes',p_acceptance_target_minutes,
    'status',p_status
  );

EXCEPTION
  WHEN unique_violation THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','policy_exists');
  WHEN OTHERS THEN
    RAISE WARNING '[update_enterprise_sla_policy] error: % (SQLSTATE: %)', SQLERRM, SQLSTATE;
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','internal_error');
END;
$function$

CREATE OR REPLACE FUNCTION public.update_enterprise_workforce_worker(p_enterprise_id uuid, p_worker_id uuid, p_display_label text, p_employee_code text, p_status text, p_all_sites boolean, p_max_concurrent_jobs integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_label text;
  v_code text;
  v_before jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','unauthenticated');
  END IF;

  IF NOT fixeo_private._fixeo_is_enterprise_manager(p_enterprise_id) THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','forbidden');
  END IF;

  v_label := pg_catalog.btrim(p_display_label);
  v_code := NULLIF(pg_catalog.btrim(p_employee_code), '');

  IF v_label IS NULL OR pg_catalog.char_length(v_label) NOT BETWEEN 1 AND 160 THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invalid_label');
  END IF;
  IF v_code IS NOT NULL AND pg_catalog.char_length(v_code) NOT BETWEEN 1 AND 80 THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invalid_employee_code');
  END IF;
  IF p_status NOT IN ('active','inactive') THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invalid_status');
  END IF;
  IF p_max_concurrent_jobs IS NULL OR p_max_concurrent_jobs NOT BETWEEN 1 AND 20 THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','invalid_capacity');
  END IF;

  SELECT pg_catalog.jsonb_build_object(
    'status',w.status,
    'availability',w.availability,
    'all_sites',w.all_sites,
    'max_concurrent_jobs',w.max_concurrent_jobs,
    'display_label',w.display_label,
    'employee_code',w.employee_code
  )
  INTO v_before
  FROM public.enterprise_workforce_workers w
  WHERE w.id = p_worker_id
    AND w.enterprise_id = p_enterprise_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','worker_not_found');
  END IF;

  UPDATE public.enterprise_workforce_workers
  SET display_label=v_label,
      employee_code=v_code,
      status=p_status,
      all_sites=COALESCE(p_all_sites,false),
      max_concurrent_jobs=p_max_concurrent_jobs,
      updated_at=now()
  WHERE id=p_worker_id;

  PERFORM fixeo_private._write_enterprise_audit_event(
    p_enterprise_id,
    'workforce.worker_updated',
    'enterprise_workforce_worker',
    p_worker_id,
    v_before,
    pg_catalog.jsonb_build_object(
      'status',p_status,
      'all_sites',COALESCE(p_all_sites,false),
      'max_concurrent_jobs',p_max_concurrent_jobs,
      'display_label',v_label,
      'employee_code',v_code
    ),
    '{}'::jsonb
  );

  RETURN pg_catalog.jsonb_build_object('ok',true,'worker_id',p_worker_id);

EXCEPTION
  WHEN unique_violation THEN
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','employee_code_exists');
  WHEN OTHERS THEN
    RAISE WARNING '[update_enterprise_workforce_worker] % %', SQLSTATE, SQLERRM;
    RETURN pg_catalog.jsonb_build_object('ok',false,'reason','internal_error');
END;
$function$

CREATE OR REPLACE FUNCTION public.update_my_artisan_activity_v1(p_services text[], p_cities text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid:=auth.uid(); v_artisan_id uuid; v_services text[]; v_cities text[];
begin
 if v_uid is null then return jsonb_build_object('ok',false,'reason','unauthenticated'); end if;
 if not exists(select 1 from public.users u where u.id=v_uid and u.role='artisan') then return jsonb_build_object('ok',false,'reason','artisan_role_required'); end if;
 select a.id into v_artisan_id from public.artisans a where a.owner_user_id=v_uid limit 1 for update;
 if v_artisan_id is null then return jsonb_build_object('ok',false,'reason','artisan_not_found'); end if;
 select coalesce(array_agg(distinct trim(x)) filter(where trim(x)<>''),'{}'::text[]) into v_services from unnest(coalesce(p_services,'{}'::text[]))x;
 select coalesce(array_agg(distinct trim(x)) filter(where trim(x)<>''),'{}'::text[]) into v_cities from unnest(coalesce(p_cities,'{}'::text[]))x;
 if cardinality(v_services)=0 or cardinality(v_cities)=0 then return jsonb_build_object('ok',false,'reason','service_and_city_required'); end if;
 if cardinality(v_services)>12 or cardinality(v_cities)>20 then return jsonb_build_object('ok',false,'reason','too_many_values'); end if;
 delete from public.artisan_service_categories where artisan_id=v_artisan_id;
 insert into public.artisan_service_categories(artisan_id,service_category) select v_artisan_id,x from unnest(v_services)x;
 delete from public.artisan_service_cities where artisan_id=v_artisan_id;
 insert into public.artisan_service_cities(artisan_id,city) select v_artisan_id,x from unnest(v_cities)x;
 update public.artisans set service_category=v_services[1],category=v_services[1],services=to_jsonb(v_services),city=v_cities[1],work_zone=array_to_string(v_cities,', '),updated_at=now() where id=v_artisan_id;
 update public.profiles set city=v_cities[1] where id=v_uid;
 update public.users set city=v_cities[1] where id=v_uid;
 return jsonb_build_object('ok',true,'services',to_jsonb(v_services),'cities',to_jsonb(v_cities));
end $function$

CREATE OR REPLACE FUNCTION public.update_my_artisan_contact_v1(p_phone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_digits text;
  v_phone text;
  v_artisan_id uuid;
begin
  if v_uid is null then
    return jsonb_build_object('ok',false,'reason','unauthenticated');
  end if;

  select a.id into v_artisan_id
  from public.artisans a
  where a.owner_user_id = v_uid
  limit 1
  for update;

  if v_artisan_id is null then
    return jsonb_build_object('ok',false,'reason','artisan_not_found');
  end if;

  v_digits := regexp_replace(coalesce(p_phone,''), '[^0-9]', '', 'g');

  if v_digits ~ '^212[5-7][0-9]{8}$' then
    v_phone := '0' || substr(v_digits,4);
  elsif v_digits ~ '^[5-7][0-9]{8}$' then
    v_phone := '0' || v_digits;
  elsif v_digits ~ '^0[5-7][0-9]{8}$' then
    v_phone := v_digits;
  else
    return jsonb_build_object(
      'ok',false,
      'reason','invalid_phone',
      'message','Numéro marocain invalide.'
    );
  end if;

  update public.users
  set phone = v_phone
  where id = v_uid;

  update public.profiles
  set phone = v_phone
  where id = v_uid;

  update public.artisans
  set phone = v_phone,
      phone_public = v_phone,
      updated_at = now()
  where id = v_artisan_id
    and owner_user_id = v_uid;

  return jsonb_build_object(
    'ok',true,
    'phone',v_phone,
    'artisan_id',v_artisan_id
  );
end
$function$

CREATE OR REPLACE FUNCTION public.upsert_enterprise_approval_policy_v1(p_enterprise_id uuid, p_policy_id uuid, p_name text, p_site_id uuid, p_service_category text, p_urgency text, p_requester_role text, p_min_amount numeric, p_max_amount numeric, p_priority integer, p_status text, p_steps jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_id uuid; v_before jsonb; v_event text; v_item jsonb; v_order integer:=0;
  v_role text; v_count integer:=0; v_category text:=NULLIF(lower(btrim(p_service_category)),'');
BEGIN
  IF auth.uid() IS NULL THEN RETURN jsonb_build_object('ok',false,'reason','unauthenticated'); END IF;
  IF NOT fixeo_private._fixeo_is_enterprise_manager(p_enterprise_id) THEN RETURN jsonb_build_object('ok',false,'reason','forbidden'); END IF;
  IF p_site_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.enterprise_sites s WHERE s.id=p_site_id AND s.enterprise_id=p_enterprise_id) THEN RETURN jsonb_build_object('ok',false,'reason','site_not_found'); END IF;
  IF btrim(p_name) IS NULL OR char_length(btrim(p_name)) NOT BETWEEN 1 AND 200 THEN RETURN jsonb_build_object('ok',false,'reason','invalid_name'); END IF;
  IF p_urgency IS NOT NULL AND p_urgency NOT IN ('normale','urgent','now') THEN RETURN jsonb_build_object('ok',false,'reason','invalid_urgency'); END IF;
  IF p_requester_role IS NOT NULL AND p_requester_role NOT IN ('owner','admin','operations_manager','site_manager','reporter') THEN RETURN jsonb_build_object('ok',false,'reason','invalid_requester_role'); END IF;
  IF p_min_amount IS NOT NULL AND p_min_amount<0 OR p_max_amount IS NOT NULL AND p_max_amount<0 OR p_min_amount IS NOT NULL AND p_max_amount IS NOT NULL AND p_max_amount<p_min_amount THEN RETURN jsonb_build_object('ok',false,'reason','invalid_amount_range'); END IF;
  IF p_priority IS NULL OR p_priority NOT BETWEEN 1 AND 10000 THEN RETURN jsonb_build_object('ok',false,'reason','invalid_priority'); END IF;
  IF p_status NOT IN ('active','inactive') THEN RETURN jsonb_build_object('ok',false,'reason','invalid_status'); END IF;
  IF p_steps IS NULL OR jsonb_typeof(p_steps)<>'array' OR jsonb_array_length(p_steps)<1 OR jsonb_array_length(p_steps)>10 THEN RETURN jsonb_build_object('ok',false,'reason','invalid_steps'); END IF;

  v_count:=0;
  FOR v_item IN SELECT value FROM jsonb_array_elements(p_steps)
  LOOP
    v_count:=v_count+1;
    BEGIN
      v_order:=COALESCE((v_item->>'step_order')::integer,v_count);
    EXCEPTION WHEN OTHERS THEN
      RETURN jsonb_build_object('ok',false,'reason','invalid_step_order');
    END;
    v_role:=v_item->>'approver_role';
    IF v_order<>v_count OR v_role NOT IN ('owner','admin','operations_manager','site_manager') THEN
      RETURN jsonb_build_object('ok',false,'reason','invalid_step');
    END IF;
  END LOOP;

  IF p_policy_id IS NULL THEN
    INSERT INTO public.enterprise_approval_policies(
      enterprise_id,name,site_id,service_category,urgency,requester_role,min_amount,max_amount,priority,status,created_by,updated_by
    ) VALUES(
      p_enterprise_id,btrim(p_name),p_site_id,v_category,p_urgency,p_requester_role,p_min_amount,p_max_amount,p_priority,p_status,auth.uid(),auth.uid()
    ) RETURNING id INTO v_id;
    v_event:='governance.policy_created';
  ELSE
    SELECT to_jsonb(p) INTO v_before FROM public.enterprise_approval_policies p
    WHERE p.id=p_policy_id AND p.enterprise_id=p_enterprise_id FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'reason','policy_not_found'); END IF;
    UPDATE public.enterprise_approval_policies SET
      name=btrim(p_name),site_id=p_site_id,service_category=v_category,urgency=p_urgency,requester_role=p_requester_role,
      min_amount=p_min_amount,max_amount=p_max_amount,priority=p_priority,status=p_status,updated_by=auth.uid(),updated_at=now()
    WHERE id=p_policy_id RETURNING id INTO v_id;
    DELETE FROM public.enterprise_approval_policy_steps WHERE policy_id=v_id;
    v_event:='governance.policy_updated';
  END IF;

  v_count:=0;
  FOR v_item IN SELECT value FROM jsonb_array_elements(p_steps)
  LOOP
    v_count:=v_count+1;
    v_order:=v_count;
    v_role:=v_item->>'approver_role';
    INSERT INTO public.enterprise_approval_policy_steps(enterprise_id,policy_id,step_order,approver_role)
    VALUES(p_enterprise_id,v_id,v_order,v_role);
  END LOOP;

  PERFORM fixeo_private._write_enterprise_audit_event(
    p_enterprise_id,v_event,'enterprise_approval_policy',v_id,v_before,
    jsonb_build_object('site_id',p_site_id,'service_category',v_category,'urgency',p_urgency,'requester_role',p_requester_role,
      'min_amount',p_min_amount,'max_amount',p_max_amount,'priority',p_priority,'status',p_status,'step_count',v_count),
    jsonb_build_object('name',btrim(p_name))
  );
  RETURN jsonb_build_object('ok',true,'policy_id',v_id,'step_count',v_count);
EXCEPTION WHEN unique_violation THEN
  RETURN jsonb_build_object('ok',false,'reason','duplicate_step');
WHEN OTHERS THEN
  RAISE WARNING '[upsert_enterprise_approval_policy_v1] % %',SQLSTATE,SQLERRM;
  RETURN jsonb_build_object('ok',false,'reason','internal_error');
END;
$function$

CREATE OR REPLACE FUNCTION public.upsert_enterprise_budget_v1(p_enterprise_id uuid, p_budget_id uuid, p_cost_center_id uuid, p_period_start date, p_period_end date, p_amount numeric, p_status text)
